-- SRS review-card backfill — BATCH 1 of 10 (849 rows).
-- Run each batch on its own in the Supabase SQL Editor; order does not matter and
-- each is idempotent. Together the 10 batches equal backfill_srs_payload.sql.
-- Covers Top 2 preboards/mocks/reviewer + main-app banks + Top 2 banks.
WITH d(qid, patch) AS (
  VALUES
  ('4827201a-20','{"options": ["Sleek", "Bruise check", "Scratch", "Drag mark"], "correct": 0, "explanation": "A sleek is a fine, elongated hairline penetration/scratch in the lens surface that does not chip or splinter the material. A drag mark is left by dragging debris, a bruise is a subsurface indentation, and ''scratch'' is the generic term. VERIFY: lab-defect terminology varies, so confirm against the source; ''sleek'' is the classic term for a clean hairline penetration."}'),
  ('ac4166e2-2x','{"options": ["23%", "8.8%", "5.3%", "4.5%"], "correct": 2, "explanation": "Fresnel reflectance at one surface = ((n-1)/(n+1))^2 = (0.60/2.60)^2 = (0.2308)^2 = 0.0533, about 5.3%. Higher index means more surface reflection (why AR coating matters). R = ((n-1)/(n+1))^2 per surface."}'),
  ('a9430522-1f','{"options": ["size is magnified", "image is located closer", "image is located farther", "size is minified"], "correct": 3, "explanation": "A magnification below 1.0 means the image is SMALLER than the object, that is, minified. Magnification above 1.0 magnifies. |m| < 1 = smaller image."}'),
  ('94cc731e-34','{"options": ["BC 7.8 mm", "BC 7.9 mm", "BC 8.0 mm", "BC 8.1 mm"], "correct": 3, "explanation": "The trial lens with an 8.1 mm base curve fit acceptably, so the prescribed base curve stays 8.1 mm; the -1.00 D over-refraction is simply incorporated into the lens POWER, not the base curve. VERIFY: if the intent were to alter fit via base curve, the mm would change, but a plain over-refraction is a power adjustment at the same BC."}'),
  ('00a4463c-4o','{"options": ["Angle of dispersion", "index of refraction", "index of dispersion", "Abbe Value"], "correct": 3, "explanation": "The Abbe value (V-number) quantifies chromatic dispersion: a LOW Abbe number means the material spreads white light into colors more (more chromatic aberration). Index of refraction sets bending power, not dispersion. Abbe = the dispersion yardstick (low Abbe = more color spread)."}'),
  ('427c93d4-1m','{"options": ["weaker", "stronger", "plano", "toroidal"], "correct": 0, "explanation": "Moving a MINUS lens away from the eye reduces its effective power at the cornea (F_eff = F/(1-dF); for negative F, a larger d shrinks the magnitude), so it becomes weaker. This is why more minus is needed at a longer vertex distance. Minus lens out = weaker effect."}'),
  ('393fba9e-2z','{"options": ["-5.50 D", "-3.52 D", "-4.68 D", "-4.25 D"], "correct": 2, "explanation": "Power in a meridian = Sphere + Cyl x sin^2(meridian - axis). For the 180 meridian with axis 125: sin^2(55) = 0.671, so -3.00 + (-2.50)(0.671) = -3.00 - 1.68 = -4.68 D. Meridional power formula: S + C sin^2(theta - axis)."}'),
  ('8e8e47e5-3r','{"options": ["+12.37 D", "+19.00 D", "+12.75 D", "+18.25 D"], "correct": 1, "explanation": "Effective power at the cornea = F/(1 - dF) = 15/(1 - 0.014 x 15) = 15/0.79 = 19.0 D. A plus lens moved toward the eye (spectacle to cornea) gains power. Aphakic plus at the cornea = stronger."}'),
  ('0b67ae37-1k','{"options": ["Basophils aggregation", "Lymphocytes aggregation", "Monocytes aggregation", "Neutrophils aggregation"], "correct": 1, "explanation": "Follicles are aggregations of LYMPHOCYTES (lymphoid tissue) in the conjunctiva, seen in viral and chlamydial conjunctivitis. Neutrophil-driven reactions form papillae instead. Follicles = lymphocytes; papillae = polymorphs/vessels."}'),
  ('2db22bf2-2a','{"options": ["1 day", "5 days", "7 days", "3 days"], "correct": 2, "explanation": "Corneal epithelial cells migrate from the basal layer to the surface and slough in about 7 days, the epithelial turnover time. This rapid renewal is why superficial epithelial defects heal quickly. Corneal epithelium renews about weekly."}'),
  ('43a759e6-15','{"options": ["lens wear", "ionicity of material", "tear component", "contact lens water content"], "correct": 1, "explanation": "Protein deposition on a soft lens depends mainly on the IONICITY of the material: ionic (negatively charged) lenses attract positively charged tear proteins like lysozyme. Non-ionic materials resist protein but attract lipids. Ionic lens = protein magnet."}'),
  ('13121ba5-23','{"options": ["Aspheric", "Spherical", "Monocurve", "Tapered"], "correct": 0, "explanation": "An ASPHERIC lens gradually flattens toward the periphery, which reduces spherical aberration and peripheral distortion compared with a spherical lens. Aspheric = flatter periphery = fewer off-axis aberrations."}'),
  ('7702fdf4-1m','{"options": ["displaced toward the base", "displaced up", "displaced toward the apex", "displaced down"], "correct": 2, "explanation": "A prism bends light toward its BASE, so the image appears shifted toward the APEX. (The eye must turn toward the apex to fixate the displaced image.) Light bends to the base, image shifts to the apex."}'),
  ('3f214ee7-25','{"options": ["Absorption", "Reflection", "Diffraction", "Refraction"], "correct": 0, "explanation": "If the photon enters but never leaves, its energy has been taken up by the material: absorption. Reflection bounces it back, refraction bends it through, and diffraction spreads it around edges. Enters and stays = absorbed."}'),
  ('1db9cabd-24','{"options": ["corneal edema", "lens warpage", "lens breakage", "corneal desiccation"], "correct": 3, "explanation": "High-water, thin lenses lose water rapidly and draw moisture from the tear film and cornea, producing corneal desiccation (and inferior staining). VERIFY: thin high-water lenses are also fragile (breakage), so the item is arguable; the classic physiologic consequence is corneal desiccation from lens dehydration."}'),
  ('8c6606f1-3e','{"options": ["1.5 cm", "1.5 m", "5.4 m", "54 cm"], "correct": 1, "explanation": "Prism displacement (cm) = prism power (prism diopters) x distance (m), so distance = displacement/power = 9/6 = 1.5 m. A prism displaces the image 1 cm per prism diopter per meter. Distance = 9 cm / 6 pd = 1.5 m."}'),
  ('758cef28-2o','{"options": ["Torsional", "With", "Scissors", "Against"], "correct": 3, "explanation": "A PLUS lens shows AGAINST motion: move the lens down and the object appears to move up (opposite). A minus lens shows WITH motion. Plus = against; minus = with."}'),
  ('4bba60fb-21','{"options": ["7.67 mm", "7.50 mm", "7.00 mm", "7.75 mm"], "correct": 0, "explanation": "Using the keratometer index 1.3375: r = (n-1)/F = 0.3375/44 = 0.00767 m = 7.67 mm. r = (1.3375 - 1)/K in meters."}'),
  ('6dbbe1d7-3b','{"options": ["+2.50 D", "-1.50 D", "+1.50 D", "-2.50 D"], "correct": 0, "explanation": "16 inches = 0.4064 m, so F = 1/0.4064 = +2.46, about +2.50 D. It is PLUS because it converges parallel rays to a real focus. Power = 1/focal length (m); converging = plus."}'),
  ('8c5557b9-3m','{"options": ["front vertex power", "effective power", "back vertex power", "equivalent power"], "correct": 2, "explanation": "With the BACK surface against the lensmeter stop (the standard way for spectacle lenses), you read the BACK vertex power, the value that matters at the eye. Turning the lens over gives front vertex power. Back against stop = back vertex power."}'),
  ('a07385fb-2g','{"options": ["ionic lens", "soft lens", "gas permeable lens", "nonionic lens"], "correct": 0, "explanation": "IONIC materials (charged) are more wettable but their surface charge attracts protein, so they are more prone to deposits. Non-ionic materials resist protein deposition. Ionic = wettable but deposit-prone."}'),
  ('73a5df50-1t','{"options": ["with lenticular back area", "an increased bowl diameter", "with decreased minus lens power", "a plano back carrier"], "correct": 0, "explanation": "A myodisc confines the high minus power to a central concave ''bowl'' on the back (a lenticular back area) surrounded by a flatter carrier, keeping the edges thin and light. VERIFY: the surrounding carrier is often described as plano, so option D overlaps; the defining feature is the lenticular (bowl) back."}'),
  ('8ddb77f6-1r','{"options": ["refraction", "vergence", "reflection", "dispersion"], "correct": 0, "explanation": "Lenses work by REFRACTION: bending light at their curved surfaces to change its vergence and form an image. Reflection is mirrors, dispersion splits colors, and vergence describes the light''s convergence/divergence state. Lenses refract."}'),
  ('e0d37e5d-1n','{"options": ["Anxiety", "Noise", "Dry atmosphere", "Stuffy atmosphere"], "correct": 1, "explanation": "Blink rate rises with emotional state (anxiety) and ocular-surface irritation (dry or stuffy air). NOISE, a purely auditory stimulus, does not directly change the blink rate, so it is the exception. VERIFY: startling noise can trigger reflex blinks, so the item is arguable."}'),
  ('8b93954b-2o','{"options": ["Glaucoma", "Central corneal opacities", "Pathological myopia", "Optic atrophy"], "correct": 1, "explanation": "With CENTRAL corneal (or lens) opacities, dim light dilates the pupil so more rays pass AROUND the central opacity, improving vision. Bright light constricts the pupil onto the opacity and worsens vision (day blindness). Central opacity = better in dim light (bigger pupil bypasses it)."}'),
  ('2dce7761-36','{"options": ["No change in illumination", "Decreases in intensity", "Increases in intensity", "Illumination becomes smaller"], "correct": 1, "explanation": "By the inverse-square law, illuminance falls as the square of the distance, so moving the source farther away DECREASES the intensity reaching the eye. Illuminance is proportional to 1/distance^2."}'),
  ('1d752844-1p','{"options": ["+44.44 cms", "+28.57 cms", "+33.33 cms", "+23.53 cms"], "correct": 1, "explanation": "Focal length = 1/power = 1/3.50 = 0.2857 m = 28.57 cm. f (cm) = 100/D."}'),
  ('2a65a678-23','{"options": ["Hydrogel", "Methane gas", "Elastomers", "Ethylene"], "correct": 1, "explanation": "Silicone (elastomer) lens surfaces are made wettable by gas-plasma treatment, using a reactive gas such as methane (or oxygen) plasma to graft a hydrophilic layer. VERIFY: the specific plasma gas varies by manufacturer; a gas plasma (not a hydrogel or elastomer) is the treatment."}'),
  ('ea73c06e-3r','{"options": ["+9.50 D", "+8.50 D", "+8.00 D", "+9.00 D"], "correct": 3, "explanation": "Effective power at the cornea = F/(1 - dF) = 8/(1 - 0.014 x 8) = 8/0.888 = 9.0 D. A plus lens moved to the cornea gains power. Hyperopic plus at the cornea = stronger."}'),
  ('19000da9-5h','{"options": ["+5.00 DS -3.00 DCyl x 150", "-5.00 DS +3.00 DCyl x 60", "-2.00 DS -3.00 DCyl x 60", "+2.00 DS +3.00 DCyl x 150"], "correct": 2, "explanation": "The lens power in each meridian equals the neutralizing lens: -5.00 at 150 and -2.00 at 60. In minus-cyl form the sphere is the less-minus meridian (-2.00, at 60), the cyl is -5.00 minus -2.00 = -3.00, and the axis lies along the sphere-only meridian (60). So -2.00 DS -3.00 DCyl x 60. Check: at 60 = -2.00, at 150 = -2.00 + -3.00 = -5.00."}'),
  ('8da7d2a2-1o','{"options": ["substantial loss of photoreceptors", "subretinal gliosis", "all of these", "hemorrhage"], "correct": 2, "explanation": "A positive scotoma (a dark patch the patient actively sees) arises from lesions at or in front of the photoreceptors that block/scatter light, including subretinal gliosis, hemorrhage, and marked photoreceptor loss, so ''all of these'' fits. VERIFY: strictly, pure photoreceptor loss often gives a negative scotoma, so the grouping is loose."}'),
  ('14e674b2-20','{"options": ["working distance is 40 cms", "working distance is 20 cms", "accommodation is paralyzed", "accommodation is active"], "correct": 0, "explanation": "Tentative near-add formulas assume a standard 40 cm (16 inch) working distance, at which the near demand is 2.50 D. VERIFY: this item''s ''Brazelton'' label is unusual (Brazelton is a neonatal scale), so the reference is uncertain; the 40 cm working-distance assumption is the standard basis for a tentative add."}'),
  ('205b5746-1n','{"options": ["Square", "Oval", "Round", "Oblong"], "correct": 1, "explanation": "The OVAL face is the balanced ''ideal'' that suits almost any frame shape, so most styles flatter it. Square, round, and oblong faces need frames chosen to offset their proportions. Oval face = fits nearly all frames."}'),
  ('541e037b-1r','{"options": ["7.9 mms", "7.3 mms", "7.7 mms", "7.5 mms"], "correct": 3, "explanation": "Using the keratometer index 1.3375: r = 0.3375/45 = 0.0075 m = 7.5 mm. r = (1.3375 - 1)/K."}'),
  ('5ad3b07e-2x','{"options": ["point incident on lens", "point emerging from lens", "right of the lens", "left of the lens"], "correct": 2, "explanation": "For a DIVERGING (minus) lens with light traveling left to right, the primary focal point is VIRTUAL and lies on the far (right) side of the lens (the point from which incident rays would have to appear to converge to emerge parallel). VERIFY: sign/side conventions vary between texts, so confirm the intended diagram. Minus lens F1 = virtual, image side."}'),
  ('f5abab26-1r','{"options": ["Its curvature flattens posteriorly", "It is not symmetrical in one eye", "It is symmetrical in both eyes", "Its curvature flattens towards periphery"], "correct": 3, "explanation": "The cornea is prolate: steepest centrally and progressively FLATTER toward the periphery. This peripheral flattening reduces spherical aberration. Cornea flattens outward from the apex."}'),
  ('1c4aa2c8-2k','{"options": ["skull", "riding bow", "convertible", "library"], "correct": 1, "explanation": "The RIDING BOW temple curves fully around the back of the ear for a secure grip, ideal for children''s and safety frames. Skull temples rest straight over the ear, and library temples are straight to slip on/off. Wraps the ear = riding bow."}'),
  ('0149c34b-2k','{"options": ["Sclero-corneal", "Oculo-facial", "Shell eye", "Reform eye"], "correct": 1, "explanation": "Exenteration removes the entire orbital contents (and often lids), leaving a large defect, so an OCULO-FACIAL (orbital) prosthesis that restores the eye plus surrounding facial tissue is used. A shell/reform eye suits a retained globe or socket. Big facial defect = oculofacial prosthesis."}'),
  ('c7764e5f-1l','{"options": ["Pseudomonas aeruginosa", "Serratia marcescens", "Staphylococcus aureus", "Fusarium solani"], "correct": 3, "explanation": "Fusarium solani is a FUNGUS (a cause of fungal keratitis, notably linked to contact-lens solution outbreaks). The other three are bacteria. Fusarium = fungus, not bacteria."}'),
  ('9a9cdbf0-1y','{"options": ["10", "20", "50", "100"], "correct": 3, "explanation": "Focal length = 1/power = 1/1.00 = 1 m = 100 cm. A 1.00 D lens focuses at 1 meter. f (cm) = 100/D."}'),
  ('2e8dfef0-3d','{"options": ["7.67 mms", "7.46 mms", "7.91 mms", "7.85 mms"], "correct": 3, "explanation": "Taking the corneal power near 43 D (about two-thirds of the eye''s ~60 D): r = 0.3375/43 = 0.00785 m = 7.85 mm. VERIFY: the exact radius depends on the corneal-power value used (43 to 45 D), so the answer shifts a little with that assumption. r = (1.3375 - 1)/K."}'),
  ('4616c700-2u','{"options": ["Deep frame with low temple", "Round frame with dark color", "Narrow frame with high temple", "Square frame with mid temple"], "correct": 0, "explanation": "An oblong (long) face is balanced by a DEEP frame with LOW-set temples, which add apparent width and break up the vertical length. VERIFY: frame-fitting guidance is a matter of style convention; a deeper frame that shortens a long face is the standard recommendation."}'),
  ('3d30d451-1x','{"options": ["increase", "decrease", "magnify", "minify"], "correct": 1, "explanation": "As with the earlier item, moving a minus lens farther from the eye DECREASES its effective power at the cornea. Minus lens out = weaker effect (F_eff = F/(1-dF))."}'),
  ('f596d982-23','{"options": ["1300 nm and above", "760 nm to 850 nm", "380 nm to 760 nm", "280 nm to 380 nm"], "correct": 2, "explanation": "Visible light spans roughly 380 nm (violet) to 760 nm (red). Below that is ultraviolet, above is infrared. Visible = about 380 to 760 nm."}'),
  ('36bace2d-2h','{"options": ["Spin casting", "Lathe cutting", "Stabilized soft molding", "Cast molding"], "correct": 3, "explanation": "CAST MOLDING presses the lens between precision molds, reproducing complex front and back geometries (aspherics, torics, multifocals) consistently and at scale. VERIFY: lathe cutting allows custom one-off complex designs, so ''best'' depends on whether the emphasis is mass reproducibility (cast molding) or customization (lathe)."}'),
  ('5493090c-1w','{"options": ["its impact resistance", "lesser aberration", "low chromatic aberration", "reduce lens thickness"], "correct": 3, "explanation": "Higher-index materials bend light more per unit thickness, so the lens can be made THINNER (and flatter) for the same power. Impact resistance and chromatic aberration actually tend to WORSEN at high index. High index = thinner lenses."}'),
  ('dba008c8-n','{"options": ["with motion", "against motion", "scissors motion", "no motion"], "correct": 1, "explanation": "A converging (plus) lens shows AGAINST motion on the rock test: move the lens one way and the image shifts the opposite way. Diverging (minus) lenses show WITH motion. Plus = against."}'),
  ('04e3c8ec-3r','{"options": ["linear magnification", "transverse magnification", "angular magnification", "axial magnification"], "correct": 0, "explanation": "The ratio of image height to object height (both measured perpendicular to the axis) is the LINEAR (also called transverse/lateral) magnification, m = h''/h. VERIFY: ''linear'' and ''transverse'' are synonyms and both appear as options, making the item loose; angular and axial magnifications describe different quantities."}'),
  ('e875a1c4-3y','{"options": ["Enucleation", "Cosmetic", "Exenteration", "Evisceration"], "correct": 3, "explanation": "EVISCERATION removes the intraocular contents while leaving the scleral shell (and orbit) in place. Enucleation removes the whole globe, and exenteration removes the entire orbital contents. Scoop out the inside, keep the shell = evisceration."}'),
  ('ab053519-3w','{"options": ["20/30", "20/40", "20/20", "20/50"], "correct": 1, "explanation": "Doubling the distance halves the angular size of the letters, so a letter readable at 10 ft as 20/20 now subtends half as much and the patient can only resolve a letter twice as large: 20/40. Twice the distance = twice the letter size needed = 20/40."}'),
  ('5d0d514e-34','{"options": ["Proteolytic enzymes", "Saline solution", "Ethylene diamine tetra acetate", "Benzalkonium chloride"], "correct": 0, "explanation": "PROTEOLYTIC (enzymatic) cleaners digest and remove the protein deposits that build up over a week. Saline only rinses, EDTA is a chelating/preservative aid, and benzalkonium is a preservative/disinfectant. Weekly protein removal = enzyme cleaner."}'),
  ('fa2f9651-2i','{"options": ["-2.50 D", "-2.00 D", "-1.00 D", "-3.00 D"], "correct": 0, "explanation": "Spherical equivalent = sphere + (cyl/2) = -2.00 + (-1.00/2) = -2.50 D. SE = sphere plus half the cylinder."}'),
  ('a121a0af-1l','{"options": ["15 percent", "1.53", "30 percent", "1.17"], "correct": 3, "explanation": "Opacity is the reciprocal of transmittance: 1/0.85 = 1.17. (It is not simply 100 minus transmission, which would be absorption.) Opacity = 1/transmittance."}'),
  ('91ddaf07-2z','{"options": ["+2.25 DS +1.25 DC x 15", "+3.50 DS +1.25 DC x 15", "+2.25 DS +1.25 DC x 105", "+3.50 DS +1.25 DC x 105"], "correct": 2, "explanation": "Transposition: new sphere = 3.50 + (-1.25) = +2.25; new cyl = +1.25 (sign flipped); new axis = 15 + 90 = 105. So +2.25 DS +1.25 DC x 105. Add cyl to sphere, flip cyl sign, rotate axis 90."}'),
  ('4a22e811-2q','{"options": ["steep fitting", "central pooling", "flat fitting lens", "with edge lift"], "correct": 0, "explanation": "Clear vision momentarily after the blink that then blurs suggests a STEEP (tight) fit: the blink briefly recenters/refreshes the tear film, then the tight lens settles and vision degrades. VERIFY: soft-lens fit interpretation from blink-related clarity is subtle and can vary; steep fits classically clear briefly post-blink."}'),
  ('6e4b6442-3f','{"options": ["scissors", "with parallax", "against parallax", "no parallax"], "correct": 1, "explanation": "A concave (minus) lens shows WITH motion (with parallax): the image moves in the SAME direction as the lens. A plus lens shows against motion. Minus = with; plus = against."}'),
  ('9ef4f72e-19','{"options": ["Forced hot air", "Hot water", "Glass beads", "Sand in a hot tray"], "correct": 0, "explanation": "Nylon frames are best warmed with FORCED HOT AIR (a frame warmer/blower), which heats evenly without the moisture or hot spots of water, beads, or sand. VERIFY: salt/bead pans are also used for some plastics; for nylon, dry hot air is the safe standard."}'),
  ('30bb7b1e-1p','{"options": ["Pancreatin", "Mucin balls", "Subtilisin", "Biofilm"], "correct": 3, "explanation": "Microbes secrete a sticky glycocalyx (extracellular polysaccharide) that binds them into a protective BIOFILM, a major problem on lens cases and lenses. Glycocalyx colony = biofilm."}'),
  ('5d194857-u','{"options": ["-9.25 DS / -11.75 DC x 35", "+6.75 DS / +2.50 DC x 125", "+6.75 DS / -2.50 DC x 125", "+9.25 DS / -11.75 DC x 35"], "correct": 1, "explanation": "New sphere = 9.25 + (-2.50) = +6.75; new cyl = +2.50; new axis = 35 + 90 = 125. So +6.75 DS / +2.50 DC x 125. Sphere + cyl, flip cyl sign, axis + 90."}'),
  ('b98123a3-1s','{"options": ["Dk 24", "Dk 120", "Dk 87", "Dk 135"], "correct": 2, "explanation": "By the Holden-Mertz criteria, a Dk/t of about 87 is the minimum for extended (overnight) wear to avoid corneal edema. Dk/t about 24 to 35 suffices for daily wear. Extended wear needs roughly 87; daily wear far less."}'),
  ('b13d520f-1u','{"options": ["5 feet", "10 feet", "6 meters", "3 meters"], "correct": 2, "explanation": "Optical infinity is taken as 6 meters (about 20 feet): beyond this, incoming light is effectively parallel (vergence under 0.17 D) so the eye is essentially relaxed. Optical infinity = 6 m / 20 ft."}'),
  ('94ed50c7-1z','{"options": ["filcon", "fluorine", "polymacon", "focon"], "correct": 3, "explanation": "Rigid (hydrophobic) contact lens materials carry the USAN stem ''-focon'' (for example, silafocon, itafocon). The ''-filcon'' stem denotes hydrophilic (soft) materials. Rigid = focon; soft = filcon."}'),
  ('d5134bf3-2d','{"options": ["8.4 mm", "7.7 mm", "8.0 mm", "8.1 mm"], "correct": 0, "explanation": "Overall diameter = optic zone + both peripheral curve widths on each side = OZD + 2(SCW) + 2(PCW) = 7.0 + 2(0.4) + 2(0.3) = 7.0 + 0.8 + 0.6 = 8.4 mm. OAD = OZD + 2(SCW) + 2(PCW)."}'),
  ('4f2c58c3-2k','{"options": ["+1.00 D", "+0.50 D", "+2.25 D", "+2.00 D"], "correct": 0, "explanation": "Spherical equivalent = sphere + cyl/2 = +1.50 + (-1.00/2) = +1.00 D. SE = sphere plus half the cylinder."}'),
  ('b6f50a27-2k','{"options": ["reduce visual acuity mainly through light scattering at the groove edges", "they are made up of a series of small prisms", "are usually applied to the front of patients'' glasses", "they are thicker than conventional prisms"], "correct": 1, "explanation": "A Fresnel prism is a thin membrane made of a SERIES of small parallel prisms, giving prism power with minimal thickness/weight. It is thinner (not thicker) than a conventional prism and is applied to the BACK of the lens; the groove scattering (which does reduce acuity a little) is a side effect, not the best definition. Fresnel = many tiny prisms on a thin sheet."}'),
  ('50535060-27','{"options": ["prism reference point", "fitting cross", "near reference point", "distance reference point"], "correct": 0, "explanation": "The major reference point (MRP) of a progressive lens is the prism reference point, where the prescribed/prism-thinning prism is verified. VERIFY: PAL nomenclature varies by manufacturer (fitting cross, DRP, NRP, PRP), so confirm against the specific lens; MRP is classically the prism reference point."}'),
  ('6f63429f-2o','{"options": ["6 X", "3 X", "12 X", "9 X"], "correct": 3, "explanation": "Axial (longitudinal) magnification equals the SQUARE of the lateral magnification: 3^2 = 9X. Axial mag = (lateral mag)^2."}'),
  ('0596d1fb-3c','{"options": ["higher", "lower", "multiple", "increasing"], "correct": 1, "explanation": "Fluorescence obeys the Stokes shift: the molecule absorbs higher-energy blue light and re-emits LOWER-energy (longer-wavelength) green light, some energy being lost as heat. Emitted light has lower energy than absorbed."}'),
  ('c3c1952a-2j','{"options": ["75", "88", "12", "99.5"], "correct": 1, "explanation": "Each surface reflects ((n-1)/(n+1))^2 = (0.66/2.66)^2 = 6.2%, so two surfaces lose about 12%, leaving roughly 88% transmitted (before AR coating). Two-surface reflection loss at n=1.66 is about 12%."}'),
  ('3c4c1557-13','{"options": ["adds negative vergence to reflected rays", "adds positive vergence to reflected rays", "does not change the vergence of its reflected rays", "demonstrates total internal reflection"], "correct": 2, "explanation": "A PLANE mirror only reverses the direction of light; it has no power, so it does NOT change the vergence (a flat mirror neither converges nor diverges). Curved mirrors change vergence. Flat mirror = no vergence change."}'),
  ('184022c9-1r','{"options": ["The surface is hollow.", "It diverges parallel incident rays.", "The surface increases the vergence of light.", "Flat edge placed on the surface will not rock."], "correct": 2, "explanation": "A concave (minus) refracting surface DIVERGES light, adding negative vergence, so ''increases the vergence'' is not a characteristic. VERIFY: option D is also questionable (a flat edge WOULD rock on a curved surface), so the item has more than one imperfect statement; the clearest non-characteristic is that a concave surface does not increase vergence."}'),
  ('e3f6ec0d-2d','{"options": ["1.336", "1.376", "1.3375", "1.367"], "correct": 1, "explanation": "The true refractive index of corneal tissue is 1.376. The value 1.3375 is the keratometer''s calibrated index (which lumps in the tear film and posterior surface), and 1.336 is the aqueous. Actual cornea = 1.376; keratometer uses 1.3375."}'),
  ('180f661e-1s','{"options": ["3%", "4%", "2%", "1%"], "correct": 3, "explanation": "Optical density (OD) = log10(1/T), so T = 10^(-OD) = 10^-2 = 0.01 = 1%. OD 2.0 means only 1% of light is transmitted. T = 10^(-OD)."}'),
  ('3ec070d4-2q','{"options": ["8x", "4x", "3x", "2x"], "correct": 2, "explanation": "Maximum magnification (image at the near point) = F/4 + 1 = 8/4 + 1 = 3X. (Relaxed, image at infinity, it would be F/4 = 2X.) Max simple-magnifier power = D/4 + 1."}'),
  ('ff855fc9-2m','{"options": ["7.1%", "17.9%", "9.9%", "29.7%"], "correct": 2, "explanation": "By the Holden-Mertz work, an equivalent oxygen percentage (EOP) of about 9.9% is the daily-wear criterion to avoid corneal edema; extended wear needs about 17.9%. Daily wear about 9.9% EOP; extended wear about 17.9%."}'),
  ('1955a48e-42','{"options": ["10 lumen", "100 lux", "1 lumen", "10 lux"], "correct": 1, "explanation": "Illuminance (lux) = luminous intensity (candela)/distance^2 = 100/1^2 = 100 lux. At 1 meter, a 100-unit source gives 100 lux. Lux = candela / (distance in m)^2."}'),
  ('2a8e00e3-44','{"options": ["-3.00 DS -1.00 DC x 180", "-4.00 DS +1.00 DC x 180", "-4.00 DS -1.00 DC x 180", "-1.00 DS -3.00 DC x 180"], "correct": 3, "explanation": "Minus-cyl form: sphere = the less-minus meridian (-1.00, along 180), cyl = -4.00 - (-1.00) = -3.00, axis along the sphere-only meridian (180). So -1.00 DS -3.00 DC x 180. Check: at 180 = -1.00, at 90 = -1.00 + -3.00 = -4.00."}'),
  ('95ef9b7c-37','{"options": ["Citric acid pathway", "TCA cycle", "HMP shunt pathway", "Kreb cycle"], "correct": 2, "explanation": "The citric acid cycle, TCA cycle, and Krebs cycle are three NAMES FOR THE SAME pathway, so the only distinct choice is the HMP (hexose-monophosphate/pentose-phosphate) shunt, which yields NADPH for biosynthesis and ribose for nucleotides. VERIFY: the item is defective because A, B, and D are identical; the amphibolic Krebs cycle actually best fits ''energy plus biosynthetic intermediates'', but the pentose-phosphate shunt is the only selectable single option."}'),
  ('ef24ed5b-1l','{"options": ["basic", "isotonic", "neutral", "acidic"], "correct": 0, "explanation": "A pH above 7.0 (neutral) is basic (alkaline); pH 7.3+ is on the basic side. Tonicity (isotonic) is a separate property from pH. Above 7 = basic."}'),
  ('ae76dfe5-2j','{"options": ["-8.50 D", "-7.75 D", "-7.00 D", "-7.25 D"], "correct": 2, "explanation": "Effective power at the cornea = F/(1 - dF) = -7.75/(1 - 0.012 x -7.75) = -7.75/1.093 = -7.09, about -7.00 D. A minus lens moved to the cornea needs LESS minus. Spectacle-to-CL for minus = less power."}'),
  ('81c44b72-31','{"options": ["1 X", "2 X", "3 X", "4 X"], "correct": 3, "explanation": "Lateral (linear) magnification in indirect ophthalmoscopy = eye power / condensing lens power = 60/15 = 4X. Lower-power condensing lenses give higher magnification (and smaller field). Mag = 60 / lens D."}'),
  ('d9e152d5-2o','{"options": ["blue dot", "posterior", "stellate", "heat"], "correct": 3, "explanation": "Chronic infrared (heat) exposure, as in glassblowers and furnace workers, causes a HEAT (infrared) cataract. Blue-dot are congenital, stellate are traumatic, and posterior subcapsular have other causes. Infrared = heat cataract."}'),
  ('eab8da4b-2u','{"options": ["+11.77 mm", "+12.12 cm", "+11.77 cm", "+12.12 mm"], "correct": 2, "explanation": "Focal length = 1/power = 1/8.50 = 0.1177 m = 11.77 cm. (The 12 mm vertex is a distractor here.) f (cm) = 100/D."}'),
  ('d0996588-2e','{"options": ["fitted flat", "optically aligned", "optimal fitting", "fitted steep"], "correct": 3, "explanation": "Mires that are clear just after a blink but DISTORT before the next blink point to a STEEP (tight) lens that settles/tightens during the interblink period. VERIFY: over-keratometry mire behavior is subtle and can vary; distortion late in the blink cycle classically indicates a steep fit."}'),
  ('88c0a584-1y','{"options": ["75", "100", "20", "50"], "correct": 2, "explanation": "Focal length = 1/power = 1/5.00 = 0.20 m = 20 cm. f (cm) = 100/D."}'),
  ('75413ea4-28','{"options": ["0.01", "2.0", "0.1", "0.005"], "correct": 3, "explanation": "Transmission = 10^(-optical density) = 10^-2.30 = 0.005 (0.5%). ND filters are rated by optical density; T = 10^(-OD)."}'),
  ('30d902f2-44','{"options": ["3", "4", "5", "2"], "correct": 2, "explanation": "Prism power (prism diopters) = displacement (cm) at 1 meter = 5 prism diopters. One prism diopter displaces the ray 1 cm at 1 meter. 5 cm at 1 m = 5 pd."}'),
  ('8a63c8e0-11','{"options": ["The angle of reflection is equal to the angle of incidence", "The angle of reflection is determined by Snell''s Law", "The angle of reflection is determined by the normal ray", "The angle of reflection is greater than the angle of incidence"], "correct": 0, "explanation": "The Law of Reflection: the angle of reflection equals the angle of incidence (both measured from the normal). Snell''s Law governs refraction, not reflection. Reflection: angle in = angle out."}'),
  ('ff3f973e-1k','{"options": ["minified", "plano", "stronger", "weaker"], "correct": 2, "explanation": "Bringing a MINUS lens toward the eye (shorter vertex) increases its effective power at the cornea, so it becomes stronger (more minus). This is why a minus spectacle needs LESS minus as a contact lens (already at the cornea). Minus lens in = stronger effect."}'),
  ('9d78d4a5-x','{"options": ["with", "no", "against", "scissors"], "correct": 2, "explanation": "Plus (converging) lenses show AGAINST motion on the rock test. Minus lenses show WITH motion. Plus = against."}'),
  ('9c6c509b-31','{"options": ["ionic materials", "non-ionic materials", "low water materials", "high water materials"], "correct": 1, "explanation": "Non-ionic materials are classed as having NO net surface charge (they resist protein), in contrast to ionic materials that carry a net negative surface charge. VERIFY: the phrase ''charged sites but no net surface charge'' is oddly worded; among the FDA charge/water categories, the no-net-charge option is non-ionic."}'),
  ('c73214e1-26','{"options": ["Age-related maculopathy", "Photokeratitis", "Cataracts", "Diabetic retinopathy"], "correct": 3, "explanation": "UV exposure is linked to photokeratitis, cataract, and age-related maculopathy, but DIABETIC RETINOPATHY is caused by diabetes (chronic hyperglycemia), not UV light. Diabetic retinopathy is not a UV disease."}'),
  ('44203374-1c','{"options": ["lower impact resistance", "higher chromatic aberration", "lower index of refraction", "higher index of refraction"], "correct": 1, "explanation": "A LOW Abbe number means high dispersion, so the lens shows more chromatic aberration (color fringing), a common trade-off in high-index materials. Low Abbe = more chromatic aberration."}'),
  ('a13641be-20','{"options": ["Decrease distance between the pads", "Increase distance between the pads", "Increase the pantoscopic tilt", "Decrease the face form tilt"], "correct": 0, "explanation": "Bringing the nose pads CLOSER together (decreasing the distance between them) makes the frame ride HIGHER on the nose, raising the low segments. VERIFY: several adjustments affect segment height, but narrowing the pad spread to lift the frame is the standard fix for low segments."}'),
  ('0b45240c-2o','{"options": ["Photokeratoscope", "Contascope", "Toposcope", "Keratometer"], "correct": 1, "explanation": "The photokeratoscope, corneal topographer (toposcope), and keratometer all measure corneal curvature. A ''contascope'' is not a recognized corneal-curvature instrument, so it is the odd one out. VERIFY: the term ''contascope'' is nonstandard, so confirm against the source''s intended list."}'),
  ('ab202341-3i','{"options": ["56 degrees", "112 degrees", "28 degrees", "224 degrees"], "correct": 1, "explanation": "For a plane mirror, angle of deviation = 180 - 2 x (angle of incidence) = 180 - 2(34) = 180 - 68 = 112 degrees. Deviation on reflection = 180 - 2i."}'),
  ('62af52a6-1w','{"options": ["Bell''s palsy", "Proptosis", "Entropion", "Ectropion"], "correct": 2, "explanation": "Exposure keratitis comes from incomplete lid closure: Bell''s palsy (facial-nerve weakness), proptosis (globe protrusion), and ectropion (lid turned OUT) all leave the cornea exposed. ENTROPION turns the lid IN (causing trichiasis, not exposure), so it is the exception. Exposure = things that keep the lid open; entropion turns it inward."}'),
  ('1acac68d-2k','{"options": ["gold plated", "gold flash", "gold filled", "fine gold"], "correct": 3, "explanation": "''Fine gold'' denotes pure gold with no other metal. Gold-plated, gold-flash, and gold-filled articles are base metals coated with a gold layer. Pure gold = fine gold."}'),
  ('0f77cc0c-1b','{"options": ["BU prism in the distance area", "BD prism in the reading area", "BD prism in the distance area", "BU prism in the reading area"], "correct": 3, "explanation": "Conventional slab-off (bicentric grinding) removes base-down effect in the lower lens, leaving a BASE-UP prism in the READING area to balance vertical imbalance at near between unequal lenses. Slab-off = base-up in the reading zone."}'),
  ('32c50224-24','{"options": ["weaker", "plano", "toroidal", "stronger"], "correct": 3, "explanation": "Moving a PLUS lens away from the eye increases its effective power (F_eff = F/(1-dF); larger d raises a positive value), so it becomes stronger. Plus lens out = stronger effect."}'),
  ('269814fa-42','{"options": ["50 lux", "48 lux", "40 lux", "70 lux"], "correct": 1, "explanation": "Illuminance = intensity/distance^2 = 1200/5^2 = 1200/25 = 48 lux. Lux = candela/(distance in m)^2."}'),
  ('4a15bf8e-2c','{"options": ["lens alignment", "optimal fit", "flat fit", "tight fit"], "correct": 2, "explanation": "Apical touch (central bearing, a DARK spot where fluorescein is squeezed out) indicates a FLAT fit. Apical clearance/pooling (bright center) indicates a steep fit. Dark central touch = flat; bright central pool = steep."}'),
  ('05527228-29','{"options": ["8.50", "13.50", "14.00", "7.50"], "correct": 0, "explanation": "A rigid lens diameter is chosen about 2 to 2.5 mm smaller than the horizontal visible iris diameter, so 11.0 - 2.5 = about 8.50 mm. RGP diameter is smaller than the cornea (about HVID minus 2 to 2.5 mm)."}'),
  ('c88be8c9-1w','{"options": ["increase", "affect", "magnify", "decrease"], "correct": 3, "explanation": "Spectacle magnification''s shape factor rises with the front (base) curve, so DECREASING (flattening) the base curve reduces the shape factor and DECREASES the magnification. VERIFY: the effect is via the shape factor of spectacle magnification; flatter front base curve = less magnification."}'),
  ('56c0b5af-2g','{"options": ["4 X", "1 X", "3 X", "2 X"], "correct": 2, "explanation": "Lateral magnification = eye power / condensing lens power = 60/20 = 3X. A stronger condensing lens gives lower magnification but a wider field. Mag = 60 / lens D."}'),
  ('9aedc2d2-3j','{"options": ["224 degrees", "112 degrees", "26 degrees", "56 degrees"], "correct": 1, "explanation": "As before, deviation for a plane mirror = 180 - 2i = 180 - 68 = 112 degrees. Reflection deviation = 180 - 2 x angle of incidence."}'),
  ('93fc1f88-25','{"options": ["10 percent", "5 percent", "21 percent", "2 percent"], "correct": 0, "explanation": "The commonly cited critical oxygen requirement to avoid corneal edema is about 10% (roughly matching the ~9.9% daily-wear EOP criterion). VERIFY: some references quote a range and the open-eye cornea normally sees 21% atmospheric oxygen, so the intended figure depends on the source; about 10% is the critical minimum."}'),
  ('ea2c113f-2i','{"options": ["Decreases", "Remains the same", "Increases", "Varies with material"], "correct": 0, "explanation": "A HIGHER Abbe number means LESS dispersion, so chromatic aberration decreases. High Abbe = low chromatic aberration."}'),
  ('d8027191-1s','{"options": ["erratic", "plano", "stronger", "weaker"], "correct": 3, "explanation": "Bringing a PLUS lens toward the eye (shorter vertex) reduces its effective power at the cornea, so it becomes weaker. (Conversely, moving it away makes it stronger.) Plus lens in = weaker effect."}'),
  ('14715ad3-15','{"options": ["does not change the vergence of its reflecting rays", "adds positive vergence to its reflected rays", "creates a real image", "adds negative vergence to its reflected rays"], "correct": 3, "explanation": "A convex mirror DIVERGES the reflected light, adding negative vergence and forming a virtual, minified, erect image. A concave mirror adds positive vergence. Convex mirror = diverging = negative vergence, virtual image."}'),
  ('bcb3add3-1f','{"options": ["centrad", "apical angle", "degree of dispersion", "prism diopter"], "correct": 0, "explanation": "The centrad, defined on the arc of a circle, is theoretically more accurate than the prism diopter (which uses the tangent and diverges from the centrad at larger angles). VERIFY: in clinical practice the prism diopter is the working unit; the centrad is the more geometrically exact measure the item is pointing to."}'),
  ('d37a207a-1l','{"options": ["has too much face form", "is out of coplanar alignment", "has skewed bridge", "has X-ing"], "correct": 1, "explanation": "If one lens sits farther forward than the other, the two lenses are no longer in the same plane, so the frame is out of coplanar alignment. Coplanar = the two lenses lie in one plane; one forward breaks that."}'),
  ('4236073d-y','{"options": ["polyethylene", "poly methylmethacrylate", "hydroxyapatite", "aluminum oxide"], "correct": 2, "explanation": "Bioceramic orbital implants are made of HYDROXYAPATITE (a calcium-phosphate ceramic that resembles bone and allows fibrovascular ingrowth). Polyethylene and PMMA are other implant materials but not the ''bioceramic'' one. Bioceramic implant = hydroxyapatite."}'),
  ('5d0ed2e2-3f','{"options": ["10 cm", "1.0 meter", "20 cm", "2.0 meter"], "correct": 2, "explanation": "Distance = 1/vergence = 1/5 = 0.20 m = 20 cm. Vergence (D) = 1/distance (m), so distance = 1/vergence."}'),
  ('ab059ac9-2k','{"options": ["5", "7", "3", "9"], "correct": 1, "explanation": "Extended (overnight) wear lenses are generally limited to about 7 days (6 nights) of continuous wear before removal, to reduce hypoxia and infection risk. Extended wear ceiling is about 7 days."}'),
  ('77ba3abc-2m','{"options": ["flat fit", "optimal fit", "tight fit", "lens alignment"], "correct": 2, "explanation": "Apical POOLING (a bright central accumulation of fluorescein = apical clearance) indicates a STEEP (tight) fit. Apical touch (dark center) indicates a flat fit. Bright central pool = steep/tight; dark touch = flat."}'),
  ('1310d7db-3r','{"options": ["58 mms", "8.7 mms", "5.8 mms", "87 mms"], "correct": 3, "explanation": "A 20/20 letter subtends 5 minutes of arc (about 8.7 mm at 20 feet); a 20/200 letter is ten times larger, about 87 mm. 20/200 letter height at 20 ft is about 87 mm (ten times the 20/20 size)."}'),
  ('4d8d9828-1i','{"options": ["HEMA", "PMMA", "CAB", "Polycon"], "correct": 2, "explanation": "Cellulose acetate butyrate (CAB) was the first rigid GAS-PERMEABLE material, adding oxygen transmission that the older non-permeable PMMA lacked. VERIFY: silicone-acrylate (e.g., Polycon) soon followed as the first widely successful RGP; CAB is credited as the earliest gas-permeable rigid material. HEMA is a soft-lens material."}'),
  ('44d6cb4e-2s','{"options": ["+8.75 D", "-5.75 D", "+5.50 D", "-8.25 D"], "correct": 1, "explanation": "For a thin lens, total = front + back, so back = 3.50 - 9.25 = -5.75 D. Back surface = nominal power minus front surface."}'),
  ('dc94b375-2m','{"options": ["benzalkonium chloride", "ethylene diaminetetra acetate", "saline solution", "proteolytic enzymes"], "correct": 3, "explanation": "PROTEOLYTIC (enzymatic) cleaners are the weekly deposit removers that digest protein build-up. Benzalkonium is a preservative, EDTA a chelating aid, and saline only rinses. Weekly protein removal = enzyme cleaner."}'),
  ('b6151df5-17','{"options": ["adds positive vergence to reflected rays", "does not change the vergence of its reflected rays", "creates a virtual image", "adds negative vergence to reflected rays"], "correct": 0, "explanation": "A concave mirror CONVERGES the reflected light, adding positive vergence (and, for a distant object, forming a real image). A convex mirror adds negative vergence. Concave mirror = converging = positive vergence."}'),
  ('5c6d67b9-1x','{"options": ["90%", "50%", "70%", "30%"], "correct": 0, "explanation": "The stroma, made of ordered collagen lamellae, makes up about 90% of corneal thickness. Its regular lamellar spacing is what keeps the cornea transparent. Stroma = about 90% of the cornea."}'),
  ('670090e3-26','{"options": ["Lathe cutting", "Cast molding", "Spin casting", "Stabilized soft molding"], "correct": 1, "explanation": "Cast molding (pressing the lens between precise molds) enabled the fast, inexpensive, reproducible mass production that made DISPOSABLE soft lenses feasible. VERIFY: the first disposables (Acuvue) used a specific ''stabilized soft molding'' cast process, so option D is closely related; cast molding is the general enabling method."}'),
  ('b8ca167b-t','{"options": ["matched in color with the fellow eye under indoor lighting", "made of blown glass", "the same as haptic shells", "fitted over an implant placed within the orbit"], "correct": 3, "explanation": "A modern ocular prosthesis is fitted OVER an orbital implant placed after enucleation/evisceration, moving with it for a natural appearance. Color is matched in natural (not just indoor) light, and acrylic has largely replaced blown glass. Prosthesis sits over an orbital implant."}'),
  ('4c441f72-2g','{"options": ["0.50 D", "Zero", "0.75 D", "1.00 D"], "correct": 1, "explanation": "By Hofstetter''s minimum formula, amplitude = 15 - 0.25 x age = 15 - 0.25(60) = 0 D. VERIFY: clinically a small residual (about 1 D, largely depth of focus) usually remains, so some keys answer 1.00 D; the Hofstetter minimum computes to zero at 60."}'),
  ('e491f5f2-2i','{"options": ["9 mm", "21 mm", "14 mm", "7 mm"], "correct": 0, "explanation": "Displacement = prism power x distance = 3.5 x 0.25 m = 0.875 cm = 8.75 mm, about 9 mm. Displacement (cm) = prism diopters x distance (m)."}'),
  ('121f1ec9-1v','{"options": ["silicon", "polymacon", "focon", "filcon"], "correct": 3, "explanation": "Soft (hydrophilic/hydrogel) lens materials carry the USAN stem ''-filcon''. The ''-focon'' stem denotes rigid materials, and ''polymacon'' is one specific hydrogel material rather than the group stem. Soft group stem = filcon."}'),
  ('3dc73169-1b','{"options": ["3.5 mm", "2.6 mm", "6.2 mm", "5.3 mm"], "correct": 1, "explanation": "The corneal sagittal depth (apex to the limbal plane) is about 2.6 mm. VERIFY: quoted values range roughly 2.5 to 3.0 mm depending on the chord diameter used, so treat 2.6 mm as the intended figure."}'),
  ('e074a4b8-1i','{"options": ["Stable visual acuity", "Complete corneal coverage", "Adequate tear exchange", "Limbal compression"], "correct": 3, "explanation": "Good soft-lens fitting aims for stable acuity, complete corneal coverage, and adequate tear exchange (movement). LIMBAL COMPRESSION is a sign of a too-tight lens and an unwanted complication, not a goal. Compression = bad fit, not an objective."}'),
  ('80c7207c-y','{"options": ["constant flat curve", "constant steep curve", "steeper than periphery", "flatter than periphery"], "correct": 2, "explanation": "The central cornea is STEEPER than the periphery, which flattens outward (a prolate shape). This central steepening does the eye''s main refraction. Center steep, periphery flat."}'),
  ('b3444f47-1l','{"options": ["1.49", "1.33", "33 percent", "49 percent"], "correct": 0, "explanation": "Opacity = 1/transmittance = 1/0.67 = 1.49. Opacity is the reciprocal of transmittance, not (100 - transmission). Opacity = 1/T."}'),
  ('b970939e-31','{"options": ["Aluminum", "Stainless steel", "Nickel silver", "Titanium"], "correct": 2, "explanation": "Nickel silver (a copper-nickel-zinc alloy, containing no actual silver) is a strong, workable base metal traditionally used for frame fronts and temple cores. VERIFY: stainless steel and titanium are also strong and highly corrosion-resistant, so the ''best'' answer depends on the emphasis; nickel silver is the classic temple base metal."}'),
  ('0ff9fb75-13','{"options": ["cannot read print smaller than 8-point type", "lack sufficient finger sensitivity", "are able to read at a very slow speed", "have distance vision of 2/200 or less"], "correct": 3, "explanation": "Braille (tactile reading) is indicated for those with severe vision loss, on the order of 2/200 or worse, who cannot use print even with magnification. Lacking finger sensitivity is a CONTRAINDICATION, and mild print difficulty is handled with magnifiers. Braille = for severe vision loss (about 2/200 or less)."}'),
  ('8bf15ae5-2v','{"options": ["-9.25 D", "-6.25 D", "-10.25 D", "-7.50 D"], "correct": 1, "explanation": "Nominal (thin-lens) power = front + back = +2.00 + (-8.25) = -6.25 D. Add the two surface powers."}'),
  ('0516ff74-2o','{"options": ["+8.00 D", "+10.00 D", "+5.75 D", "+2.75 D"], "correct": 1, "explanation": "Surface power = (n2 - n1)/r = (1.498 - 1)/0.05 = 0.498/0.05 = 9.96, about +10.00 D. F = (n'' - n)/radius in meters."}'),
  ('3b920bc8-3e','{"options": ["Preservation", "Sterilization and Disinfection", "Disinfection", "Sterilization and Preservation"], "correct": 1, "explanation": "Actively KILLING/removing resident organisms is done by sterilization (kills all, including spores) and disinfection (kills most vegetative organisms). Preservation only INHIBITS growth in storage. Kill/remove = sterilization and disinfection; preservation merely holds growth in check."}'),
  ('3702c290-24','{"options": ["Sterilization", "all of these", "Disinfection", "Preservation"], "correct": 0, "explanation": "STERILIZATION is defined as any process that kills or eliminates ALL transmissible agents, including bacterial spores. Disinfection spares some resistant forms, and preservation only inhibits. Kill everything = sterilization."}'),
  ('0064c4dc-2q','{"options": ["Sterilization and Disinfection", "Sterilization and Preservation", "Sterilization", "Preservation"], "correct": 3, "explanation": "PRESERVATION inhibits (and can kill) SELECTED microorganisms to keep a stored solution from becoming contaminated, without sterilizing it. VERIFY: ''killing or inhibition of selected organisms'' also overlaps disinfection, so the item is loose; preservation best matches the storage-level, selective control described."}'),
  ('ab082be9-5x','{"options": ["III only", "IV only", "I only", "II only"], "correct": 2, "explanation": "GOBLET cells (I) are the secretory cells embedded within the conjunctival epithelium, producing the mucin of the tear film. VERIFY: ''sero-mucous'' would strictly suit the accessory lacrimal glands of Wolfring (III), but those lie in the stroma, not the epithelial layer; the epithelial secretory cell is the goblet cell."}'),
  ('84b81882-56','{"options": ["IV only", "II only", "I only", "III only"], "correct": 3, "explanation": "The glands of Wolfring (III), accessory lacrimal glands, secrete the AQUEOUS component of the tear film. Meibomian glands (IV) make the lipid layer and goblet cells (I) the mucin. Wolfring (accessory lacrimal) = aqueous."}'),
  ('f0e49550-6q','{"options": ["II and IV", "II only", "I and III", "I only"], "correct": 3, "explanation": "The conjunctival epithelium differs from the corneal by containing GOBLET cells (I), which add to its bulk and give it its mucin-secreting function. VERIFY: the conjunctival epithelium also varies in layer number by region, so the ''thicker'' framing is loose; the goblet cells are the distinguishing added structure."}'),
  ('e990d5bc-3q','{"options": ["equal to 15x", "less than 15x", "equal to plano", "greater than 15x"], "correct": 0, "explanation": "In direct ophthalmoscopy the emmetropic eye gives the baseline magnification of about 15x. Ametropia shifts this: myopia increases it, hyperopia decreases it. Emmetrope = about 15x."}'),
  ('87a69cf3-2v','{"options": ["greater than 15x", "lesser than 15x", "equal to 15x", "equal to plano"], "correct": 0, "explanation": "A MYOPIC eye acts like a stronger optical system, so direct ophthalmoscopy of a myope gives GREATER than 15x magnification (with a smaller field). Myopia = higher magnification."}'),
  ('58bc6ee7-34','{"options": ["equal to plano", "lesser than 15x", "greater than 15x", "equal to 15x"], "correct": 1, "explanation": "A HYPEROPIC eye is a weaker optical system, so direct ophthalmoscopy gives LESS than 15x magnification (with a larger field). Hyperopia = lower magnification."}'),
  ('0abc722b-30','{"options": ["7.5 cm behind the mirror", "13 cm behind the mirror", "7.5 cm in front of the mirror", "7.0 cm in front of the mirror"], "correct": 1, "explanation": "Focal length = R/2 = 30 cm; with the object (10 cm) inside the focal point, the image is virtual and behind the mirror. Working 1/v = 1/f - 1/u gives about -15 cm (15 cm behind), so the nearest listed option is about 13 cm behind. VERIFY: the exact computed value is ~15 cm behind, so the option set is approximate/imperfect; the image is virtual and behind the mirror."}'),
  ('aa3d044f-1b','{"options": ["2.25", "4.75", "1.50", "3.25"], "correct": 1, "explanation": "With the object inside the focal length of a concave mirror, the image is enlarged and erect; the magnification is about 1.5x, so a 3 cm letter gives roughly 4.5 cm, nearest the listed 4.75 cm. VERIFY: the computed value (~4.5 cm) does not match an option exactly, so treat this as the closest choice for a magnified virtual image."}'),
  ('38cc6141-15','{"options": ["erect and virtual", "inverted and virtual", "erect and real", "inverted and real"], "correct": 0, "explanation": "An object placed INSIDE the focal length of a concave mirror forms an ERECT, VIRTUAL, magnified image behind the mirror (the makeup/shaving-mirror case). Inside f of a concave mirror = erect, virtual, enlarged."}'),
  ('2959941f-45','{"options": ["Amplitude", "Speed", "Frequency", "Wavelength"], "correct": 3, "explanation": "WAVELENGTH is the distance between corresponding points (for example crest to crest) on successive waves. Amplitude is height, frequency is cycles per second, and speed is how fast the wave travels. Crest-to-crest distance = wavelength."}'),
  ('c0b746cb-2c','{"options": ["Amplitude", "Frequency", "Wavelength", "Speed"], "correct": 1, "explanation": "FREQUENCY is the number of wave cycles passing a point per second (measured in hertz). Wavelength is spatial, amplitude is height, and speed is distance per time. Waves per second = frequency."}'),
  ('999faf13-2g','{"options": ["Frequency", "Wavelength", "Speed", "Amplitude"], "correct": 2, "explanation": "SPEED is the distance a wave travels per second (speed = frequency x wavelength). Frequency counts cycles, wavelength is the length of one cycle, and amplitude is height. Distance per second = speed."}'),
  ('7d59f56f-3k','{"options": ["Index of Refraction", "Specific Gravity", "Abbe Value", "Light Transmission"], "correct": 2, "explanation": "The Abbe value (V-number) is the reciprocal of dispersive power; a high Abbe means low chromatic dispersion, so the material holds the spectrum together. Index of refraction is bending power, specific gravity is density. High Abbe = less color fringing."}'),
  ('2509a3a4-2n','{"options": ["-3.50 D", "+11.00 D", "+3.50 D", "-11.00 D"], "correct": 2, "explanation": "Nominal (thin-lens) power = sum of the two surface powers = (+7.25) + (-3.75) = +3.50 D. Nominal power just adds the surfaces, ignoring thickness."}'),
  ('5e4df196-4j','{"options": ["+3.25 D", "+4.25 D", "+4.00 D", "-4.25 D"], "correct": 1, "explanation": "Back vertex power Fv = F2 + F1/(1 - (t/n)F1). t/n = 0.008/1.67 = 0.00479; (t/n)F1 = 0.00479 x 10.25 = 0.0491; F1/(1-0.0491) = 10.25/0.9509 = 10.78; Fv = 10.78 + (-6.50) = +4.28, about +4.25 D. Thick-lens BVP adds the thickness-boosted front power to the back surface."}'),
  ('42f5caa6-29','{"options": ["decrease plus power", "decrease minus power", "increase plus power", "have no change in power"], "correct": 0, "explanation": "Moving a plus lens toward the eye reduces its effective plus power (you need more plus the closer it sits). So the effective power decreases. Plus lens closer to eye = less effective plus."}'),
  ('2f99c413-63','{"options": ["-5.89 D", "-5.62 D", "-0.25 D", "-6.06 D"], "correct": 1, "explanation": "Vertex effectivity: the -5.75 D at 13 mm gives a corneal-plane power of -5.75/(1+0.013x5.75) = -5.35 D. The equivalent lens at 9 mm = -5.35/(1-0.009x5.35) = -5.62 D. Moving a minus lens closer needs less minus, so -5.62 D."}'),
  ('ad919cff-41','{"options": ["-5.52sph = -1.15 cx180", "-5.99sph = -1.37cx180", "-5.99sph = -1.37cx90", "5.52sph = -1.15 cx90"], "correct": 1, "explanation": "Work each meridian at the new (farther) vertex. The 180 meridian (-5.75): -5.75/(1+0.007x5.75) = -5.99. The 90 meridian (-7.00): -7.00/(1+0.007x7.00) = -7.36. New Rx = -5.99 sph = -1.37 cx 180. Moving the lens out (5 to 12 mm) adds minus in both meridians."}'),
  ('7178fbac-28','{"options": ["6 Δ BU and BO @ 55", "6 Δ BU and BO @ 125", "6 Δ BU and BO @ 235", "6 Δ BU and BO @ 305"], "correct": 0, "explanation": "Magnitude = √(5.0² + 3.5²) = 6.10Δ, and all four options share it, so this is a direction question. Reference angle = arctan(5.0/3.5) = 55.0° off the horizontal. Place it on the 360 scale: 0° sits on the examiner''s right, which for OS is temporal (base OUT), with base up at 90 and base down at 270. Base up and base out therefore lands in the upper-temporal quadrant, giving 55°. Answer: 6.10Δ @ 55. The trap is 125, which is the correct answer for the same two prisms in front of the other eye, so check OD vs OS before committing."}'),
  ('f9b72d05-2g','{"options": ["0.7 mm", "7 mm", "0.7 cm", "7 cm"], "correct": 1, "explanation": "Prentice: d(cm) = prism / F = 4 / 5.75 = 0.696 cm, which is 6.96 mm. DEFECTIVE ITEM, flagged: options B (7 mm) and C (0.7 cm) are the SAME quantity, so both are correct and this cannot be graded as written. The bank keys B, but 0.7 cm is equally right. The original ''unit trap'' framing does not work because two of the four options are the same value. Keep the method, not the key: d = prism / F with F in dioptres gives CENTIMETRES, then multiply by 10 for the millimetres a lab order uses."}'),
  ('933a3bca-28','{"options": ["7.63 Δ BD and BO @ 58", "7.63 Δ BD and BO @ 122", "7.63 Δ BD and BO @ 236", "7.63 Δ BD and BO @ 302"], "correct": 2, "explanation": "Magnitude = √(6.5² + 4.0²) = 7.63Δ, and all four options share it, so this is a direction question. Reference angle = arctan(6.5/4.0) = 58.4° off the horizontal. Place it on the 360 scale: 0° sits on the examiner''s right, which for OD is nasal (base IN), with base up at 90 and base down at 270. Base down and base out therefore lands in the lower-temporal quadrant, giving 238°. The listed option 236 is the nearest value to 238. Answer: 7.63Δ @ 236. The trap is 302, which is the correct answer for the same two prisms in front of the other eye, so check OD vs OS before committing."}'),
  ('e1c364ab-28','{"options": ["3.35 Δ BD and BO @ 63", "3.35 Δ BD and BO @ 117", "3.35 Δ BD and BO @ 243", "3.35 Δ BD and BO @ 297"], "correct": 3, "explanation": "Magnitude = √(3.0² + 1.5²) = 3.35Δ, and all four options share it, so this is a direction question. Reference angle = arctan(3.0/1.5) = 63.4° off the horizontal. Place it on the 360 scale: 0° sits on the examiner''s right, which for OS is temporal (base OUT), with base up at 90 and base down at 270. Base down and base out therefore lands in the lower-temporal quadrant, giving 297°. Answer: 3.35Δ @ 297. The trap is 243, which is the correct answer for the same two prisms in front of the other eye, so check OD vs OS before committing."}'),
  ('cb69abe4-28','{"options": ["8.38 Δ BU and BI @ 73", "8.38 Δ BU and BI @ 107", "8.38 Δ BU and BI @ 253", "8.38 Δ BU and BI @ 287"], "correct": 1, "explanation": "Magnitude = √(8.0² + 2.5²) = 8.38Δ, and all four options share it, so this is a direction question. Reference angle = arctan(8.0/2.5) = 72.6° off the horizontal. Place it on the 360 scale: 0° sits on the examiner''s right, which for OS is temporal (base OUT), with base up at 90 and base down at 270. Base up and base in therefore lands in the upper-nasal quadrant, giving 107°. Answer: 8.38Δ @ 107. The trap is 73, which is the correct answer for the same two prisms in front of the other eye, so check OD vs OS before committing."}'),
  ('3cee8a8e-2s','{"options": ["Ideal Face form", "Flat face form", "Steep Face form", "Positive Face form"], "correct": 2, "explanation": "Excessive (steep) face-form wrap tilts the lens relative to the line of sight, inducing power error and unwanted cylinder. An ideal/flat face form minimizes this."}'),
  ('e5dea2ae-3a','{"options": ["-4.23 sph", "+4.23 sph", "+6.41 sph", "6.41 sph"], "correct": 2, "explanation": "Tilting a lens makes light cross it obliquely, which effectively steepens it, so the sphere power goes UP. Martin: new sphere = F(1 + sin^2(theta) / 2n). sin 16 = 0.2756, so sin^2 = 0.0760. 2n = 2 x 1.523 = 3.046. New sphere = 6.25 x (1 + 0.0760/3.046) = 6.25 x 1.0249 = +6.41 D. Answer: +6.41 sph. A pantoscopic tilt also induces cyl of F x tan^2(16) = 6.41 x 0.0822 = +0.53 D at axis 180, which this item does not ask for. Direction check: tilt can only ADD plus to a plus lens, so both minus options are out before you compute."}'),
  ('0337009f-3h','{"options": ["-5.25 sph = -0.95 cx 180", "+5.25 sph = 1.33 cx 180", "-7.36 sph = -1.33 cx 180", "+7.36 sph = -0.95 cx 90"], "correct": 2, "explanation": "Retroscopic tilt rotates the lens about the HORIZONTAL axis, so the meridian that is tilted (and gains power) is the VERTICAL one, and any induced cylinder lands on axis 180. Step 1, read the vertical-meridian power: for -7.00 = +2.00 x 90 the cyl axis is 90, so the vertical (90 deg) meridian carries the -7.00; the horizontal (180 deg) meridian is -5.00 and, lying along the tilt axis, is unchanged. Step 2, trig: sin 23 = 0.3907 (sin^2 = 0.1527); tan 23 = 0.4245 (tan^2 = 0.1802). Step 3, new sphere = F(1 + sin^2/2n) = -7.00 x (1 + 0.1527/3) = -7.00 x 1.0509 = -7.36 D. Step 4, induced cyl = new sphere x tan^2 = -7.36 x 0.1802 = -1.33 D; because the extra power appears vertically, the axis is 180. Answer: -7.36 sph = -1.33 cx 180. Trap: applying the formula to the -5.00 horizontal meridian (the rotation axis, which cannot be made oblique) gives -5.25 / -0.95 — right axis, wrong meridian. n = 1.5 assumed for the glass."}'),
  ('7ccdbf0d-2p','{"options": ["7.62 degrees", "3.28 degrees", "2.62 degrees", "7 degrees"], "correct": 2, "explanation": "Deviation of a thin prism = (n-1) x apical angle. Crown glass n = 1.523, so (0.523)(5) = 2.62 degrees. Thin-prism deviation = (n-1) times the apex angle."}'),
  ('287e4f47-1u','{"options": ["A cylinder decentered along its axis will give no prismatic effect.", "A cylinder decentered perpendicular to its axis will give a prismatic effect equivalent to a sphere of the same power.", "A cylinder parallel to its axis will give a prismatic effect equivalent to a sphere of the same power.", "The sphere and cylinder of a sphero- cylinder prescription can be treated as two separate lenses"], "correct": 2, "explanation": "The false statement is that a cylinder decentered PARALLEL to its axis gives a prismatic effect; in fact decentration ALONG (parallel to) the axis gives NO prism. Decentration perpendicular to the axis is what yields prism. So ''parallel gives prism'' is the exception."}'),
  ('0c5716b1-2n','{"options": ["H = 1.05 Δ BO and V = 2.5 Δ BD", "H = 1.05 Δ BI and V = 2.5 Δ BU", "H = 1.75 Δ BI and V = 1 Δ BU", "H = 1.75 Δ BO and V = 1 Δ BD"], "correct": 1, "explanation": "Horizontal meridian (180) power of +5.00 = -2.00 cx 90 is +5.00 + (-2.00) = +3.00; 3.5 mm in x 0.35 cm x 3.00 = 1.05 prism, base-in for a plus lens decentered in. Vertical (90) power is +5.00; 5 mm up x 0.5 cm x 5.00 = 2.5 prism, base-up. So H = 1.05 BI, V = 2.5 BU."}'),
  ('079dc3f4-3n','{"options": ["0.3 Δ Base Out", "0.3 Δ Base In", "0.3 Δ Base Up", "0.3 Δ Base Down"], "correct": 0, "explanation": "Prism = F × d in the relevant meridian (Prentice in an oblique-cyl lens). For −1.50 +3.00 ×30 you first find the power in the HORIZONTAL (180) meridian using F_θ = F_sph + F_cyl·sin²(angle from cyl axis); a 5 mm horizontal OC shift then gives ≈ 0.3Δ, base OUT given the net meridional power. Method: resolve power in the meridian of decentration FIRST, then apply Prentice. ≈ 0.3Δ base out."}'),
  ('a299bcc6-30','{"options": ["4 degrees", "2 degrees", "3 degrees", "7 degrees"], "correct": 0, "explanation": "Deviation = (n-1) x apex. Polycarbonate n = 1.586, so (0.586)(7) = 4.1, about 4 degrees. Polycarbonate prism deviation = 0.586 times the apex angle."}'),
  ('377a634d-40','{"options": ["Cutting", "Centering", "Bench Layout", "Crumbling"], "correct": 2, "explanation": "Bench layout is marking the decentration and placing the cylinder axis and prism base-apex line in position before surfacing/edging. Cutting and centering are other steps. Marking axis and base line = bench layout."}'),
  ('59ee5275-12','{"options": ["+4.75 D", "-4.75 D", "+1.75 D", "-1.75 D"], "correct": 0, "explanation": "EXCLUDED FROM SCORING. The stem was lost in PDF extraction (only ''530.'' survives), so the lens data needed to answer it is gone. Needs the source paper to rebuild."}'),
  ('d6eba0c4-4i','{"options": ["+2.50 D", "-1.50 D", "+6.25 D", "-6.25 D"], "correct": 0, "explanation": "Sag relates thickness difference to power: F = 2s(n - 1) / y^2, where s is how much thicker the centre is and y is the SEMI-diameter. s = 3.5 - 1.5 = 2 mm = 0.002 m. y = 65/2 = 32.5 mm = 0.0325 m. F = 2(0.002)(0.67) / 0.0325^2 = 0.00268 / 0.00105625 = +2.54 D, so +2.50 D. Answer: +2.50 D. Sign check without arithmetic: centre thicker than edge means a plus lens, so any minus option is out before you compute. Trap: using the full 65 mm diameter instead of the 32.5 mm semi-diameter divides by four times too much and gives about +0.63 D."}'),
  ('dcbb58a6-2p','{"options": ["-3.00 sph = -2.00 cx 180", "+0.25 sph = -2.00 cx 180", "+1.75 sph = -2.00 cx 180", "-4.25 sph = -0.50 cx 180"], "correct": 0, "explanation": "Intermediate add is half the near add (+2.50/2 = +1.25). Intermediate sphere = -4.25 + 1.25 = -3.00, cylinder unchanged: -3.00 sph = -2.00 cx 180. Intermediate = distance Rx plus half the add."}'),
  ('55a0b0a8-1s','{"options": ["95 %", "90 %", "92 %", "5 %"], "correct": 1, "explanation": "Uncoated polycarbonate (n = 1.586) loses about 5% per surface to reflection, transmitting roughly 90%. Higher index means more surface reflection and lower transmission. Uncoated poly = about 90%."}'),
  ('5be9de59-1o','{"options": ["92 %", "7 %", "96 %", "97%"], "correct": 2, "explanation": "CR-39 (n = 1.498) is about 92% uncoated; a single antireflection coat raises transmission to about 96%. AR coating cuts surface reflection and boosts transmission. Single-coated CR-39 = about 96%."}'),
  ('75a91939-1u','{"options": ["87 %", "93 %", "94 %", "6 %"], "correct": 2, "explanation": "Dense flint reflects more per surface, so uncoated it is about 87%; a double (both-surface) AR coat brings it up to about 94%. Double-coated dense flint = about 94%."}'),
  ('724ebddb-1q','{"options": ["87 %", "93 %", "94 %", "6 %"], "correct": 0, "explanation": "Uncoated dense flint (high index, n about 1.7) reflects heavily, transmitting only about 87%. High index = more reflection loss. Uncoated dense flint = about 87%."}'),
  ('544eaa9a-1l','{"options": ["91 %", "96 %", "95 %", "4 %"], "correct": 0, "explanation": "Uncoated crown glass (n = 1.523) reflects about 4% per surface, transmitting roughly 91 to 92%. VERIFY: 92% is the commonly cited figure, but the listed 91% is the closest option; confirm the source table."}'),
  ('c23cd5fe-20','{"options": ["Mirror coating", "UV coating", "Hard coating", "Antireflective coating"], "correct": 2, "explanation": "A hard (scratch) coat is the clear layer applied to protect lenses from scratches. AR coating cuts reflection, UV coating blocks UV, mirror coating is cosmetic/reflective. Scratch protection = hard coat."}'),
  ('a8f32d02-3l','{"options": ["Coma", "Chromatic Aberration", "Spherical Aberration", "Curvature of Field"], "correct": 2, "explanation": "Spherical aberration is the failure of a lens to bring all rays to a single focus (peripheral rays focus differently from central), blurring the image. Chromatic aberration is color-based; coma and field curvature are off-axis. One point of focus failing = spherical aberration."}'),
  ('4b97a9d2-z','{"options": ["Sir Isaac Newton", "Max Planck", "Albert Einstein", "Christian Huygens"], "correct": 3, "explanation": "Christiaan Huygens proposed the wave theory of light. Newton favored the corpuscular theory; Planck and Einstein worked on the quantum/photon picture later. Wave theory = Huygens."}'),
  ('348fc03d-29','{"options": ["Gamma Rays", "Visible Light", "Infrared", "Ultraviolet"], "correct": 1, "explanation": "Visible light is the only part of the electromagnetic spectrum the human eye detects. Gamma, infrared, and ultraviolet are invisible to us. Eye sees only visible light."}'),
  ('d8ea34b4-15','{"options": ["11.76 m", "4.71 m", "0.12 m", "117.65 m"], "correct": 2, "explanation": "Focal length = 1/power = 1/8.50 = 0.1176 m, about 0.12 m (the minus sign just marks a diverging lens). f = 1/F, so 0.12 m."}'),
  ('4d20653b-2w','{"options": ["waves", "quanta", "photons", "corpuscles"], "correct": 3, "explanation": "Newton''s emission (corpuscular) theory held that light is tiny particles called corpuscles. Photons and quanta are the modern terms; waves are the rival theory. Emission theory = corpuscles."}'),
  ('c75d1472-53','{"options": ["508.31 in¬2", "510.62 in¬2", "616.19 in¬2", "107. 88 in¬2"], "correct": 3, "explanation": "Tracing the penumbra edge: a ray from the source edge through the object edge projects to a shadow radius of about 5.86 in on the screen, so area = pi x 5.86^2 = about 107.88 in^2. Shadow area uses the projected penumbra radius."}'),
  ('687e1f22-3t','{"options": ["It will become slower as it enters the second medium", "It will become faster as it enters the second medium", "The speed will be the same as it enters the second medium", "Neither of the three choices is correct for as long as the second medium is not air"], "correct": 1, "explanation": "From higher to lower index, light speeds up (faster in the less dense medium). Lower index = faster light."}'),
  ('943bb1da-25','{"options": ["85.71 ft", "2.45 ft", "85.72 fc", "2.45 fc"], "correct": 3, "explanation": "Illuminance E = I/d^2 = 3000/35^2 = 3000/1225 = 2.45 foot-candles. Inverse-square law: E = candlepower over distance squared."}'),
  ('3b8c1b27-2y','{"options": ["vergence of light", "rays of light", "beam of light", "pencil of light"], "correct": 2, "explanation": "A beam is the collection of convergent, divergent, and parallel rays from an extended source (a pencil comes from a point). Extended source = beam of light."}'),
  ('d2309bb7-1m','{"options": ["Violet", "Red", "Blue", "Orange"], "correct": 0, "explanation": "Violet has the highest frequency (shortest wavelength) of the visible spectrum; red has the lowest. Violet = highest frequency end."}'),
  ('4fb80421-4x','{"options": ["37.8cd", "175cd", "291.67cd", "63cd"], "correct": 2, "explanation": "Inverse-square comparison: I/15^2 = 105/9^2, so I = 105 x 225/81 = 291.67 cd. Equal illumination means candlepowers scale with the square of distance."}'),
  ('8ef2dc5c-4v','{"options": ["180,956.16in2", "101,787.84in2", "407,151.36in2", "11309.76in2"], "correct": 3, "explanation": "The illuminated patch scales with distance from the source: diameter = aperture x (total distance/source-to-aperture) = 30 x (480/120) = 120 in, radius 60 in, area = pi x 60^2 = 11309.76 in^2. Patch grows linearly with distance from the source."}'),
  ('7d1da611-1j','{"options": ["Plano convex/ Plano concave", "Bi-convex/ Bi-concave", "Equi- convex/ Equi- concave", "Plus/minus meniscus"], "correct": 3, "explanation": "A lens with a convex front and concave back is a meniscus (plus or minus meniscus). The other options name symmetric or plano forms. Convex front, concave back = meniscus."}'),
  ('200294c4-3e','{"options": ["34.99 ft", "55.01 ft", "34.99 degrees", "55.01 degrees"], "correct": 3, "explanation": "Angular elevation: tan(theta) = height/shadow = 50/35 = 1.43, so theta = 55.01 degrees. The answer is an angle, not a length. arctan(height/shadow) = elevation."}'),
  ('9ed985c8-41','{"options": ["Inverse Square Law", "Law of Intensity", "Law of Rectilinear Propagation of Light", "Law of Reflection"], "correct": 0, "explanation": "The inverse-square law: candlepowers compared on a photometer are proportional to the squares of the distances. Photometric comparison = inverse-square law."}'),
  ('43060ca2-4v','{"options": ["44.5 cm", "0.50 D", "225 cm", "0.25 D"], "correct": 0, "explanation": "Add the two surface powers, then invert. Radii in metres: front +0.55 m, back -0.65 m. Front (convex): F1 = (n - 1)/r = 0.67 / 0.55 = +1.22 D. Back (concave): F2 = (1 - n)/r = -0.67 / -0.65 = +1.03 D. Total F = 1.22 + 1.03 = +2.25 D, so f = 1 / 2.25 = 0.445 m = 44.5 cm. Answer: 44.5 cm. Both surfaces come out PLUS here even though one is concave, because the back surface of a meniscus has a negative radius and a negative (1 - n), and two negatives give plus. That sign pair is the whole difficulty."}'),
  ('07cda90b-44','{"options": ["0.30x", "0.79x", "0.38x", "1.26x"], "correct": 2, "explanation": "Concave lens f = -30 in (2.5 ft), object u = -50 in. 1/v = 1/f + 1/u = -1/30 - 1/50 = -0.0533, v = -18.75 in; magnification = v/u = 18.75/50 = 0.38x. Minified, upright image, m = 0.38."}'),
  ('5957901f-3k','{"options": ["Real, inverted and magnified", "Real, inverted and same size as the object", "Real, inverted and minified", "No image is formed"], "correct": 3, "explanation": "A +5.00 D lens has f = 20 cm and the object sits at 20 cm (the focal point), so no finite image forms (rays leave parallel). Object at F = no image."}'),
  ('3aaadf44-3r','{"options": ["4.67 m", "-1.27 m", "-4.67 m", "1.27 m"], "correct": 1, "explanation": "Concave lens f = -2 m, object u = -3.5 m. 1/v = 1/f + 1/u = -0.5 - 0.2857 = -0.7857, v = -1.27 m (virtual, same side). Image at -1.27 m."}'),
  ('431463bc-2r','{"options": ["2 cm", "2 mm", "5 cm", "5 mm"], "correct": 3, "explanation": "Prentice: decentration (cm) = prism/power = 3/6.00 = 0.5 cm = 5 mm. 5 mm of decentration gives the 3-prism base-in effect."}'),
  ('690a9153-4r','{"options": ["The size of the image will increase", "The size of the image will decrease", "The size of the image will remain the same", "There will be no image formed on the camera"], "correct": 0, "explanation": "In a pinhole camera, moving the object toward the pinhole makes the image larger (image size grows as object distance shrinks). Closer object = bigger pinhole image."}'),
  ('699f0f45-2h','{"options": ["Prentice rule", "Properties of prism", "Dennet’s Method", "Law of Illumination"], "correct": 2, "explanation": "A prism that deviates a ray by 1/100 of a radian is the CENTRAD, the angular unit introduced by Dennet (Dennet''s method). It differs from the prism diopter (Prentice rule), which is 1 cm of deviation at 1 metre. 1/100 radian = Dennet''s centrad."}'),
  ('8bc3359e-2e','{"options": ["Prism Base Out", "Prism Base In", "Prism Base Up", "Prism Base Down"], "correct": 1, "explanation": "Exotropia (an eye turned out) is corrected/aligned with base-IN prism (apex toward the deviation). For the non-seeing eye the prism is cosmetic but still base-in for an exo. Exo = base-in."}'),
  ('9cf463f6-2s','{"options": ["Prism Base Out", "Prism Base In", "Prism Base Up", "Prism Base Down"], "correct": 0, "explanation": "Esotropia (an eye turned in) is corrected with base-OUT prism. The 20/40 acuity means the eye still sees, so a real correcting prism is warranted. Eso = base-out."}'),
  ('223ff508-17','{"options": ["-2.00 sph = -0.50 cx 65", "+2.00 sph = -0.50 cx 65", "+2.00 sph = -3.50 cx 65", "+2.00 sph = +0.50 cx 65"], "correct": 1, "explanation": "Two crossed cylinders on perpendicular axes: +2.00 cx 155 and +1.50 cx 65 combine to +2.00 sph + (1.50 - 2.00) cx 65 = +2.00 sph = -0.50 cx 65. Crossed-cyl transpose: keep one as sphere, the difference becomes the cylinder."}'),
  ('3596d70d-1z','{"options": ["-3.50 D", "-1.50 D", "+8.00 D", "+4.50 D"], "correct": 3, "explanation": "A cylinder acts 90 degrees away from its own axis. With the axis at 180, the cyl power sits entirely in the 90 (vertical) meridian and contributes nothing at 180. So the HORIZONTAL (180) meridian carries the sphere alone: +4.50 D. The vertical (90) meridian carries +4.50 + (-3.50) = +1.00 D. Answer: +4.50 D. Trap: reading ''cx 180'' as though the cyl acts along 180. It is the axis, not the power meridian, and the two are always perpendicular."}'),
  ('1ae72815-20','{"options": ["Optical Zone", "Peripheral Curve", "Base Curve", "Edge Thickness"], "correct": 2, "explanation": "The base curve primarily determines how a contact lens fits the cornea (the relationship of lens back surface to corneal curvature). Optic zone and peripheral curve refine it. Fit on cornea = base curve."}'),
  ('649bcad6-25','{"options": ["Lens Diameter", "Water Content", "Base Curve", "Lens Material"], "correct": 3, "explanation": "Oxygen permeability (Dk) is a property of the lens MATERIAL. Water content and thickness affect transmissibility (Dk/t) but the intrinsic permeability is material-based. Oxygen permeability = material."}'),
  ('c86871b9-2e','{"options": ["Edge Lift", "Prism Ballast", "Lens Thickness", "Base Curve"], "correct": 1, "explanation": "Prism ballast (a thicker inferior zone) stabilizes a toric soft lens against rotation using gravity and lid forces. Base curve and thickness do not orient the lens. Toric stabilization = prism ballast (or thin zones)."}'),
  ('fdbf35b5-22','{"options": ["Peripheral Curve", "Central Thickness", "Edge Lift", "Optic Zone"], "correct": 0, "explanation": "The peripheral curve of an RGP creates edge lift that drives tear exchange under the lens with each blink. Tear pumping = peripheral curve/edge lift."}'),
  ('1b4b5eb0-46','{"options": ["8.6 mm", "8.0 mm", "9.0 mm", "8.4 mm"], "correct": 1, "explanation": "For a steep cornea you need a steeper (smaller radius) base curve; among the choices 8.0 mm is the steepest. Smaller mm radius = steeper. Steep cornea = 8.0 mm BC."}'),
  ('932920b9-2m','{"options": ["Tight adherence with minimal movement", "Adequate centration and coverage with 0.5-1.0 mm of movement", "Excessive movement with lid interaction", "Loose fit with significant decentration"], "correct": 1, "explanation": "A well-fitted soft lens shows adequate centration and full corneal coverage with about 0.5 to 1.0 mm of movement on blink. Too tight = no movement; too loose = excess movement. Ideal soft fit = centered with slight movement."}'),
  ('45976b17-52','{"options": ["-6.25 S", "-6.25 S = -0.25 cyl x 180", "-6.50 S", "-6.50 S = -0.50 cyl x 180"], "correct": 0, "explanation": "Vertex distance matters beyond about +/-4.00 D, because the spectacle sits 12 mm in front of the cornea while a contact lens sits on it. Step 1, take the spherical equivalent, since a low cyl is folded into a spherical soft lens: SE = -6.50 + (-0.50/2) = -6.75 D. Step 2, move it to the cornea: F_CL = F / (1 - d x F) with d = 0.012 m. = -6.75 / (1 - 0.012 x -6.75) = -6.75 / 1.081 = -6.24, so -6.25 S. Answer: -6.25 S. Direction check: a minus lens moved CLOSER to the eye needs LESS minus, and -6.25 is less minus than -6.50. If your answer came out stronger, the sign in the denominator is flipped. On the cyl: vertexing each meridian gives -6.03 and -6.46, a residual cyl of only -0.43, which is why the spherical soft lens carries it as spherical equivalent rather than as a -0.25 cyl."}'),
  ('1e7f74e7-2g','{"options": ["Superior decentration", "Excessive lens movement", "Conjunctival indentation", "Blurred vision upon blinking"], "correct": 2, "explanation": "Conjunctival indentation (a compression ring at the lens edge) is a classic sign a soft lens is too tight. Excessive movement is the opposite (too loose). Tight lens = conjunctival indentation."}'),
  ('c8e05ae1-1s','{"options": ["Central pooling with peripheral clearance", "Peripheral pooling with central touch", "Uniform tear film thickness across the lens", "Large central touch with minimal edge clearance"], "correct": 2, "explanation": "An optimally aligned RGP shows a near-UNIFORM tear film (light, even fluorescein) across the lens — neither central pooling (apical clearance = steep) nor central touch/bearing (apical touch = flat). Cross-link: pooling vs touch is the whole fluorescein-pattern logic in Q130/Q137. Mnemonic: ''even green = on the K.''"}'),
  ('8eb68fbb-3k','{"options": ["Flat base curve", "Small diameter", "Steep base curve", "Thick edge design"], "correct": 2, "explanation": "A keratoconic cornea is steep/conical, so a steeper base curve is most crucial to vault and align the large RGP. A flat curve would bear on the apex. Keratoconus = steeper base curve."}'),
  ('e2c711ff-4j','{"options": ["Flatten the base curve", "Increase the lens power", "Increase the optical zone diameter", "Steepen the base curve"], "correct": 3, "explanation": "If PLUS over-refraction improves vision on an RGP, the lens is too FLAT (insufficient apical clearance / flat tear lens). STEEPENING the base curve adds the needed plus tear lens and corrects the fit. Rule (SAM-FAP): Steeper Adds Minus tear lens, Flatter Adds Plus — so to gain plus, flatten... but here the FIT is flat and the PATIENT needs more plus power overall, so steepen to build a plus tear reservoir. Reason it through the tear lens each time."}'),
  ('23bdba8a-1s','{"options": ["No movement", "0.5-1.0 mm of movement", "1.0-2.0 mm of movement", "Excessive movement with lens displacement"], "correct": 2, "explanation": "A properly fitted RGP lags about 1.0 to 2.0 mm on each blink (more movement than a soft lens). Excess displacement means too flat/loose. RGP blink movement = 1 to 2 mm."}'),
  ('6c7319fb-3c','{"options": ["Monovision", "Bifocal lenses", "Multifocal lenses", "EDOF lenses"], "correct": 2, "explanation": "Multifocal contact lenses provide simultaneous clear vision at all distances but require neural adaptation. Monovision sacrifices one eye for near; bifocals alternate. All-distance with adaptation = multifocal."}'),
  ('7e688429-2y','{"options": ["Refitting with multifocal lenses", "Increasing the add power", "Adjusting the dominant eye lens for distance", "Switching to bifocal glasses"], "correct": 2, "explanation": "Ghosting in monovision is managed by adjusting the dominant eye''s lens for distance (optimizing the distance eye). Adding more add or switching usually worsens or sidesteps it. Monovision ghosting = re-balance the dominant (distance) eye."}'),
  ('922e9153-2e','{"options": ["Simplified fitting process", "Enhanced contrast sensitivity", "Extended range of clear vision at multiple distances", "Reduced adaptation period"], "correct": 2, "explanation": "Extended depth of focus (EDOF) lenses give an extended continuous range of clear vision across distances. That continuous range is their main selling point. EDOF = extended range of focus."}'),
  ('d4c22218-20','{"options": ["Decreased contrast sensitivity", "Need for frequent lens replacement", "Difficulty in achieving stable vision at all distances", "Increased risk of lens deposits"], "correct": 2, "explanation": "A common drawback of bifocal contact lenses is difficulty achieving stable, consistent vision at all distances (image jump/balance issues). Bifocal CL = unstable vision across distances."}'),
  ('10501b2a-2l','{"options": ["Corneal diameter", "Corneal thickness", "Corneal curvature", "Corneal endothelial cell density"], "correct": 2, "explanation": "Corneal curvature is the key characteristic for selecting the initial orthokeratology lens (the lens is designed to reshape that curvature). Ortho-K starts from corneal curvature."}'),
  ('c0420ac5-33','{"options": ["Lens decentration", "Insufficient overnight lens wear time", "Too flat BC", "Too steep BC"], "correct": 1, "explanation": "Ortho-K reshapes the epithelium overnight and the effect REGRESSES through the day. End-of-day vision blur usually means INSUFFICIENT overnight wear time (incomplete or fading reshaping). Decentration causes ghosting/glare; BC errors give over/under-correction rings. Cross-link: mechanism in Q121 explains why regression happens."}'),
  ('7ce1f52f-28','{"options": ["Epithelial flattening", "Corneal stromal remodeling", "Redistribution of corneal epithelial cells", "Increase in corneal hydration"], "correct": 2, "explanation": "Orthokeratology works mainly by redistributing the corneal EPITHELIAL cells (central thinning, mid-peripheral thickening), not by stromal remodeling. Ortho-K = epithelial redistribution."}'),
  ('cbe34e9b-1x','{"options": ["Hyperopia", "Myopia", "Presbyopia", "Astigmatism"], "correct": 1, "explanation": "Orthokeratology is used primarily to correct (and slow) MYOPIA by flattening the central cornea overnight. Ortho-K = myopia control/correction."}'),
  ('62cc06e5-2q','{"options": ["Increased oxygen permeability", "Larger optic zone", "Vaulting of the cornea with no corneal contact", "Easier handling"], "correct": 2, "explanation": "Scleral lenses vault the cornea entirely, resting on the sclera with no corneal contact, which is their key advantage for irregular/diseased corneas. Scleral = corneal vaulting, no touch."}'),
  ('b2a96d13-1m','{"options": ["A patient with mild dry eye syndrome", "A patient with keratoconus and advanced corneal scarring", "A patient with low myopia", "A patient with presbyopia"], "correct": 1, "explanation": "A patient with keratoconus and advanced corneal scarring benefits most from scleral lenses (they vault the irregular cornea and create a smooth optical surface). Severe irregular cornea = scleral."}'),
  ('f3c39806-2j','{"options": ["Loose peripheral fit", "Excessive lens movement", "Improper lens diameter", "Overly steep base curve"], "correct": 0, "explanation": "Midday fogging in scleral wear typically comes from a loose peripheral fit letting debris/tears seep into the bowl. A loose edge = fogging. Scleral midday fog = loose periphery."}'),
  ('79692b42-2c','{"options": ["Saline solution", "Multipurpose solution", "Tap water", "Hydrogen peroxide"], "correct": 0, "explanation": "The scleral lens bowl is filled with preservative-free SALINE before insertion. Tap water and disinfectants are unsafe on the eye. Scleral bowl = preservative-free saline."}'),
  ('085e9152-29','{"options": ["High myopia", "Cosmetic improvement of disfigured eyes", "Correcting astigmatism", "Presbyopia"], "correct": 1, "explanation": "Prosthetic contact lenses are used mainly for cosmetic improvement of disfigured eyes (masking scars, restoring appearance). Cosmetic restoration = prosthetic lens."}'),
  ('c12ce970-2k','{"options": ["UV protection", "Custom pupil size and color", "High oxygen permeability", "Edge thickness"], "correct": 1, "explanation": "For aniridia (absent iris), the critical prosthetic feature is a custom artificial pupil size and iris color to control glare and appearance. Aniridia = custom pupil/iris."}'),
  ('f51f9f23-29','{"options": ["Measure corneal thickness", "Determine corneal curvature", "Assess tear film quality", "Evaluate corneal endothelial health"], "correct": 1, "explanation": "Keratometry before contact-lens fitting determines corneal curvature (the K readings that guide base-curve selection). Pre-fit K = corneal curvature."}'),
  ('7f65b3ab-26','{"options": ["Regular astigmatism", "Keratoconus", "Presbyopia", "Myopia"], "correct": 1, "explanation": "Topography-guided fitting is most useful in keratoconus, where the irregular surface needs detailed mapping for lens design. Irregular cone = topography-guided fit."}'),
  ('fc24140a-1u','{"options": ["Central pooling with mid-peripheral clearance", "Uniform central fluorescein pattern with 0.5-1 mm edge clearance", "Central touch with peripheral pooling", "Inferior touch with superior pooling"], "correct": 1, "explanation": "A well-fitted RGP shows a uniform (alignment) fluorescein pattern with about 0.5 to 1 mm of edge clearance. Even fluorescein plus slight edge lift = good RGP fit."}'),
  ('84d48fa9-21','{"options": ["To assess lens movement and centration", "To determine refractive error", "To evaluate corneal curvature", "To measure intraocular pressure"], "correct": 0, "explanation": "Post-fit slit-lamp examination assesses lens movement and centration (and surface/cornea response). It is not for refraction or IOP. After fitting, check movement and centration."}'),
  ('ecc05a4d-48','{"options": ["Excellent suitability", "Marginal suitability; lens type should be carefully selected", "Poor suitability; consider tear film stabilization first", "No relevance to contact lens wear"], "correct": 2, "explanation": "A TBUT under 5 seconds signals poor tear stability, so lens wear is poorly suited until the tear film is stabilized first. Very low TBUT = stabilize tears before fitting."}'),
  ('7d64e916-29','{"options": ["To measure corneal curvature", "To assess the palpebral conjunctiva for papillae or follicles", "To evaluate tear film stability", "To determine lens diameter"], "correct": 1, "explanation": "Lid eversion lets you inspect the palpebral conjunctiva for papillae or follicles (signs of GPC or allergy) before/while fitting. Flip the lid to check for papillae."}'),
  ('23c9a444-2m','{"options": ["Soft spherical lens", "Soft toric lens", "RGP lens", "Scleral lens"], "correct": 2, "explanation": "Irregular astigmatism is best corrected with a rigid (RGP) lens, which masks the irregular surface with a smooth tear lens. Irregular astigmatism = RGP."}'),
  ('2c4bb5b7-33','{"options": ["With the Rule astigmatism", "Against the Rule astigmatism", "Oblique astigmatism", "Irregular astigmatism"], "correct": 0, "explanation": "K of 45.00 @ 180 and 47.50 @ 90 means the steeper power is vertical, which is WITH-the-rule astigmatism. Steeper vertical meridian = with-the-rule."}'),
  ('ec98bbb0-2t','{"options": ["Keratoconus", "Regular astigmatism", "Corneal dystrophy", "Post-LASIK ectasia"], "correct": 1, "explanation": "A symmetric bow-tie of hot (steep) colors on topography is the hallmark of regular astigmatism. Keratoconus shows an asymmetric, inferiorly displaced pattern. Symmetric bow-tie = regular astigmatism."}'),
  ('e7dae3a9-3c','{"options": ["Steepen the base curve", "Flatten the base curve", "Increase the lens diameter", "Decrease the lens diameter"], "correct": 1, "explanation": "Central pooling with mid-peripheral touch means the lens is too steep (apical clearance), so you flatten the base curve. Central pooling = steep fit = flatten BC."}'),
  ('bb344c74-2u','{"options": ["Poor lens fit", "Allergic reaction to lens solution", "Inadequate tear film", "Lens overwear"], "correct": 1, "explanation": "DIFFUSE (widespread) corneal staining after CL wear most often reflects SOLUTION toxicity/hypersensitivity — a preservative reaction (e.g., to a multipurpose solution) producing scattered punctate staining across the whole cornea. Focal/localized staining points to mechanical/fit causes; the ''diffuse'' descriptor is the key to a solution reaction. Management: switch to a preservative-free/peroxide system. Cross-link: solution-induced corneal staining (SICS)."}'),
  ('473a278e-2n','{"options": ["Corneal neovascularization", "Lid wiper epitheliopathy", "Conjunctival papillae", "Dry eye syndrome"], "correct": 0, "explanation": "Corneal neovascularization is a classic complication of extended (overnight) wear from chronic hypoxia. Extended wear = hypoxic neovascularization."}'),
  ('95b5deb1-4d','{"options": ["Giant papillary conjunctivitis", "Microbial keratitis", "Corneal edema", "Contact lens-induced acute red eye (CLARE)"], "correct": 1, "explanation": "Pain, redness, and corneal infiltrates in a soft-lens wearer point to microbial keratitis (a sight-threatening infection) until proven otherwise. Infiltrates plus pain = microbial keratitis."}'),
  ('a9b6b48e-1o','{"options": ["High water content lenses", "Poor blink rate", "Lens material with low oxygen permeability", "Inadequate tear film production"], "correct": 3, "explanation": "CL-associated dry eye is driven primarily by INADEQUATE tear film / production (and lens-induced tear instability and evaporation) — the lens disrupts and depletes a marginal tear film. Water content and Dk contribute, but the core problem is a deficient tear supply. Cross-link: assess with Schirmer (Q142) and TBUT (Q132); treat MGD (Q144)."}'),
  ('c0504a44-2a','{"options": ["Schirmer’s test", "Tear break-up time (TBUT)", "Fluorescein staining", "Meibography"], "correct": 0, "explanation": "Schirmer''s test measures aqueous tear production (volume), the quantity assessment used in lens wearers. TBUT measures stability, not amount. Tear quantity = Schirmer''s."}'),
  ('4577b2ff-2x','{"options": ["Recommend Silicone Hydrogel", "Prescribe artificial tears and continue lens wear", "Discontinue contact lens wear permanently", "Switch to RGP lenses"], "correct": 0, "explanation": "A borderline-TBUT (<7 s) CL wearer is best managed by refitting into SILICONE HYDROGEL (low dehydration, high Dk, surface treatments) to improve comfort and surface health — better than stopping lenses permanently or just adding drops. (Keyed: recommend silicone hydrogel.) Cross-link: frankly low TBUT (<5 s, Q132) means fix the surface first before fitting at all."}'),
  ('237dd6ff-30','{"options": ["Increased tear production", "Blocked meibomian glands", "Excessive lipid layer thickness", "Hyperemia of the conjunctiva"], "correct": 1, "explanation": "Meibomian gland dysfunction shows blocked/obstructed meibomian glands, reducing the tear lipid layer and causing evaporative dry eye. MGD = blocked oil glands."}'),
  ('76d19229-2d','{"options": ["High water content soft lenses", "Silicone hydrogel lenses", "RGP lenses", "Scleral lenses"], "correct": 3, "explanation": "Moderate dry eye does best in SCLERAL lenses — the fluid reservoir continuously bathes the cornea, giving comfort and even therapeutic benefit where soft and RGP lenses fail. High-water soft lenses paradoxically WORSEN dryness by dehydrating and pulling from the tear film. Cross-link: same vaulting/reservoir advantage as Q123/Q145; sclerals double as therapeutic lenses for ocular surface disease."}'),
  ('c7f197ea-1z','{"options": ["Better protection against injury", "Improved peripheral vision", "Easier to clean", "Less expensive"], "correct": 1, "explanation": "Contact lenses give improved peripheral vision (no frame edges, full field) over glasses for sports. CL for sports = wider field, no frame."}'),
  ('c501e819-2j','{"options": ["High water content soft lenses", "Low water content soft lenses", "Silicone hydrogel lenses", "Rigid gas-permeable lenses"], "correct": 2, "explanation": "For a swimmer, SILICONE HYDROGEL daily lenses (high Dk, single-use, discarded after water exposure) best balance oxygen and infection control. (Keyed: silicone hydrogel.) But the real safety rule is goggles over the lenses and discard immediately afterward, because water carries Acanthamoeba (Q148). Pearl: ''water + lenses → goggles + daily disposables.''"}'),
  ('39fd9282-1y','{"options": ["Increased UV exposure", "Corneal abrasion", "Lens displacement", "Infection from waterborne pathogens"], "correct": 3, "explanation": "The key risk of wearing lenses during water sports is infection from waterborne pathogens (notably Acanthamoeba). Lenses in water = microbial infection risk."}'),
  ('3aa1c3cc-2f','{"options": ["Soft contact lenses", "RGP lenses", "Scleral lenses", "Hybrid lenses"], "correct": 0, "explanation": "For contact sports, soft lenses provide the best protection/retention (they stay put and will not shatter, unlike rigid lenses that can dislodge). Contact sports = soft lenses."}'),
  ('93159f7b-35','{"options": ["Reduced oxygen permeability", "Corneal abrasions", "Lens dehydration", "Lens contamination"], "correct": 3, "explanation": "In dusty/debris-heavy INDUSTRIAL settings the major CL concern is lens CONTAMINATION — trapped particulate under the lens raising infection and abrasion risk — so sealed protective eyewear is essential and many such environments discourage CL wear entirely. Cross-link: occupational eye safety overlaps Primary Eye Care; pair with impact eyewear standards (ANSI Z87.1)."}'),
  ('9f555a5f-2b','{"options": ["Soft daily disposable lenses", "Silicone hydrogel lenses", "RGP lenses", "Scleral lenses"], "correct": 2, "explanation": "In a chemical environment, rigid (RGP) lenses absorb fewer chemicals than soft lenses, making them the safer lens if any is worn (with mandatory eye protection). VERIFY: many guidelines discourage lenses entirely here, so confirm the intended answer."}'),
  ('69dd60f6-3a','{"options": ["Real, inverted and magnified", "Real point image", "Virtual, erect and minified", "Virtual point image"], "correct": 1, "explanation": "An object at infinity in front of a concave mirror focuses incoming parallel rays to the focal point, forming a real point image. Infinity into concave mirror = real point image at F."}'),
  ('a39cb1e5-3w','{"options": ["Real, inverted and magnified", "Real point image", "Virtual, erect and minified", "Virtual point image"], "correct": 3, "explanation": "An object at infinity in front of a convex mirror forms a virtual point image at the focal point behind the mirror. Infinity into convex mirror = virtual point image."}'),
  ('dce2b5af-4i','{"options": ["1 ft 9 inches", "3 ft 7 inches", "4 ft 2 inches", "5 ft 6 inches"], "correct": 1, "explanation": "A plane mirror forms the image as far behind as the object is in front: 43 in behind = 3 ft 7 in. Image distance equals object distance for a plane mirror."}'),
  ('bb07c791-3e','{"options": ["60 inches", "63 inches", "68 inches", "72 inches"], "correct": 2, "explanation": "A plane mirror image is the same size as the object: 5 ft 8 in = 68 in. Plane mirror magnification = 1."}'),
  ('5d9e382d-3m','{"options": ["2", "3", "4", "7"], "correct": 3, "explanation": "Two plane mirrors at angle theta divide the space around them into 360/theta sectors. One sector holds the real object, every other sector holds an image, so the count is 360/theta - 1. 360/45 = 8 sectors, so 8 - 1 = 7 images. Answer: 7. The minus one is the object''s own sector, which is the step people skip. Note the formula is only clean when 360/theta comes out a whole number, as it does here."}'),
  ('79b81d03-4s','{"options": ["3.01 ft", "3.08 ft", "3.12 ft", "3.30 ft"], "correct": 1, "explanation": "The minimum plane-mirror height to see your whole image is half your height, independent of distance: 74 in/2 = 37 in = 3.08 ft. Min mirror = half your height."}'),
  ('e5198789-3b','{"options": ["inverted", "Real", "Virtual", "Perverted"], "correct": 2, "explanation": "An image formed by prolonging (extending) the reflected/refracted rays behind the mirror is a virtual image. Rays only appear to come from it. Prolonged rays = virtual image."}'),
  ('e7b283de-25','{"options": ["inverted", "Perverted", "Real", "Virtual"], "correct": 1, "explanation": "An erect but laterally reversed image is called a perverted image (as in a plane mirror). Erect + left-right flipped = perverted."}'),
  ('12f2b8d9-5m','{"options": ["3.90 ft", "9.10 ft", "19.25 ft", "29. 50 ft"], "correct": 2, "explanation": "Convex mirror, f = -11 ft, image virtual 7 ft behind (v = -7). 1/u = 1/f - 1/v = -1/11 + 1/7 = 0.0519, u = 19.27 ft. Nola stands about 19.25 ft from the mirror."}'),
  ('5586ab14-4o','{"options": ["30 cm", "45 cm", "65 cm", "90 cm"], "correct": 1, "explanation": "Erect, magnified (x3) virtual image means a concave mirror with the object inside F. Using u = 30, v = -90 (m = 3): 1/f = 1/(-90) + 1/30 = 0.0222, f = 45 cm. Concave mirror, f = 45 cm."}'),
  ('29e69a58-6j','{"options": ["230.65 m", "266.00 m", "285.25 m", "365.75 m"], "correct": 1, "explanation": "Aquaman underwater sees Superman raised by refraction: apparent height = real x n(water) = 200 x 1.33 = 266 m. Object in air seen from water appears farther by the water index."}'),
  ('f936e77d-65','{"options": ["4.45 cm", "9.75 cm", "13.25 cm", "cm"], "correct": 0, "explanation": "Lateral displacement d = t sin(i - r)/cos(r). With i = 22, n = 1.586: sin(r) = sin22/1.586, r = 13.66; d = 30 sin(8.34)/cos(13.66) = 4.45 cm. Slab displacement formula gives 4.45 cm."}'),
  ('b34ea44d-1t','{"options": ["40.63 degrees", "43.75 degrees", "60.84 degrees", "78.69 degrees"], "correct": 2, "explanation": "Critical angle: sin(theta_c) = n2/n1 = 1.33/1.523 = 0.873, theta_c = 60.84 degrees. Crown-water critical angle = 60.84 degrees."}'),
  ('9e666f12-4a','{"options": ["40.63 degrees", "43.75 degrees", "60.84 degrees", "78.69 degrees"], "correct": 0, "explanation": "Snell: sin(r) = sin(76)/1.498 = 0.648, r = 40.4 degrees, about 40.63. Refraction into CR-39 from air bends to about 40.6 degrees."}'),
  ('d33428fb-3s','{"options": ["It will be reflected internally", "It will be refracted toward the normal ray", "It will be refracted away from the normal ray", "It will be absorbed by the diamond"], "correct": 1, "explanation": "Entering a denser medium (air into diamond), light refracts TOWARD the normal. Slower medium = bend toward normal."}'),
  ('c8b8c2b9-43','{"options": ["It will be reflected internally", "It will be refracted toward the normal ray", "It will be refracted away from the normal ray", "It will be absorbed by the diamond"], "correct": 1, "explanation": "Going from water into denser crown glass, light refracts toward the normal (and the 27-degree angle is well below the critical angle, so it transmits). Into denser glass = bend toward normal."}'),
  ('2e61d124-3m','{"options": ["-0.67 m", "-1.5 m", "1.5 m", "2 m"], "correct": 0, "explanation": "Concave lens f = -1 m, object u = -2 m: 1/v = -1 - 0.5 = -1.5, v = -0.67 m (virtual). Image at -0.67 m."}'),
  ('8dc400a7-6d','{"options": ["5 cm", "10 cm", "20 cm", "30 cm"], "correct": 2, "explanation": "Real, inverted, half-size image (m = -0.5) at 30 cm means object at 60 cm. 1/f = 1/30 - 1/(-60) = 0.05, f = 20 cm. Converging lens, f = 20 cm."}'),
  ('7fa89280-3u','{"options": ["Virtual, erect minified", "Virtual, erect, magnified", "Virtual, inverted, minified", "Virtual, inverted, magnified"], "correct": 0, "explanation": "A concave (diverging) lens always forms a virtual, erect, minified image regardless of object distance. Concave lens = virtual, erect, smaller."}'),
  ('5321e853-45','{"options": ["0.30 x", "0.38x", "0.79 x", "1.26 x"], "correct": 1, "explanation": "Same setup as before: concave lens f = -30 in, object 50 in, magnification = 0.38x. Minified upright image, m = 0.38."}'),
  ('7711bcb2-5a','{"options": ["4.2 meters", "3.7 meters", "7.6 meters", "3.1 meters"], "correct": 0, "explanation": "Shadow height = object x (screen-from-source/object-from-source) = 1.6 x (525/200) = 4.2 m. Shadow scales with the distance ratio from the point source."}'),
  ('c0208664-3r','{"options": ["63 degrees", "59 degrees", "49 degrees", "34 degrees"], "correct": 3, "explanation": "The sun''s elevation is the angle whose tangent is the pole''s height over its shadow''s length. tan(theta) = 30 / 45 = 0.6667, so theta = arctan(0.6667) = 33.7 degrees, about 34. Answer: 34 degrees. Trap: inverting the ratio to 45/30 = 1.5 gives 56.3 degrees, which is the complement. If your answer and the expected one add to 90, you divided the wrong way round. Sanity check: the shadow is LONGER than the pole, so the sun is low and the angle must be under 45."}'),
  ('997aa969-7q','{"options": ["50 cm", "60 cm", "70 cm", "40 cm"], "correct": 0, "explanation": "Shadow = object x (screen-from-source/object-from-source) = 25 mm x (200/10) = 500 mm = 50 cm. Distance ratio x object size."}'),
  ('7f04ea79-4f','{"options": ["1560 cm", "876 cm", "437 cm", "132 cm"], "correct": 0, "explanation": "shadow/object = screen/object-distance: 1800/150 = screen/1300, screen = 15600 mm = 1560 cm. Solve the ratio for screen distance."}'),
  ('7cd91044-4s','{"options": ["The size of the image will increase", "The size of the image will decrease", "The size of the image will remain the same", "There will be no image formed on the camera"], "correct": 0, "explanation": "Moving the object toward the pinhole enlarges the image (image size rises as object distance falls). Closer object = larger pinhole image."}'),
  ('3a9a60c3-50','{"options": ["14 meters", "11 meters", "20 meters", "32 meters"], "correct": 0, "explanation": "object = shadow x (object-from-source/screen-from-source) = 70 x (20/100) = 14 m. Back out object height from the ratio."}'),
  ('b270f297-14','{"options": ["1.923", "1.58", "1.33", "1.49"], "correct": 1, "explanation": "Light flint glass has an index of about 1.58 (dense flint is about 1.70). Light flint = 1.58."}'),
  ('01683f90-59','{"options": ["Prism", "Diamond", "Mirror", "Lens"], "correct": 0, "explanation": "A refracting medium of two plane surfaces meeting at an apex with a base is a prism. Two planes meeting at an apex = prism."}'),
  ('2db8c7a7-1b','{"options": ["Refracting Surface", "Base", "Apex", "Principal Section"], "correct": 2, "explanation": "The apex is where the two refracting plane surfaces of a prism meet; the base is opposite. Surfaces meet at the apex."}'),
  ('07d48a6f-19','{"options": ["Luminous Intensity", "Luminous Flux", "Illumination", "Illuminance"], "correct": 1, "explanation": "Luminous flux is the rate of flow of luminous energy from a source (measured in lumens). Intensity is per solid angle; illuminance is per area. Rate of luminous energy = luminous flux."}'),
  ('66c38309-23','{"options": ["100 mc", "4 lumen", "6.25 mc", "6.25 steradians"], "correct": 2, "explanation": "E = I/d^2 = 100/4^2 = 6.25 (lux/metre-candle). Inverse-square law again: 6.25 mc."}'),
  ('b397e6e7-12','{"options": ["The further the object is from the prism the more it is displaced.", "Ray of light passing through a prism are bent toward the base", "Rays that are diverging as they enter the prism will diverge as they leave.", "Prisms causes rays of light to converge or diverge."], "correct": 3, "explanation": "The incorrect statement is that prisms cause rays to converge or diverge; prisms only DEVIATE rays (they do not add or remove vergence). Light still bends toward the base, and entering vergence is preserved. Prisms deviate, they do not converge/diverge."}'),
  ('c3b11b77-3c','{"options": ["Chromatic Aberration", "Specific Gravity", "Abbe Value", "Index of Refraction"], "correct": 2, "explanation": "Abbe value is the reciprocal of dispersive power and measures the ability to hold the spectrum together (resist chromatic dispersion). Reciprocal of dispersive power = Abbe value."}'),
  ('8ce5cbf9-2','{"options": ["+3.50", "+3.25", "-3.50", "-3.25"], "correct": 0, "explanation": "EXCLUDED FROM SCORING. The stem was lost in PDF extraction (only ''75?'' survives). Needs the source paper to rebuild."}'),
  ('6618e604-2j','{"options": ["+50.00D", "-50.00D", "-4.50D", "+4.50D"], "correct": 3, "explanation": "EXCLUDED FROM SCORING. The surface powers were lost in extraction, leaving only the 3 cm thickness and n = 1.58, so the equivalent power cannot be computed. Needs the source paper."}'),
  ('cf206f85-4m','{"options": ["+1.00D", "-1.00D", "+8.50D", "+8.00D"], "correct": 2, "explanation": "Equivalent power at a new vertex: corneal-plane power of +8.75 at 13 mm is +9.87; the lens at 17 mm = 9.87/(1+0.017x9.87) = +8.50 D. Moving a plus lens out needs less plus, so +8.50 D."}'),
  ('058c9c06-3u','{"options": ["+1.00D", "-1.00D", "+7.75D", "-7.75D"], "correct": 3, "explanation": "Moving a lens AWAY from the eye reduces how much minus the eye actually sees, so the effective power gets weaker, not stronger. Shift = 16 - 12 = 4 mm = 0.004 m. F_eff = F / (1 - d x F) = -8.00 / (1 - 0.004 x -8.00) = -8.00 / 1.032 = -7.75 D. Answer: -7.75 D. Sanity check without arithmetic: a minus lens further from the eye is less effective minus, so the number moves toward zero. -7.75 is closer to zero than -8.00, so the direction is right. If you got -8.25 you added the correction instead of dividing by (1 - dF)."}'),
  ('6c429b5e-3','{"options": ["+12.50s=-1.75cx180", "+12.50s=-1.75cx90", "+11.50s=-1.50cx90", "+11.50s=-1.50cx180"], "correct": 0, "explanation": "EXCLUDED FROM SCORING. The stem was lost in extraction (only ''5mm.'' survives). Needs the source paper."}'),
  ('cd26eb79-2k','{"options": ["Decrease", "Increase", "Same", "Change sign"], "correct": 0, "explanation": "Moving a plus lens toward the eye decreases its effective power. Plus lens closer = less effective plus."}'),
  ('26ccbb47-2m','{"options": ["Decrease", "Increase", "Same", "Change sign"], "correct": 1, "explanation": "Moving a plus lens away from the eye increases its effective power (you need less plus at the spectacle plane, so the same lens does more). Plus lens farther = more effective plus."}'),
  ('0dfb7844-21','{"options": ["Plus spherical", "Minus spherical", "Bifocal lens", "Plano lens"], "correct": 1, "explanation": "Sign of the Rx tells you the lens form: a minus number (–2.50 D) is myopic correction needing a minus (concave, diverging) sphere that pushes the image back onto the retina. Plus spheres converge light for hyperopia; bifocals add near power for presbyopia; plano has zero power. Cross-link (Physio Optics): myopia = eye too long / too powerful, so you ADD divergence to neutralize it. Cue: read the SIGN first, then the suffix ''spherical'' vs ''cylindrical.''"}'),
  ('5b593a76-1z','{"options": ["High Abbe value", "Low Abbe value", "Thicker edge design", "Aspheric lens curvature"], "correct": 0, "explanation": "Chromatic aberration is color fringing from dispersion — the lens bends short (blue) wavelengths more than long (red). A material resists dispersion when its Abbe value (constringence, V-number) is HIGH, so high Abbe = least color fringe. Low Abbe (e.g., polycarbonate ~30, dense flint) disperses badly. Edge design and asphericity fight thickness and oblique astigmatism, not color. Mnemonic: ''High Abbe = Honest color.''"}'),
  ('ee565863-1y','{"options": ["0.6Δ base out", "1.2Δ base out", "0.6Δ base in", "1.2Δ base in"], "correct": 1, "explanation": "Prentice''s Rule: prism (Δ) = F × d(cm) = 3.00 × 0.4 cm = 1.2Δ. Direction: a PLUS lens acts like two prisms base-to-base, so decentering it OUTWARD (temporally) puts a base-OUT prism in front of the eye. Distractors halve the decentration or flip the base. Cross-link (Dispensing): this is the same math behind induced prism from a wrong PD. Mnemonic for base: plus lens, base follows the decentration direction; minus lens, base is opposite."}'),
  ('783482cf-1b','{"options": ["The prism is maximum", "Light passes without deviation", "Lens thickness is the thinnest", "The curvature is the steepest"], "correct": 1, "explanation": "The optical center (OC) is the single point where a ray passes straight through with zero deviation — prism is ZERO there, not maximum, and grows linearly with distance from it (that IS Prentice''s Rule). Thickness and curvature relate to lens form, not the OC definition. Cross-link: aligning the OC with the visual axis is why PD and seg height matter."}'),
  ('fe143e11-22','{"options": ["Lower the right temple", "Raise the right temple", "Spread both temples", "Narrow the bridge"], "correct": 1, "explanation": "If the lower rim touches the cheek, that side of the front is sitting too low — RAISE the temple at the ear, which pivots the front up and away from the face. Lowering the temple drops it further; spreading temples or narrowing the bridge changes width/grip, not vertical height. Cue: ''lens too low → raise the temple on that side.''"}'),
  ('9ad7cacd-2b','{"options": ["Incorrect PD measurement", "Incorrect add power", "Incorrect fitting height", "Excessive pantoscopic tilt"], "correct": 2, "explanation": "The ''swim'' / floating sensation in PALs is a positional error — the eye is landing in the wrong part of the corridor, almost always because the lens sits at the wrong vertical height (fitting/seg height). PD and add errors blur the image rather than make it swim; excess pantoscopic tilt mainly induces distance power error. Pearl: swim/sway = adaptation or HEIGHT problem; blur = power/PD problem."}'),
  ('fd8d869b-2c','{"options": ["Segment height", "Pantoscopic tilt", "Interpupillary distance (PD)", "Vertex distance"], "correct": 2, "explanation": "Interpupillary distance (PD) sets the HORIZONTAL placement of the optical centers in front of the pupils, preventing induced horizontal prism. Segment height is the vertical multifocal measure; pantoscopic tilt and vertex distance are fitting angles/distances. Cross-link: wrong PD → horizontal prism by Prentice''s Rule (see Q65)."}'),
  ('58701395-15','{"options": ["Thinner profile", "Reduced magnification distortion", "Wider field of vision", "Lower Abbe number"], "correct": 3, "explanation": "This is a NOT question — find the non-benefit. Aspheric lenses flatten the front curve, giving a thinner, lighter profile, less magnification, and a wider clear field. But asphericity does NOT change the material''s Abbe number, so ''lower Abbe'' is not a benefit (it would be a drawback). Trap: the three real benefits are true statements; the answer is the odd one out. Pearl: asphericity changes SHAPE, not the material''s dispersion."}'),
  ('cc6505d5-11','{"options": ["Effective diameter and decentration", "Lens power only", "Frame color and design", "Index of refraction"], "correct": 0, "explanation": "Minimum blank size (MBS) = effective diameter + 2 × (decentration per lens), with a margin. It depends on how far each OC must be moved and the frame''s effective diameter — geometry, not power, color, or index. Cross-link (Dispensing): MBS decides whether a given prescription can even be cut from a stock blank, especially with large decentration or prism."}'),
  ('c9c847a0-14','{"options": ["Abbe value", "Index of refraction", "Lens coating", "Vertex distance"], "correct": 1, "explanation": "Lens weight tracks material DENSITY, and density rises with refractive index — high-index GLASS is dense and heavy; high-index plastics trade thickness for a denser matrix. Abbe (dispersion), coatings (microns thick), and vertex distance don''t drive weight. Pearl: for a heavy-lens complaint, think index/material first, then aspheric thinning."}'),
  ('fde68b5c-1m','{"options": ["Small circle at nasal side", "Small cross at pupil location", "Triangle at temporal edge", "Horizontal line on the lens"], "correct": 1, "explanation": "The fitting cross is the temporary engraved/inked cross placed at the pupil center for PAL vertical-and-horizontal alignment. The nasal circle plus temporal markings are the PERMANENT micro-engravings (add power and brand logo); there is no horizontal line. Cross-link: locating the permanent marks lets you verify add power and re-mark a remake."}'),
  ('8e839890-z','{"options": ["Spherical aberration", "Vertical imbalance in anisometropia", "Horizontal diplopia", "Excessive pantoscopic tilt"], "correct": 1, "explanation": "A slab-off (bicentric grind) adds base-UP prism to the more-minus (or less-plus) lens to cancel the vertical prismatic imbalance at near in anisometropia. It does nothing for spherical aberration, horizontal diplopia, or tilt. Cross-link (Physio Optics/BV): the imbalance arises because at near the eyes look below the OCs, and Prentice''s Rule gives unequal vertical prism between two unequal-power lenses."}'),
  ('0285ca07-1r','{"options": ["Photochromic coating", "UV protection", "Anti-reflective coating", "Mirror coating"], "correct": 2, "explanation": "Anti-reflective (AR) coating suppresses surface reflections and stray internal light, cutting night headlight glare and ghost images. Photochromics darken in UV (useless at night), UV coating blocks ultraviolet, and mirror coatings reflect light away (for bright sun). Pearl: ''night glare / halos around lights → AR.''"}'),
  ('1ee9fbcc-18','{"options": ["Aspheric plus lens", "Spheric minus lens", "Flat-top bifocal", "Trifocal"], "correct": 0, "explanation": "High hyperopia needs a strong PLUS lens; an aspheric plus design flattens the front curve to cut center thickness, weight, and the magnified ''bug-eye'' look, while improving peripheral optics. Minus lenses are for myopia; bifocal/trifocal address presbyopia, not the base correction. Cross-link: same aspheric rationale as the high-plus and aphakia questions (Q35, Q63)."}'),
  ('60e73f38-y','{"options": ["Distance from pupil to nose bridge", "Distance from cornea to back lens surface", "Distance between optical centers", "Distance between spectacle frame temples"], "correct": 1, "explanation": "Vertex distance is the gap from the BACK surface of the spectacle lens to the front (apex) of the cornea. It matters because effective power changes with this distance once you exceed about ±4.00 D — the basis of vertex conversion when moving an Rx to a contact lens. Mnemonic: ''Vertex = back of lens to front of eye.'' Cross-link: Q43, Q109."}'),
  ('af4a86ff-x','{"options": ["Reflections", "Chromatic aberration", "Weight", "Spherical power"], "correct": 1, "explanation": "High Abbe value = low dispersion = reduced chromatic aberration (same concept as Q2). Abbe doesn''t affect reflections (that''s AR), weight (density), or spherical power. Pearl: any question pairing ''Abbe'' with a benefit is asking about COLOR fringing."}'),
  ('a5285897-1g','{"options": ["UV", "Photochromic", "AR coating", "Mirror"], "correct": 2, "explanation": "AR coating reduces reflected glare including night headlight glare (identical concept to Q13). UV blocks ultraviolet, photochromics darken in sun, mirror coatings reflect bright light — none target night glare. High-yield: AR appears repeatedly; lock it to ''glare/reflections/night driving.''"}'),
  ('17374188-s','{"options": ["Reflection changes wavelength", "Reflected light bends toward the normal", "The angle of incidence equals the angle of reflection", "The angle of incidence is twice the angle of reflection"], "correct": 2, "decode": "Law of reflection: angle of incidence EQUALS angle of reflection.", "ow": ["Reflection does not change wavelength.", "Reflection bounces light; it does not refract toward the normal.", "Correct. Angle of incidence equals angle of reflection.", "The angles are equal, not doubled."]}'),
  ('4fabb5be-14','{"options": ["Enters new medium", "Travels along boundary", "Reflects at right angle", "Disappears"], "correct": 1, "explanation": "At the critical angle the refracted ray bends to exactly 90° and grazes ALONG the boundary; beyond it you get total internal reflection (TIR). It doesn''t simply ''enter'' or ''vanish.'' Formula: θc = arcsin(n₂/n₁). Cross-link: TIR drives fiber optics, gonioscopy (why we need a goniolens), and prism binoculars (Q79)."}'),
  ('bc3fef14-1b','{"options": ["Real, upright, same size", "Virtual, upright, same size", "Real, inverted, smaller", "Virtual, inverted, magnified"], "correct": 1, "explanation": "A plane mirror gives a VIRTUAL, upright (erect), same-size image, laterally inverted, located as far behind the mirror as the object is in front. Distractors mix up real/virtual and size. Mnemonic: plane mirror = ''Virtual, Upright, Same size, behind'' (VUS)."}'),
  ('d145b0a8-1c','{"options": ["Real, inverted, same size", "Virtual, upright, smaller", "Real, inverted, larger", "Virtual, magnified"], "correct": 0, "explanation": "Object at 2F of a converging lens (object 40 cm, f = 20 cm → object at 2F) gives an image at 2F on the far side: REAL, inverted, SAME size. This is the symmetry point used to find focal length by the ''same-size'' method. Cross-link: object-image rules — inside F → virtual/magnified (the simple-magnifier case), beyond 2F → real/minified."}'),
  ('2ee05bda-v','{"options": ["Slows down in denser medium", "Speeds up in denser medium", "Travels parallel", "At critical angle"], "correct": 0, "explanation": "Light bends TOWARD the normal when it SLOWS DOWN entering a denser (higher-index) medium (Snell''s law, n₁sinθ₁ = n₂sinθ₂). Going to a less dense medium it speeds up and bends AWAY. Mnemonic: ''denser = slower = bends toward normal.'' Cross-link: this is why the cornea (n≈1.376 vs air) does most of the eye''s refracting."}'),
  ('fdfac962-1f','{"options": ["TIR", "Greater optical density", "Reflection", "Dispersion only"], "correct": 1, "explanation": "A prism deviates light toward its BASE because the denser glass slows and bends the ray toward the thicker part; the apparent image shifts toward the APEX. It''s refraction, not TIR, reflection, or pure dispersion. Cross-link: clinically this is how we measure and prescribe prism for phorias/diplopia (BV)."}'),
  ('127933f7-1a','{"options": ["Object is beyond focus", "Object at focus", "Object between F and pole", "Object at C"], "correct": 0, "explanation": "A concave (converging) mirror forms a REAL, inverted image when the object lies BEYOND the focal point. At F the reflected rays emerge parallel (image at infinity, no image); inside F the image becomes virtual, upright, magnified (the shaving/makeup mirror). Cross-link: mirror behavior mirrors the converging-lens object rules."}'),
  ('2f315cc8-o','{"options": ["Light travels in straight lines", "Each point on wavefront acts as source of wavelets", "Photons are energy packets", "Light speed is infinite"], "correct": 1, "explanation": "Huygens'' principle: every point on a wavefront acts as a source of secondary spherical wavelets, and their envelope forms the next wavefront. It explains reflection, refraction, and diffraction geometrically. Distractors describe rectilinear propagation or the photon model. Pearl: Huygens = WAVELETS."}'),
  ('796276d1-n','{"options": ["A particle", "Mechanical vibration", "Electromagnetic wave", "Corpuscular beam"], "correct": 2, "explanation": "Maxwell unified electricity and magnetism and showed light is an ELECTROMAGNETIC wave — oscillating E and B fields traveling at c. Newton''s corpuscles came earlier; Einstein''s photon (particle) came later. Timeline cue: Newton (particle) → Huygens/Young/Maxwell (wave) → Planck/Einstein (quantum)."}'),
  ('7455107b-h','{"options": ["Continuous energy emission", "Quantized energy packets", "Photon relativity", "Geometric optics"], "correct": 1, "explanation": "Planck introduced energy QUANTIZATION — energy is emitted/absorbed in discrete packets (quanta), E = hν — to explain blackbody radiation, launching quantum theory. Classical physics had assumed continuous emission. Cross-link: E = hν also underlies the photoelectric effect (Q30) and why UV (high ν) damages tissue."}'),
  ('77d259cc-p','{"options": ["Wave theory only", "Particle theory only", "Wave-particle duality", "Corpuscular"], "correct": 2, "explanation": "The modern view is WAVE–PARTICLE DUALITY: light shows wave behavior (diffraction, interference) and particle behavior (photoelectric, Compton) depending on the experiment. Neither pure wave nor pure particle alone is complete. Pearl: duality reconciles Q29 (wave evidence) and Q30 (particle evidence)."}'),
  ('4d1eefc7-10','{"options": ["Diffraction", "Photoelectric effect", "Compton effect", "Blackbody radiation"], "correct": 0, "explanation": "Diffraction — light bending/spreading around edges and apertures — is a WAVE property. The photoelectric and Compton effects and blackbody radiation reveal the PARTICLE (photon) nature. Cross-link: diffraction at the pupil sets the eye''s resolution limit (Airy disc), so this isn''t just trivia."}'),
  ('90d2d4c8-s','{"options": ["Interference", "Reflection", "Photoelectric effect", "Diffraction"], "correct": 2, "explanation": "The PHOTOELECTRIC effect proves the particle nature: electrons are ejected only above a threshold FREQUENCY and instantly, which a wave model can''t explain — only discrete photons (E = hν, Einstein) fit. Interference, diffraction, and reflection are wave/geometric evidence. Pairs with Q29 as the wave-vs-particle dyad."}'),
  ('832d56bf-3i','{"options": ["Glass", "CR-39 plastic", "Polycarbonate", "High-index plastic"], "correct": 2, "explanation": "A high-minus CHILD needs impact protection plus thin, light lenses: POLYCARBONATE is the pediatric/safety standard — highest impact resistance, built-in UV, high index (thin), and light. Glass is unsafe (shatters), CR-39 is thick and only moderately impact-resistant, high-index plastic is thin but less impact-tough than poly. High-yield: ''child or safety + thin → polycarbonate.''"}'),
  ('15b08fb3-1q','{"options": ["Plane mirror", "Spectacles", "Prism binoculars", "Pinhole camera"], "correct": 1, "explanation": "Everyday spectacles use BOTH refraction (the lens power bends light) and reflection (surface reflections, which AR coating fights). A plane mirror is reflection only; prism binoculars rely on TIR; a pinhole camera uses rectilinear propagation. Cross-link: the unwanted reflections here are exactly what Q13/Q17 address with AR."}'),
  ('8494f58d-4h','{"options": ["Trifocal", "Bifocal flat-top", "Double D segment", "Computer/Office PAL"], "correct": 3, "explanation": "A computer/office PAL (a near-intermediate ''degressive'' design) gives a wide intermediate AND near field at eye level, so the patient doesn''t tilt the chin up — eliminating the neck strain a general-purpose PAL causes at the monitor. Trifocals and double-D have image jump and narrower zones. Pearl: ''computer + neck strain in PALs → occupational/office lens.''"}'),
  ('99a46342-2k','{"options": ["Induced BO prism", "Induced BI prism", "Induced BU prism", "Induced BD prism"], "correct": 1, "explanation": "The OC separation (68) is WIDER than the patient''s PD (64), so each visual axis passes through the lens 2 mm nasal to its OC. Decentering a PLUS-power line of sight nasally induces BASE-IN prism by Prentice''s Rule (plus lens, axis nasal to OC → base toward the OC = base-in). Distractors flip the base or make it vertical. Cross-link: this is the mechanism of the wrong-PD complaint in Q65."}'),
  ('0c259d53-32','{"options": ["Spheric high-index", "Aspheric plus lenses", "Glass crown lenses", "Plano-convex lenses"], "correct": 1, "explanation": "Bilateral high hyperopia (+8.00) magnifies the eyes cosmetically; ASPHERIC plus lenses flatten the front curve, cutting magnification and the bug-eye look while staying thin. High-index alone reduces thickness but aspheric specifically tackles magnification. Same family as Q14 (high hyperopia) and Q63 (high minus). Pearl: aspheric = shape fix for magnification + thickness."}'),
  ('96bd715f-22','{"options": ["Minus-powered progressive lenses", "Plus-powered progressive lenses", "Flat-top bifocal lenses", "Minus-powered single vision lenses"], "correct": 1, "explanation": "Prism thinning grinds equal base-DOWN prism into both lenses to shave the thick lower edge created by the add on PLUS-powered progressives — it''s a cosmetic thickness trick, standard on plus PALs. It''s not used on minus single-vision lenses (whose thickness is at the edge for a different reason). Cross-link: contrast with slab-off (Q12), which is a prism FIX, not a cosmetic trim."}'),
  ('c95aca91-2c','{"options": ["Myope", "Hyperope", "Emmetrope", "They accommodate the same"], "correct": 1, "explanation": "A corrected HYPEROPE accommodates MORE than an emmetrope for the same near target because the plus spectacle lens sits in front of the eye and changes effectivity — the spectacle-plane vergence means more accommodative effort per diopter of demand. A corrected myope (minus lens) accommodates LESS. Cross-link (Physio Optics): spectacle vs ocular accommodation and the reason CL wearers (no vertex gap) have different near demand than spectacle wearers."}'),
  ('27e9c468-3p','{"options": ["3.93D at 21°", "3.93D at 159°", "2.75D at 30°", "2.75D at 45°"], "correct": 1, "explanation": "Resolve each prism into horizontal and vertical components, add them, then recombine. Taking the base-IN direction as 0: x = 2.00cos0 + 1.50cos30 + 0.75cos60 = 2.000 + 1.299 + 0.375 = 3.674. y = 2.00sin0 + 1.50sin30 + 0.75sin60 = 0.000 + 0.750 + 0.650 = 1.400. R = sqrt(3.674^2 + 1.400^2) = sqrt(13.50 + 1.96) = sqrt(15.46) = 3.93 D. Angle = arctan(1.400 / 3.674) = 20.9 degrees off that base-IN direction. Because base-IN on the RIGHT eye points nasally, the same resultant is written 159 in standard 360 notation, the mirror of 21 about the vertical. Answer: 3.93 D at 159. Trap: 21 and 159 give the identical magnitude, so choosing between them is a base-direction convention question, not an arithmetic one. Get the magnitude first, then decide which side the base sits on."}'),
  ('b52145ea-4b','{"options": ["+4.82 D", "+6.00 D", "+7.47 D", "+6.25 D"], "correct": 2, "explanation": "CORRECTED ANSWER: +7.47 D (the preboard sheet keyed +4.82, which inverts the ratio). A Geneva lens clock is calibrated for crown glass n = 1.530; on a higher-index 1.66 lens the SAME physical curve has more power, so actual surface power = reading × (n_actual − 1)/(1.530 − 1) = 6.00 × 0.66/0.53 = +7.47 D. Rule: high-index reads LOW on a 1.53 clock, so multiply UP. Cross-link: the reverse correction is used when verifying base curves on high-index stock."}'),
  ('36dad6a8-28','{"options": ["Myope", "Hyperope", "Emmetrope", "They are the same"], "correct": 0, "explanation": "The MYOPE enjoys the widest real field of view. Minus lenses minify and, by spectacle magnification, give a larger apparent field, while PLUS lenses (hyperopes, aphakes) restrict the field and create a ring scotoma with the ''jack-in-the-box'' phenomenon (objects pop in/out at the edge). Cross-link: this field penalty is a key reason aphakes do better in contact lenses than thick plus spectacles."}'),
  ('8adbaf3c-2l','{"options": ["25.0 cm in front of the lens", "33.3 cm behind the lens", "33.3 cm in front of the lens", "20.0 cm behind the lens"], "correct": 1, "explanation": "Vergence method: U = 1/(−0.50 m) = −2.00 D (object 50 cm in front). V = P + U = +5.00 + (−2.00) = +3.00 D → image at 1/3.00 = +0.333 m = 33.3 cm BEHIND the lens. Positive V = real image on the far side. Mnemonic: ''V = P + U, then flip V to get image distance.'' Distractors drop the sign or use 1/f directly."}'),
  ('dc789005-2k','{"options": ["2.8 mm", "3.0 mm", "3.6 mm", "4.5 mm"], "correct": 2, "explanation": "Sag (sagitta) formula: first r = (n − 1)/F = 0.530/6.00 = 0.0883 m = 88.3 mm; half-diameter y = 25 mm. Then s = r − √(r² − y²) = 88.3 − √(88.3² − 25²) ≈ 88.3 − 84.7 = 3.6 mm. Cross-link (CL/Dispensing): sag governs how a lens drapes over the cornea and the center/edge thickness of a blank. Mnemonic: ''radius minus the leftover under the chord.''"}'),
  ('73607706-3v','{"options": ["+10.50 D", "+9.50 D", "+10.25 D", "+9.25 D"], "correct": 0, "explanation": "Effective (vertex) power: F₂ = F₁ / (1 − (d₁ − d₂)·F₁), where d is in meters. Moving the +10.00 D lens CLOSER (13.5 → 8.5 mm = 0.005 m toward the eye): F₂ = 10 / (1 − 0.005×10) = 10/0.95 = +10.53 ≈ +10.50 D. Plus lens moved closer needs MORE plus; the opposite for minus. Cross-link: same formula converts a spectacle Rx to a CL power (Q109)."}'),
  ('1b3bb060-1w','{"options": ["Diffraction", "Spherical aberration", "Chromatic aberration", "Oblique astigmatism"], "correct": 3, "explanation": "Corrected-curve (''best-form'' / point-focal / Tscherning) lenses choose specific base curves to minimize OBLIQUE (marginal/radial) astigmatism for off-axis gaze, keeping the periphery sharp. They don''t affect diffraction, and chromatic aberration depends on Abbe (material), not base curve. Cross-link: oblique astigmatism is also what aspheric designs (Q8) reduce by a different route."}'),
  ('fc037eb1-1s','{"options": ["Directly proportional to the power of the lens", "Directly proportional to the distance from the optical center", "Inversely proportional to the Abbe value of the material", "All of the above"], "correct": 3, "explanation": "All three raise peripheral chromatic aberration: it is directly proportional to lens POWER, increases with DISTANCE from the optical center (off-axis), and worsens with LOWER Abbe (more dispersion) — so ''all of the above.'' Pearl: a strong, low-Abbe lens viewed off-center is the worst case for color fringe (e.g., high-power polycarbonate edges)."}'),
  ('ae81ddd4-4s','{"options": ["Use a 56 mm distance PD", "Use a 60 mm near PD", "Use a 54 mm near PD", "Can’t be done"], "correct": 2, "explanation": "Prentice: prism = decentration (cm) x power. The near prism comes from the ADD, not the distance Rx, which is exactly why changing the NEAR PD moves prism at near only. Per eye: d = prism / F = 1.00 / 2.50 = 0.40 cm = 4 mm of inward decentration. Both eyes: near PD 62 - (2 x 4) = 54 mm. Answer: use a 54 mm near PD. Check the distractor: a 60 mm near PD is only 1 mm per eye, giving 0.1 x 2.50 = 0.25 D, a quarter of what was asked. Why base-IN: with plus segs, eyes reading nasal to the seg optical centres throw the base toward the nose."}'),
  ('71d25dab-2m','{"options": ["Lens thickness", "Temperature", "Sunlight exposure", "Age"], "correct": 0, "explanation": "This is a NOT/least-dependent question. Photochromic (Transitions) darkening DOES depend on UV/sunlight exposure, temperature (warmer = lighter, the ''winter is darker'' effect), and lens AGE (the dye fatigues over years). In a modern imbibed/in-mass plastic the photochromic dye sits throughout the lens matrix, so transmittance is essentially independent of LENS THICKNESS — that''s the factor it does NOT depend on. (Older surface-coated or glass photochromics did vary with thickness.)"}'),
  ('978283a4-4o','{"options": ["71 mm", "65 mm", "68 mm", "77 mm"], "correct": 3, "explanation": "Minimum blank size = effective diameter + 2 x (total decentration per eye) + a small chipping allowance. Step 1, frame decentration. Frame PD = eyesize + bridge = 54 + 16 = 70 mm. Patient PD = 64 mm. So each lens centre sits (70 - 64)/2 = 3 mm temporal to the eye. Step 2, prism decentration. Prentice: c = prism / F = 1.5 / 5.00 = 0.3 cm = 3 mm per eye. Step 3, do the two ADD or oppose? Decentring a MINUS lens outward gives base-IN, and the frame is already pushing the centres 3 mm outward, so both displacements run the same way: 3 + 3 = 6 mm per eye. Step 4, MBS = 64 + 2(6) + 1 = 77 mm. Answer: 77 mm. The listed 71 mm is what you get by counting only the frame''s 3 mm and ignoring the prism grind entirely. The direction check in step 3 is the whole item: if the prism had been base-OUT the two would have cancelled and the blank would have been smaller, not larger."}'),
  ('c73e8290-5b','{"options": ["Base in prism", "Base out prism", "Vertical prism", "No prism"], "correct": 0, "explanation": "Plano distance power but the segs ground to a NARROWER near PD (60) than specified (64): the reading axes now pass nasal to the seg OCs. With the plus add this induces BASE-IN prism while reading (axis nasal to OC on a plus = base toward OC). Distractors flip base or call it vertical. Cross-link: the cosmetic intentional version of this is Q46."}'),
  ('0b57196d-1t','{"options": ["1.5 mm", "2.0 mm", "2.5 mm", "3.0 mm"], "correct": 1, "explanation": "ANSI Z80.1 tolerance for the near PD / horizontal segment placement of multifocals is ±2.0 mm total. (Tighter tolerances apply to higher-power monocular measurements.) Pearl: file the dispensing tolerances together — center thickness ±0.3 mm (Q60), prism imbalance 0.5Δ horizontal (Q70), axis tolerance power-dependent (Q64)."}'),
  ('73ca98ab-1h','{"options": ["Sphere power is increased; cylinder power equal in sign to sphere power is induced", "Only cylinder power is induced", "Sphere power is decreased; cylinder power equal in sign to sphere power is induced", "Sphere power is increased; cylinder power opposite in sign to sphere power is induced"], "correct": 0, "explanation": "Lens TILT (pantoscopic or face-form) by Martin''s formulas INCREASES the sphere power and induces a cylinder of the SAME sign as the sphere, with axis along the tilt meridian. So a plus lens tilted gets more plus sphere plus a plus cyl. This is why high powers and wrap frames must control tilt. Formulas: F_sph'' = F(1 + sin²θ/2n); induced cyl = F·tan²θ. Cross-link: Q86, Q87 apply this numerically."}'),
  ('cbf00857-4m','{"options": ["O.D. 4D Base In and 4D Up; O.S. No prism", "O.D. 2D Base In and 2D Up; O.S. 2D Base Out and 2D Base Down", "O.D. 2D Base In and 2D Up; O.S. 2D Base In and 2D Base Up", "O.D. 2D Base In and 2D Up; O.S. 2D Base In and 2D Base Down"], "correct": 1, "explanation": "Splitting prism between the two eyes halves each eye''s grind and improves cosmetics: give OD half the Rx (2Δ BI, 2Δ up) and OS the COMPLEMENTARY halves in the OPPOSITE base directions (2Δ BO, 2Δ down). The RELATIVE prism between the eyes then equals the original 4Δ BI / 4Δ up. Pearl: for binocular prism, the eyes only feel the DIFFERENCE, so opposite bases share the load."}'),
  ('8a384558-25','{"options": ["Optyl", "Cellulose Acetate", "Carbon Fiber", "Polyamide"], "correct": 0, "explanation": "OPTYL is a thermosetting epoxy with shape MEMORY — reheating returns it to its molded shape, handy for adjustments. Cellulose acetate (thermoplastic) softens but doesn''t ''remember,'' and carbon fiber/polyamide are rigid/semi-rigid without this property. Pearl: ''Optyl = remembers its shape when reheated.''"}'),
  ('e3219b9d-45','{"options": ["Right (O.D.) eye/lens", "Left (O.S.) eye/lens", "Either lens could use it", "Neither lens could use it"], "correct": 1, "explanation": "Reverse slab-off places the base-UP correction on the MORE PLUS lens — here OS (+4.00). In anisometropia at near the eyes look below the OCs; the more-plus lens carries more base-down prism, so the corrective base-up (reverse slab-off) goes on OS. Contrast: conventional slab-off goes on the more-MINUS lens. Cross-link: same vertical-imbalance problem as Q12/Q68."}'),
  ('9a329988-32','{"options": ["3.5%", "4.0%", "4.5%", "8.0%"], "correct": 0, "explanation": "Per-surface reflection loss ≈ ((n − 1)/(n + 1))² × 100. For CR-39 (n = 1.50): (0.5/2.5)² = 0.04 = 4% per surface (~8% both surfaces uncoated). The keyed 3.5% is a rounding; the Fresnel formula gives ~4%. Cross-link: this loss is exactly what AR coatings recover (Q88–Q90 transmission values)."}'),
  ('413a4d7c-26','{"options": ["+1.00 D", "+0.50 D", "0.00 D (plano)", "-1.00 D"], "correct": 2, "explanation": "CORRECTED ANSWER: plano 0.00 D (the preboard sheet keyed +0.50). Spherical equivalent = sphere + ½(cylinder) = +1.00 + ½(−2.00) = +1.00 − 1.00 = 0.00 D. SE is the dioptric midpoint (circle of least confusion) of the Sturm interval. Mnemonic: ''SE = sphere plus half the cyl.'' Cross-link: SE is how you pick a single-vision ''best sphere'' or a soft CL power for a low-cyl eye (Q109)."}'),
  ('f5856f29-22','{"options": ["Partial sight (low vision)", "Aphakia", "Aniseikonia", "Nystagmus"], "correct": 1, "explanation": "A ''Hi-Drop'' (high, dropped segment) design supplies a large near reading area used in APHAKIA, where the patient needs strong plus and a wide near field after cataract/lens removal. Not for low-vision magnifiers, aniseikonia, or nystagmus. Cross-link: aphakic optics also explain the field/ring-scotoma issues in Q40."}'),
  ('2174249c-3o','{"options": ["1 mm above", "½ mm below", "1 mm below", "2 mm below"], "correct": 2, "explanation": "Rule of thumb: LOWER the OC about 1 mm for every 2° of pantoscopic tilt so the optical axis stays aligned with the eye''s line of sight on downgaze, avoiding induced power error and unwanted cyl (Q51). Mnemonic: ''2 degrees → 1 mm down.'' High-yield for high-power dispensing."}'),
  ('c9609f74-2u','{"options": ["-1.50 D", "-4.00 D", "-2.50 D", "+2.50 D"], "correct": 0, "explanation": "Cylinder power = the DIFFERENCE between the two principal back curves = −8.00 − (−6.50) = −1.50 D. The +4.00 front is the spherical base; the two different back curves create the cyl. Cross-link: this is lens-clock verification — you read each meridian and subtract. Trap: don''t add the front curve into the cyl."}'),
  ('241c67af-1v','{"options": ["+/-0.25 mm", "+/-0.30 mm", "+/-0.50 mm", "+/-1.00 mm"], "correct": 0, "explanation": "ANSI Z80.1 center-thickness tolerance, when thickness is specified, is ±0.3 mm. (The keyed ±0.25 mm is the tighter end some labs use.) Group with the other ANSI numbers: near PD ±2.0 mm (Q50), horizontal prism imbalance 0.5Δ (Q70), axis tolerance scales with cyl power (Q64)."}'),
  ('cd2a4b38-2c','{"options": ["Raise right temple", "Lower right temple", "Narrow the bridge", "Spread both temples"], "correct": 0, "explanation": "Same as Q5: the lens touching the cheek means that side sits too low, so RAISE the temple on that side to lift the front away from the face. Narrowing the bridge or spreading temples changes width/grip, not vertical drop. Reinforced repeat — lock the rule: ''low lens → raise temple.''"}'),
  ('5c4bfff2-1k','{"options": ["0.5Δ BI", "1.25Δ BI", "0.5Δ BO", "1.25Δ BO"], "correct": 1, "explanation": "Prentice: 2.50 × 0.5 cm = 1.25Δ. Decentered INWARD (nasally) on a PLUS lens → base-IN prism (base follows the decentration for plus). So 1.25Δ BI. Distractors halve the answer or flip the base. Pearl: plus lens + decentration → base SAME direction as the shift; minus lens → base OPPOSITE."}'),
  ('3b094ee2-2k','{"options": ["Polycarbonate lenses", "CR-39 lenses", "Aspheric high-index lenses", "Glass crown lenses"], "correct": 2, "explanation": "High myopia (−8.00) with a heavy/thick complaint: ASPHERIC HIGH-INDEX lenses give the thinnest edge and lowest weight while flattening the profile and reducing the minified, swirly edge look. Polycarbonate/CR-39 are thicker; glass is heaviest. Same material-selection family as Q31/Q35. Pearl: ''high minus, thick edges → high-index aspheric (+ roll/polish edges, smaller eye size).''"}'),
  ('3d6119d8-27','{"options": ["±3°", "±7°", "±15°", "±30°"], "correct": 2, "explanation": "ANSI cylinder AXIS tolerance is power-dependent — looser for low cyl, tighter for high cyl: for very low cyl (≤0.25 D) the axis band is the widest (~±14°, the keyed ±15° reflects this), tightening toward ±2° for high cyl. Reason: a tiny cyl has little visual effect, so axis precision matters less. Group with the ANSI cluster (Q50, Q60, Q70)."}'),
  ('432931dc-2b','{"options": ["Vertical diplopia", "Headaches due to horizontal prism", "Blur at near", "Increased magnification"], "correct": 1, "explanation": "A spectacle PD too WIDE (64 vs true 60) decenters each OC temporally, so the visual axes pass nasal to the OCs — inducing unwanted BASE-OUT prism the eyes must overcome with convergence reserves, causing asthenopic headaches. It doesn''t cause vertical diplopia or near blur. Cross-link: this is Prentice''s Rule (Q34) felt as a symptom; the fix is correct PD."}'),
  ('f1ce14df-1l','{"options": ["Segment height", "Fitting cross", "Vertex distance", "PD"], "correct": 0, "explanation": "Segment HEIGHT positions bifocal/multifocal segs correctly in the VERTICAL meridian (relative to lower lid or pupil). PD is horizontal; fitting cross is the PAL alignment mark; vertex distance is the eye–lens gap. Pair: PD = horizontal centering (Q7), seg height = vertical centering (this)."}'),
  ('2a71a8c9-2c','{"options": ["PD too wide", "Add too low", "Fitting cross too high", "Insufficient vertex distance"], "correct": 1, "explanation": "Clear distance but blurred NEAR through a PAL points to an inadequate (too LOW) add for the patient''s near demand — distance optics are fine, so it''s not PD/cross/vertex. Add errors blur; height/PD errors cause swim or distortion (Q6). Pearl: ''distance clear, near blurred in a PAL → check add power first.''"}'),
  ('6ab9b721-1t','{"options": ["High-index lenses", "AR coating", "Slab-off prism", "Aspheric design"], "correct": 2, "explanation": "Vertical imbalance over 1Δ at near (from anisometropia) is best solved with a SLAB-OFF (bicentric) prism that equalizes the vertical prism between the two lenses. High-index/AR/aspheric address weight, glare, and thickness — not vertical prism. Cross-link: the underlying Prentice imbalance is the same one in Q12/Q54."}'),
  ('5d34af49-1o','{"options": ["Thicker edge", "Higher index", "Lower Abbe value", "AR coating"], "correct": 1, "explanation": "Higher refractive INDEX lets a thinner lens reach the same power, cutting volume and therefore WEIGHT for strong Rxs (works for plus and minus). Thicker edges add weight; low Abbe worsens color, not weight; AR is a surface coating. Cross-link: index ↔ weight and thickness is the recurring material theme (Q10, Q31, Q63)."}'),
  ('876328f5-1i','{"options": ["0.25Δ", "0.50Δ", "0.75Δ", "1.00Δ"], "correct": 1, "explanation": "ANSI Z80.1 tolerance for HORIZONTAL prism imbalance between the two eyes is 0.50Δ (vertical imbalance tolerance is tighter, ~0.33Δ, because the eyes fuse vertical prism poorly). Finish the ANSI set with Q50, Q60, Q64. Pearl: eyes tolerate horizontal prism better than vertical — hence the tighter vertical spec."}'),
  ('c33b3dce-1u','{"options": ["28°", "56°", "62°", "90°"], "correct": 0, "explanation": "Angle of reflection equals angle of incidence: 28° (law of reflection, Q18), both from the normal. Distractors double it or use the complement. Quick win — don''t overthink it."}'),
  ('d3f2a131-u','{"options": ["Real, inverted images", "Virtual, upright, reduced images", "Real, magnified images", "Virtual, magnified images"], "correct": 1, "explanation": "A concave (diverging, minus) lens ALWAYS forms a virtual, upright, minified image, for every object position — there''s no real-image case. This is the myopic spectacle lens, which is why minus wearers see a slightly smaller world (and get a wider field, Q40). Mnemonic: minus lens = ''Virtual, Upright, Minified, always.''"}'),
  ('bf25918d-1r','{"options": ["0.66", "1.5", "2.0", "3.0"], "correct": 1, "explanation": "Refractive index n = c/v = (3×10⁸)/(2×10⁸) = 1.5. Index is the ratio of light''s speed in vacuum to its speed in the medium, so it''s always ≥1 and dimensionless. Cross-link: this n drives Snell''s law (Q22) and the critical angle (Q19, Q77)."}'),
  ('52ccd0f8-1b','{"options": ["Reflection", "Different refractive indices for different wavelengths", "Diffraction", "Polarization"], "correct": 1, "explanation": "Dispersion (white light fanning into colors, e.g., a prism or rainbow) occurs because refractive index VARIES WITH WAVELENGTH — short violet bends more than long red. Not reflection, diffraction, or polarization. Cross-link: dispersion in a lens IS chromatic aberration (Q2), quantified by Abbe."}'),
  ('d9eede1f-16','{"options": ["Towards apex", "Towards base", "Parallel to incident ray", "Perpendicularly"], "correct": 1, "explanation": "In a prism the emergent ray bends TOWARD the BASE (and the image displaces toward the apex). Base direction = direction of light deviation — the convention behind prescribing prism. Reinforces Q23. Cue: ''light goes to the base, image goes to the apex.''"}'),
  ('7b49f015-1m','{"options": ["Real, inverted, same size", "Real, inverted, magnified", "Virtual, upright, magnified", "Real, inverted, reduced"], "correct": 0, "explanation": "Object at the center of curvature (C, i.e., 2F for a mirror) forms a real, inverted, SAME-size image, also located at C. This is the mirror analog of the lens-at-2F case (Q21) and is used to locate C experimentally. Distractors change size or make it virtual."}'),
  ('51f6e8c2-23','{"options": ["Smaller", "Larger", "Same", "Zero"], "correct": 0, "explanation": "Critical angle θc = arcsin(1/n). A diamond''s very high index (~2.42) makes 1/n small, so its critical angle is SMALLER than glass (~24° vs ~42°) — light is trapped more easily by TIR, giving diamonds their brilliance. Inverse relationship: higher n → smaller θc. Cross-link: same θc concept as Q19."}'),
  ('1d78598c-1h','{"options": ["Center of curvature", "Optical center", "Focal point", "Principal axis"], "correct": 2, "explanation": "An object at infinity sends PARALLEL rays, which a convex lens focuses at the FOCAL point (focal plane). This defines focal length and is how we measure the back vertex power of a lens. Cross-link: the reverse — a source at the focal point yields parallel emergent rays (collimation)."}'),
  ('4adbc71b-o','{"options": ["Refraction at prisms", "Reflection in mirrors/prisms", "Interference", "Dispersion"], "correct": 1, "explanation": "A periscope works by REFLECTION — two parallel mirrors, or right-angle prisms using total internal reflection, fold the light path. Not refraction, interference, or dispersion. Cross-link: prism binoculars/periscopes exploit TIR (Q19), erecting the image without lenses."}'),
  ('15c39b89-2r','{"options": ["Ideal Face form", "Flat face form", "Steep Face form", "Positive Face form"], "correct": 2, "explanation": "A STEEP (excessive) face-form / pantoscopic tilt introduces power error and unwanted cylinder per the tilt formulas (Q51). ''Ideal'' or flat face form minimizes this; the steep tilt is the culprit that distorts the Rx. Cross-link: this is the conceptual setup for the numeric tilt problems Q86–87."}'),
  ('a0c1550b-52','{"options": ["Albert Einstein", "Christiaan Huygens", "Isaac Newton", "Max Planck"], "correct": 1, "explanation": "Christiaan Huygens, his wave theory says every point on a wavefront is a source of secondary wavelets. Hint: ''secondary wavelets from each wavefront point'' = Huygens'' principle."}'),
  ('b0fa4f5f-5g','{"options": ["Gamma radiation", "Infrared radiation", "Ultraviolet radiation", "Visible light"], "correct": 3, "explanation": "Visible light is the only band that stimulates human vision. Hint: the eye only ''sees'' the visible slice of the spectrum."}'),
  ('be9f7948-2l','{"options": ["−0.118 m", "−8.50 m", "+0.118 m", "+8.50 m"], "correct": 0, "explanation": "f = 1/F = 1/(-8.50) = -0.118 m (a diverging lens has a negative focal length). Hint: focal length (m) = 1 / power; minus power = minus focal length."}'),
  ('e3376969-3j','{"options": ["Corpuscles", "Photons", "Quanta", "Wavelets"], "correct": 0, "explanation": "Corpuscles, Newton''s emission theory called light tiny particles (corpuscles). Hint: Newton = corpuscles (not photons/quanta, which came later)."}'),
  ('bccd9ad9-5a','{"options": ["It decreases because the second medium is optically denser.", "It increases because the second medium has a lower refractive index.", "It remains constant because light always travels at the same speed.", "It becomes zero at the boundary between the two media."], "correct": 1, "explanation": "Speed increases, the second medium (1.33) is optically LESS dense than 1.60, so light speeds up. Hint: lower index = faster light (v = c/n)."}'),
  ('a9bfca05-5h','{"options": ["Beam of light", "Normal ray", "Pencil of light", "Principal ray"], "correct": 0, "explanation": "A beam of light, a broad collection of rays (parallel/converging/diverging) from an extended source. A pencil is rays from a single point. Hint: many rays from an extended source = beam; from one point = pencil."}'),
  ('d8ea748e-32','{"options": ["Orange", "Red", "Violet", "Yellow"], "correct": 2, "explanation": "Violet has the highest frequency (shortest wavelength) in the visible spectrum. Hint: violet = short wavelength = high frequency; red = the opposite."}'),
  ('5cbb4bea-72','{"options": ["107.78 in²", "270.91 in²", "508.31 in²", "616.19 in²"], "correct": 0, "explanation": "About 107.78 sq in. Since the object (10 in) is larger than the source (8 in), the umbra GROWS: umbra radius = 5 + (5 - 4)(30/35) = 5.857 in, area = pi r^2 = 107.8 sq in. Hint: object bigger than source = umbra widens with distance; compute the umbra radius, then pi r^2."}'),
  ('8e7760f3-4u','{"options": ["2.45 fc", "85.71 fc", "85.71 lm", "105.00 fc"], "correct": 0, "explanation": "E = I / d^2 = 3000 / 35^2 = 3000/1225 = 2.45 foot-candles. Hint: inverse-square law, illuminance = intensity / distance squared."}'),
  ('a191d5bf-5c','{"options": ["37.80 cd", "175.00 cd", "291.67 cd", "472.50 cd"], "correct": 2, "explanation": "Equal illuminance: I1/d1^2 = I2/d2^2, so I = 105 x (15^2/9^2) = 105 x 2.778 = 291.67 cd. Hint: intensities scale with the SQUARE of distance for equal illuminance."}'),
  ('105d6bfd-66','{"options": ["2,827.43 in²", "7,068.58 in²", "11,309.73 in²", "101,787.60 in²"], "correct": 2, "explanation": "About 11,309.73 sq in. From a point source, the illuminated radius scales with distance: r = 15 x (480/120) = 60 in, area = pi(60^2) = 11,309.73. Hint: point-source shadow/illumination scales linearly with total distance; then pi r^2."}'),
  ('101775b3-3w','{"options": ["34.99°", "44.42°", "55.01°", "64.98°"], "correct": 2, "explanation": "Elevation = arctan(height/shadow) = arctan(50/35) = arctan(1.4286) = 55.01 degrees. Hint: the sun angle = arctan(pole height over shadow length)."}'),
  ('fbe37335-5u','{"options": ["Inverse square law", "Law of reflection", "Law of refraction", "Rectilinear propagation law"], "correct": 0, "explanation": "The inverse square law, intensities proportional to the square of the distances for equal illuminance. Hint: illuminance falls with distance squared = inverse square law."}'),
  ('f8c5d914-5g','{"options": ["It becomes larger.", "It becomes smaller.", "It remains the same size.", "It becomes upright"], "correct": 0, "explanation": "The image becomes LARGER, moving the object closer (screen fixed) increases magnification. Hint: pinhole image size grows as the object nears the pinhole (screen distance fixed)."}'),
  ('767faa6d-34','{"options": ["Biconcave lens", "Biconvex lens", "Meniscus lens", "Plano-convex lens"], "correct": 2, "explanation": "A meniscus lens (one convex surface, one concave surface). Hint: convex front + concave back = meniscus (crescent) lens."}'),
  ('32c55995-5q','{"options": ["+0.25 D", "+0.50 D", "+2.25 D", "+4.00 D"], "correct": 2, "explanation": "About +2.25 D. F1 = (1.67-1)/0.55 = +1.218 D, F2 = (1-1.67)/(-0.65) = +1.031 D, total = +2.25 D. Hint: add the two surface powers, F = (n-1)/R1 + (1-n)/R2 (radii in meters)."}'),
  ('4edbdde3-41','{"options": ["+0.38×", "+0.79×", "−0.38×", "−1.26×"], "correct": 0, "explanation": "About +0.38x. With f = -30 in and object at -50 in, 1/v = 1/f + 1/u gives v = -18.75 in, m = v/u = -18.75/-50 = +0.38 (virtual, upright, minified). Hint: a diverging lens always gives an upright, minified (m<1, positive) image."}'),
  ('68f58f8f-3r','{"options": ["The rays emerge parallel, and the image is located at infinity.", "A real, inverted, magnified image forms beyond twice the focal length.", "A real, inverted, minified image forms between the lens and its focus.", "A virtual, upright image forms behind the object."], "correct": 0, "explanation": "Rays emerge parallel with the image at infinity, the object sits exactly at the focal point (f = 20 cm for +5.00 D). Hint: object at F -> emergent rays parallel -> image at infinity."}'),
  ('6411b586-32','{"options": ["−4.67 m", "−1.27 m", "+1.27 m", "+4.67 m"], "correct": 1, "explanation": "v = -1.27 m. 1/v = 1/f + 1/u = 1/(-2) + 1/(-3.5) = -0.786, v = -1.273 m. Hint: a concave (minus) lens gives a virtual image (negative v) closer than the object."}'),
  ('618252f3-2y','{"options": ["Real, inverted, and magnified", "Real, inverted, and minified", "Virtual, upright, and magnified", "Virtual, upright, and minified"], "correct": 3, "explanation": "Virtual, upright, and minified, the standard image from a concave (diverging) lens. Hint: minus lens = always virtual, upright, minified."}'),
  ('f8bf3147-2t','{"options": ["2 mm", "5 mm", "20 mm", "50 mm"], "correct": 1, "explanation": "5 mm. Prentice: prism = decentration(cm) x power, so 3 = c x 6 -> c = 0.5 cm = 5 mm. Hint: decentration (cm) = prism / power (3/6 = 0.5 cm)."}'),
  ('adbe5413-29','{"options": ["Toward the apex", "Toward the base", "Toward the optical center", "Perpendicular to the prism axis"], "correct": 0, "explanation": "Toward the APEX, a prism displaces the image toward its apex (light bends toward the base). Hint: image shifts to the apex; the ray bends to the base."}'),
  ('19075d01-34','{"options": ["0.25∆", "1.00∆", "4.00∆", "40.00∆"], "correct": 2, "explanation": "4.00 prism diopters, 1 prism diopter = 1 cm displacement at 1 m, so 4 cm at 1 m = 4 prism diopters. Hint: prism diopters = cm of displacement per meter."}'),
  ('a2f0105a-3g','{"options": ["+1.50 DS / +0.50 DC × 155", "+2.00 DS / −0.50 DC × 65", "+2.00 DS / +0.50 DC × 65", "−2.00 DS / +0.50 DC × 155"], "correct": 1, "explanation": "+2.00 DS / -0.50 DC x65. The two crossed cylinders (axes 155 and 65 are perpendicular) give +2.00 at meridian 65 and +1.50 at meridian 155, which is +2.00 sphere with -0.50 cyl axis 65. Hint: crossed cyls at 90 degrees, read each meridian''s power, then write it as sphere + cyl."}'),
  ('42c4031b-3a','{"options": ["+1.00 D", "+3.50 D", "+4.50 D", "+8.00 D"], "correct": 2, "explanation": "+4.50 D. The cylinder (axis 180) contributes zero along its own 180 meridian, so the horizontal power is just the sphere, +4.50 D. Hint: at the cyl AXIS meridian, only the sphere counts."}'),
  ('7fe7d20d-44','{"options": ["Abbe value", "Light transmission", "Refractive index", "Specific gravity"], "correct": 0, "explanation": "The Abbe value (higher Abbe = less chromatic dispersion). Hint: Abbe number rates color dispersion, high Abbe = low dispersion."}'),
  ('c8d0b319-2w','{"options": ["Greater chromatic dispersion", "Less chromatic aberration", "Lower surface reflection", "Greater lens thickness"], "correct": 1, "explanation": "Less chromatic aberration, a high Abbe value means less color fringing. Hint: high Abbe = clean color (little chromatic aberration)."}'),
  ('60783801-3b','{"options": ["−11.00 D", "−3.50 D", "+3.50 D", "+11.00 D"], "correct": 2, "explanation": "+3.50 D nominal power = front + back = +7.25 + (-3.75) = +3.50 D. Hint: nominal (thin-lens) power = sum of the two surface powers."}'),
  ('98fc66f6-4s','{"options": ["+3.75 D", "+4.00 D", "+4.28 D", "+4.75 D"], "correct": 2, "explanation": "About +4.28 D. Back vertex power = F2 + F1/(1 - (t/n)F1) = -6.50 + 10.25/(1 - 0.00479 x 10.25) = -6.50 + 10.78 = +4.28 D. Hint: BVP boosts the front power by the 1/(1-(t/n)F1) factor, then add the back power."}'),
  ('18cf091d-4e','{"options": ["It decreases.", "It increases.", "It becomes plano.", "It remains unchanged."], "correct": 0, "explanation": "It DECREASES, moving a plus lens closer to the eye reduces its effective plus power at the cornea. Hint: plus lens toward the eye = less effective plus (that is why a strong plus is worn close)."}'),
  ('b7759ddb-3v','{"options": ["It becomes less minus.", "It becomes more minus.", "It becomes more plus.", "It remains unchanged."], "correct": 0, "explanation": "It becomes LESS minus, moving a minus lens closer reduces its effective minus power. Hint: minus lens toward the eye = less effective minus."}'),
  ('afacdfe3-6k','{"options": ["−5.35 D", "−5.62 D", "−5.89 D", "−6.06 D"], "correct": 1, "explanation": "About -5.62 D. F2 = F1 / (1 - (d1-d2)F1) = -5.75 / (1 - 0.004 x -5.75) = -5.75/1.023 = -5.62 D (moving closer needs slightly less minus). Hint: shorter vertex on a minus lens = a bit less minus power."}'),
  ('5d3b193e-2q','{"options": ["−5.75 D at 90° and −7.00 D at 180°", "−5.75 D at 180° and −7.00 D at 90°", "−4.50 D at 180° and −5.75 D at 90°", "−7.00 D at 180° and −5.75 D at 90°"], "correct": 1, "explanation": "-5.75 D at 180 and -7.00 D at 90. The cyl (axis 180) adds its -1.25 to the 90 meridian: -5.75 (at 180) and -7.00 (at 90). Hint: axis meridian = sphere; 90-away meridian = sphere + cyl."}'),
  ('1c0adae2-2c','{"options": ["+1.00 D", "+2.00 D", "+3.00 D", "+5.00 D"], "correct": 0, "explanation": "+1.00 D. At the 90 meridian the -2.00 cyl (axis 180) applies fully: +3.00 + (-2.00) = +1.00 D. Hint: the cyl acts 90 degrees from its axis; add it there."}'),
  ('51d2c905-2y','{"options": ["Lens diameter changes significantly with vertex distance.", "The effective power at the eye changes with lens position.", "The refractive index changes when the lens is moved.", "The cylinder axis rotates when vertex distance changes."], "correct": 1, "explanation": "Because the effective power at the eye changes with lens position (significant at about 4 D or more). Hint: high powers + vertex changes shift the effective power, so compensate."}'),
  ('0df55320-35','{"options": ["0.70 mm", "4.00 mm", "6.96 mm", "23.00 mm"], "correct": 2, "explanation": "About 6.96 mm. c = prism/power = 4/5.75 = 0.696 cm = 6.96 mm. Hint: decentration (cm) = prism / power (4/5.75)."}'),
  ('3dac629e-2e','{"options": ["0.30∆", "1.20∆", "3.00∆", "30.00∆"], "correct": 2, "explanation": "3.00 prism diopters, prism = 0.5 cm x 6.00 D = 3.00. Hint: Prentice, cm x D (0.5 x 6)."}'),
  ('f4d30e12-3p','{"options": ["0.20∆", "1.25∆", "2.00∆", "20.00∆"], "correct": 2, "explanation": "2.00 prism diopters, prism = 0.4 cm x 5.00 D = 2.00. Hint: 4 mm = 0.4 cm, times 5 D = 2 prism diopters."}'),
  ('d2c81ff5-2x','{"options": ["Base in", "Base out", "Base up", "Base down"], "correct": 1, "explanation": "Base OUT, a MINUS lens decentered nasally induces base-out prism. Hint: minus lens, prism base is OPPOSITE the decentration (nasal decentration -> base out)."}'),
  ('31587bbd-2w','{"options": ["Base in", "Base out", "Base up", "Base down"], "correct": 0, "explanation": "Base IN, a PLUS lens decentered nasally induces base-in prism. Hint: plus lens, prism base is TOWARD the decentration (nasal -> base in)."}'),
  ('daef82cb-3i','{"options": ["1.50∆", "6.10∆", "8.50∆", "17.50∆"], "correct": 1, "explanation": "6.10 prism diopters, resultant = sqrt(5^2 + 3.5^2) = sqrt(37.25) = 6.10. Hint: perpendicular prisms add by Pythagoras."}'),
  ('d98aef73-30','{"options": ["2.50∆", "7.63∆", "10.50∆", "26.00∆"], "correct": 1, "explanation": "7.63 prism diopters, sqrt(6.5^2 + 4^2) = sqrt(58.25) = 7.63. Hint: combine perpendicular prisms with the hypotenuse."}'),
  ('b532f3db-30','{"options": ["1.50∆", "3.00∆", "3.35∆", "4.50∆"], "correct": 2, "explanation": "3.35 prism diopters, sqrt(3^2 + 1.5^2) = sqrt(11.25) = 3.35. Hint: Pythagorean sum of the two components."}'),
  ('6910f4e5-3b','{"options": ["5.50∆ directed between base up and base out", "8.38∆ directed between base up and base in", "10.50∆ directed between base down and base in", "20.00∆ directed between base up and base out"], "correct": 1, "explanation": "8.38 prism diopters directed between base up and base in, sqrt(8^2 + 2.5^2) = 8.38, with components up and in. Hint: magnitude by Pythagoras; direction is the quadrant of the two bases (up + in)."}'),
  ('edf18a5f-41','{"options": ["+3.00 D horizontally and +5.00 D vertically", "+5.00 D horizontally and +3.00 D vertically", "+5.00 D in both meridians", "+3.00 D in both meridians"], "correct": 0, "explanation": "+3.00 D horizontally and +5.00 D vertically. For +5.00 -2.00 x90, the 180 (horizontal) meridian = +3.00 and the 90 (vertical) meridian = +5.00. Hint: use each meridian''s own power for the decentration in that direction."}'),
  ('4781e7e2-29','{"options": ["Decreased refractive index", "Induced sphere and cylinder power", "Increased Abbe value", "Elimination of oblique astigmatism"], "correct": 1, "explanation": "Induced sphere and cylinder power, excessive tilt adds unwanted power/astigmatism. Hint: tilting a lens injects extra sphere and cylinder (oblique astigmatism)."}'),
  ('e46f6f65-2x','{"options": ["The lens remains optically identical in all meridians.", "The tilt may induce additional sphere and cylinder power.", "The lens power becomes zero along the axis of tilt.", "Only the lens color and transmission are affected."], "correct": 1, "explanation": "The tilt may induce additional sphere and cylinder power. Hint: a tilted sphere is no longer a pure sphere, it gains cylinder."}'),
  ('7ed2024b-4p','{"options": ["0.52°", "2.62°", "5.00°", "7.62°"], "correct": 1, "explanation": "About 2.62 degrees, deviation = (n-1) x A = 0.523 x 5 = 2.615 degrees. Hint: small-angle prism deviation = (n-1) times the apical angle."}'),
  ('816d34de-3r','{"options": ["1.41°", "2.62°", "4.10°", "11.10°"], "correct": 2, "explanation": "About 4.10 degrees, (1.586-1) x 7 = 0.586 x 7 = 4.10 degrees. Hint: (n-1) x apical angle again."}'),
  ('2ab389bf-49','{"options": ["Bench layout", "Blocking", "Finishing", "Tempering"], "correct": 0, "explanation": "Bench layout (marking the decentration, axis, and prism line before edging). Hint: marking out the lens before cutting = layout."}'),
  ('5e045a59-6a','{"options": ["The higher refractive index allows the lens to bend light more efficiently, requiring less surface curvature to achieve the prescribed power.", "The higher refractive index increases the speed of light through the lens, resulting in a thinner design.", "The higher refractive index eliminates chromatic aberration, allowing the lens to be manufactured thinner.", "The higher refractive index decreases the focal length of light without affecting lens curvature."], "correct": 0, "explanation": "The higher index bends light more efficiently, so less surface curvature is needed for the same power, hence thinner. Hint: high index = flatter curves = thinner lens (speed/aberration are not the reason)."}'),
  ('10786b86-42','{"options": ["1.5∆ Base Out", "1.5∆ Base In", "0.75∆ Base Out", "0.75∆ Base In"], "correct": 0, "explanation": "1.5 prism diopters Base OUT, prism = 0.3 x 5.00 = 1.5, and a minus lens decentered nasally is base out. Hint: 3 mm x 5 D = 1.5 prism; minus + nasal = base out."}'),
  ('3d565c5f-32','{"options": ["Manufacturer''s logo", "Prism reference point", "Fitting cross", "Near reference circle"], "correct": 0, "explanation": "The manufacturer''s logo/mark (in the temporal circle) identifies the temporal side; the nasal circle carries the add power. Hint: PAL temporal engraving = maker''s mark; nasal engraving = the add."}'),
  ('a0b02e5f-3q','{"options": ["Raise the right temple", "Lower the right temple", "Increase pantoscopic tilt", "Widen the bridge"], "correct": 0, "explanation": "Raise the right temple, if the frame sits low on the right ear (lens on the cheek), lift that temple to raise the lens. Hint: low side = raise that temple to bring the lens up off the cheek."}'),
  ('abf82ce9-3l','{"options": ["Verify lens thickness", "Determine front surface curvature", "Measure refractive index", "Calculate vertex distance"], "correct": 1, "explanation": "To determine the front surface curvature (the base curve). Hint: a lens clock reads surface curvature; base curve = front curve."}'),
  ('910c75fe-3x','{"options": ["Fitting height too low", "Fitting height too high", "Distance PD too narrow", "Add power too high"], "correct": 0, "explanation": "Fitting height too LOW, the near/corridor sits too low, so the patient lifts the chin to reach it. Hint: lifting the chin to read = the reading zone is set too low."}'),
  ('2c3b721c-32','{"options": ["2%", "4%", "8%", "12%"], "correct": 1, "explanation": "About 4% lost to surface reflection (transmits 96%). Hint: an uncoated lens loses roughly 4% per air-glass interface pair here (100 - 96)."}'),
  ('bff5ae95-4f','{"options": ["Diffraction", "Chromatic aberration", "Spherical aberration", "Coma"], "correct": 1, "explanation": "Chromatic aberration, polycarbonate''s low Abbe value produces color fringes at the periphery. Hint: poly = low Abbe = color fringing (chromatic aberration)."}'),
  ('5c0717c6-33','{"options": ["Barrel distortion", "Pincushion distortion with spectacle magnification", "Chromatic dispersion", "Image minification"], "correct": 1, "explanation": "Pincushion distortion with spectacle magnification, a high plus lens magnifies and pincushions the image. Hint: plus lenses = magnify + pincushion distortion."}'),
  ('14349efe-4s','{"options": ["Refractive index", "Surface accuracy (Newton''s rings)", "Prism imbalance", "Vertex distance"], "correct": 1, "explanation": "Surface accuracy via Newton''s rings, interference rings on an optical flat under monochromatic light. Hint: concentric interference rings on a flat = Newton''s rings (surface figure test)."}'),
  ('42b68bfa-4s','{"options": ["CR-39 spherical with hard coat", "Polycarbonate spherical with UV coating", "1.67 high-index aspheric with AR coating", "Crown glass lenticular lens"], "correct": 2, "explanation": "1.67 high-index aspheric with AR coating, thinnest for -8.00 D with reduced peripheral distortion and reflections. Hint: strong minus + thin + low distortion = high-index aspheric with AR."}'),
  ('ad8170bd-45','{"options": ["Chromatic aberration", "Spectacle magnification", "Barrel distortion", "Accommodation lag"], "correct": 1, "explanation": "Spectacle magnification, plus (hyperopic) spectacles enlarge the retinal image. Hint: plus power magnifies, so objects look bigger."}'),
  ('73469b35-2n','{"options": ["2.2∆ Base In", "2.2∆ Base Out", "1.8∆ Base In", "1.8∆ Base Out"], "correct": 0, "explanation": "2.2 prism diopters Base IN, prism = 0.4 x 5.5 = 2.2, and a minus lens decentered temporally is base in. Hint: 4 mm x 5.5 D = 2.2; minus + temporal = base in."}'),
  ('2159ae16-4d','{"options": ["Increased chromatic aberration", "Asthenopia due to induced prism", "Reduced contrast sensitivity", "Image jump"], "correct": 1, "explanation": "Asthenopia due to induced prism, a 2 mm OC error creates unwanted prism and eyestrain. Hint: misplaced optical centers = induced prism = asthenopia."}'),
  ('283f4091-33','{"options": ["Polycarbonate", "Trivex", "CR-39", "1.74 high-index plastic"], "correct": 2, "explanation": "CR-39 has the highest Abbe value here (about 58), so the least transverse chromatic aberration. Hint: among these, CR-39 = highest Abbe = least color fringing."}'),
  ('d569a224-2n','{"options": ["Speed increases.", "Wavelength increases.", "Frequency decreases.", "Speed decreases while frequency remains constant."], "correct": 3, "explanation": "Speed decreases while frequency stays constant (wavelength shortens). Hint: into denser glass, light slows and its wavelength shrinks, but frequency is fixed."}'),
  ('138ddca9-40','{"options": ["Vertex distance", "Segment inset", "Fitting height", "Lens center thickness"], "correct": 2, "explanation": "Fitting height, poor computer (intermediate) vision with good distance/near points to a corridor/height issue first. Hint: intermediate trouble in a PAL = check the fitting height/corridor."}'),
  ('4f42725b-2f','{"options": ["Increase refractive index", "Reduce surface reflections and improve light transmission", "Reduce chromatic aberration", "Increase impact resistance"], "correct": 1, "explanation": "To reduce surface reflections and improve light transmission. Hint: AR coating = fewer reflections, more light through."}'),
  ('44d58e04-22','{"options": ["Plano-convex", "Aspheric plus lens", "Double-convex", "Meniscus lens"], "correct": 1, "explanation": "Aspheric plus lens minimizes magnification in high hyperopia (flatter form). Hint: aspheric plus = less magnification and thinner for hyperopes."}'),
  ('f015defb-3o','{"options": ["Prism thinning", "Slab-off prism", "High-index material", "Roll-and-polish"], "correct": 1, "explanation": "Slab-off prism corrects the vertical imbalance at near in anisometropia. Hint: anisometropic vertical imbalance at reading = slab-off (bicentric grinding)."}'),
  ('e5ca5430-3w','{"options": ["+3.00 −2.00 × axis", "+1.00 +2.00 × axis", "+3.00 +2.00 × axis", "+1.00 −3.00 × axis"], "correct": 0, "explanation": "+3.00 -2.00 x axis. First (sphere) lines clear at +3.00, second at +1.00, so cyl = +1.00 - (+3.00) = -2.00. Hint: cyl power = (second reading) minus (first reading)."}'),
  ('18c15fc1-2r','{"options": ["Diffraction", "Polarization", "Total internal reflection", "Dispersion"], "correct": 2, "explanation": "Total internal reflection, the basis of fiber optics. Hint: light trapped and bounced inside a fiber = total internal reflection."}'),
  ('f3949fd3-1p','{"options": ["Refractive index decreases.", "Refractive index increases.", "Wavelength increases.", "Frequency decreases."], "correct": 1, "explanation": "The critical angle gets smaller as refractive index INCREASES. Hint: higher index = smaller critical angle (easier total internal reflection)."}'),
  ('2e58b226-3b','{"options": ["Coma", "Oblique astigmatism", "Diffraction", "Polarization"], "correct": 1, "explanation": "Oblique astigmatism dominates peripheral distortion in a strong minus lens. Hint: off-axis blur in strong lenses = oblique astigmatism."}'),
  ('4a13e7a4-2p','{"options": ["Lower the right temple", "Raise the right temple", "Increase face-form wrap", "Widen the bridge"], "correct": 1, "explanation": "Raise the right temple first (to lift the right lens off the cheek). Hint: same as Q54, low side lens on the cheek = raise that temple."}'),
  ('f7bc92df-39','{"options": ["2%", "4%", "8%", "12%"], "correct": 2, "explanation": "About 8% lost to reflection AND absorption (transmits 92%). Hint: 100 - 92 = 8% total loss (reflection + absorption)."}'),
  ('9929553a-1f','{"options": ["Higher refractive index", "Lower impact resistance", "Higher Abbe value with excellent impact resistance", "Greater density"], "correct": 2, "explanation": "Higher Abbe value with excellent impact resistance, Trivex''s edge over polycarbonate. Hint: Trivex = poly-like safety but crisper optics (higher Abbe)."}'),
  ('a4cbd616-2w','{"options": ["Place all prism in one eye.", "Divide prism equally between both lenses whenever clinically appropriate.", "Eliminate horizontal prism.", "Increase pantoscopic tilt."], "correct": 1, "explanation": "Divide the prism equally between both lenses whenever clinically appropriate (best cosmetics). Hint: split prism across both lenses to keep each edge thinner."}'),
  ('dc6d4216-22','{"options": ["Improve distance vision", "Reduce edge thickness and weight", "Reduce image jump", "Eliminate chromatic aberration"], "correct": 1, "explanation": "To reduce edge thickness and weight of the PAL. Hint: prism thinning shaves the bottom edge to lighten/thin the lens."}'),
  ('aa075792-3y','{"options": ["Spherical aberration", "Chromatic aberration secondary to low Abbe value", "Coma", "Fresnel reflection"], "correct": 1, "explanation": "Chromatic aberration secondary to LOW Abbe value (typical of high-index materials). Hint: high index often means low Abbe = color fringes despite sharp acuity."}'),
  ('40e6aef5-2v','{"options": ["The refracted ray bends away from the normal.", "The refracted angle is greater than 40°.", "The velocity of light decreases while its frequency remains constant.", "Both wavelength and frequency increase."], "correct": 2, "explanation": "The velocity decreases while frequency stays constant (entering denser glass). Hint: into glass, slower speed, shorter wavelength, same frequency; the ray bends TOWARD the normal."}'),
  ('46e4f572-2b','{"options": ["CR-39", "Polycarbonate", "1.74 High-index plastic", "Trivex"], "correct": 2, "explanation": "1.74 high-index plastic has the highest refractive index of these. Hint: 1.74 > polycarbonate (1.586) > Trivex (1.53) > CR-39 (1.50)."}'),
  ('3c6aa63a-3o','{"options": ["Equal to the angle of refraction", "Less than the critical angle", "Greater than the critical angle", "Equal to 90°"], "correct": 2, "explanation": "Total internal reflection occurs when the angle of incidence is GREATER than the critical angle. Hint: past the critical angle, all light reflects internally."}'),
  ('f2e59955-1h','{"options": ["The ratio of reflected light to transmitted light", "The ratio of the speed of light in vacuum to the speed of light in the material", "The reciprocal of focal length", "The ratio of wavelength to frequency"], "correct": 1, "explanation": "Refractive index = speed of light in vacuum divided by its speed in the material. Hint: n = c / v."}'),
  ('18ca89f0-30','{"options": ["High-index materials absorb more light.", "High-index materials bend light more efficiently, requiring less curvature.", "High-index materials have higher Abbe values.", "High-index materials reduce reflection."], "correct": 1, "explanation": "High-index materials bend light more efficiently, needing less curvature, so lenses are thinner. Hint: more bending per surface = flatter, thinner lens."}'),
  ('98a18dda-1w','{"options": ["Velocity", "Wavelength", "Frequency", "Refractive index"], "correct": 2, "explanation": "Frequency stays unchanged when light enters glass (speed and wavelength change). Hint: color/frequency is conserved across media; speed and wavelength are not."}'),
  ('01777154-1x','{"options": ["Lens thickness only", "The refractive indices of the two media", "The Abbe value", "Lens diameter"], "correct": 1, "explanation": "The refractive indices of the two media (Snell''s law). Hint: n1 sin(i) = n2 sin(r), only the indices (and angle) matter."}'),
  ('d917ee53-2o','{"options": ["3.0 × 10⁸ m/s", "2.5 × 10⁸ m/s", "1.88 × 10⁸ m/s", "1.60 × 10⁸ m/s"], "correct": 2, "explanation": "About 1.88 x 10^8 m/s, v = c/n = 3.0x10^8 / 1.60 = 1.88x10^8. Hint: speed in medium = c divided by the index."}'),
  ('ecb81ef5-24','{"options": ["Polarization", "Diffraction", "Total internal reflection", "Interference"], "correct": 2, "explanation": "Total internal reflection gives diamonds their sparkle (high index, small critical angle). Hint: diamond''s tiny critical angle traps and bounces light = sparkle (TIR)."}'),
  ('bb361ea3-35','{"options": ["High-index materials have lower density.", "Surface reflectance increases as refractive index increases.", "The Abbe value is higher.", "The critical angle becomes larger."], "correct": 1, "explanation": "Surface reflectance INCREASES as refractive index increases, so high-index lenses reflect more (hence AR coatings). Hint: higher index = more reflection = needs AR."}'),
  ('4f3b52e2-5j','{"options": ["Cement bifocal", "Split or two-piece bifocal", "Fused bifocal", "Solid or one-piece bifocal"], "correct": 2, "explanation": "A fused bifocal, a higher-index segment fused into a depression in the crown-glass major lens. Hint: fused = a higher-index button melted into the main lens."}'),
  ('a7c0d094-4q','{"options": ["Straight top bifocal", "Executive bifocal", "Ultex bifocal", "Round (Kryptok) bifocal"], "correct": 1, "explanation": "An Executive (Franklin) bifocal, full-width segment for the widest near field (visible line). Hint: widest reading field, does not mind the line = Executive/E-line."}'),
  ('78ca2d1b-8r','{"options": ["Its segment line is thick and highly visible on casual inspection", "Its one-piece construction produces a deep cleft that distorts near vision", "It produces a large amount of image jump and requires greater eye movement to reach the widest part of the segment", "Its reading area is reduced because the segment top is flattened"], "correct": 2, "explanation": "It produces a large amount of image jump and needs more eye movement to reach the widest part (round segment traits). Hint: round seg = big image jump + the wide zone is low down."}'),
  ('860d8993-5a','{"options": ["Iron oxide", "Manganese", "Cerium", "Cobalt oxide"], "correct": 3, "explanation": "Cobalt oxide gives glass a blue tint. Hint: cobalt = blue glass."}'),
  ('b267c937-66','{"options": ["Yellow", "Red", "Gray", "Green"], "correct": 0, "explanation": "Yellow, it blocks blue-green, sharpens contrast, and aids depth in low light (dawn). Hint: yellow/amber = high-contrast, haze-cutting, low-light shooting tint."}'),
  ('d2fa4c0c-5g','{"options": ["Crown glass", "Plastic CR-39", "Trivex", "Polycarbonate"], "correct": 3, "explanation": "Polycarbonate has the lowest Abbe value here, so the greatest chromatic aberration. Hint: poly = lowest Abbe = most color fringing."}'),
  ('52732826-2j','{"options": ["3.87%", "4.30%", "5.05%", "8.60%"], "correct": 1, "explanation": "About 4.30%, R = ((n-1)/(n+1))^2 = (0.523/2.523)^2 = 0.043 = 4.3%. Hint: Fresnel single-surface reflection = ((n-1)/(n+1))^2."}'),
  ('a7ccdbbc-41','{"options": ["96.13%", "92.41%", "90.05%", "88.50%"], "correct": 1, "explanation": "About 92.41%, transmission = (1 - 0.0387)^2 = 0.9613^2 = 0.9241. Hint: multiply the surviving fraction at each of the two surfaces."}'),
  ('0c22e16c-3o','{"options": ["4.30%", "5.05%", "6.72%", "13.44%"], "correct": 2, "explanation": "About 6.72%, R = ((1.70-1)/(1.70+1))^2 = (0.70/2.70)^2 = 0.0672. Hint: higher index (1.70) reflects more per surface."}'),
  ('5918eefc-57','{"options": ["80%", "72%", "64%", "60%"], "correct": 2, "explanation": "64%, combined transmission = 0.80 x 0.80 = 0.64. Hint: multiply the transmissions in series (0.8 x 0.8)."}'),
  ('2480d82b-47','{"options": ["20%", "36%", "44%", "64%"], "correct": 1, "explanation": "36% opacity, opacity = 100% - transmission = 100 - 64 = 36%. Hint: opacity = 1 minus transmittance."}'),
  ('4841b00c-2x','{"options": ["0.19", "0.36", "0.64", "1.94"], "correct": 0, "explanation": "About 0.19, optical density = log10(1/T) = log10(1/0.64) = 0.194. Hint: OD = log(1/transmittance)."}'),
  ('a7eb1b16-4t','{"options": ["+1.25 D", "+2.50 D", "+3.25 D", "+4.50 D"], "correct": 2, "explanation": "+3.25 D, the trifocal intermediate = distance + half the add = +2.00 + 1.25 = +3.25 D. Hint: intermediate = distance power + 50% of the add."}'),
  ('05cea5ab-4x','{"options": ["–0.50 D", "+0.50 D", "+1.00 D", "–1.00 D"], "correct": 0, "explanation": "-0.50 D, intermediate = -1.50 + (half of +2.00 = +1.00) = -0.50 D. Hint: distance + half the add (works with minus distance too)."}'),
  ('8eef3d76-2z','{"options": ["0.30", "0.50", "0.70", "1.30"], "correct": 0, "explanation": "About 0.30, optical density = log10(1/0.50) = log10(2) = 0.301. Hint: 50% transmission = OD of 0.3."}'),
  ('6fdf015f-1b','{"options": ["Grinding → Blocking → Marking → Polishing → De-blocking → Smoothing", "Marking → Blocking → Grinding → Smoothing → Polishing → De-blocking", "Blocking → Marking → Polishing → Grinding → De-blocking → Smoothing", "Cutting → Blocking → Marking → Polishing → Grinding → De-blocking"], "correct": 1, "explanation": "Marking -> Blocking -> Grinding -> Smoothing -> Polishing -> De-blocking is the surfacing order. Hint: lay out, block, rough-grind, fine/smooth, polish, then deblock."}'),
  ('97f4b9f2-s','{"options": ["Vacuum coating", "Immersion in hot dye", "Electroplating", "Spray coating"], "correct": 1, "explanation": "Plastic lenses are tinted by immersion in hot dye. Hint: plastic soaks up dye from a hot tint bath; glass is tinted in the melt/coated."}'),
  ('3605dd77-h','{"options": ["Tinting the lens", "Polishing", "Inserting the lens into the frame", "Measuring lens power"], "correct": 2, "explanation": "Glazing = inserting/mounting the lens into the frame. Hint: glazing is the fitting of lenses into the frame."}'),
  ('946afc3c-11','{"options": ["High-index plastic", "Polycarbonate", "Crown glass", "Trivex"], "correct": 2, "explanation": "Crown glass has the highest Abbe value (about 59). Hint: crown glass and CR-39 top the Abbe list (crown edges it)."}'),
  ('ba0e18ec-1o','{"options": ["Flat-top", "Executive", "Round segment", "Ultex"], "correct": 1, "explanation": "The Executive bifocal is the thick, heavy, less cosmetic design. Hint: the full-ledge Executive is the heavyweight bifocal."}'),
  ('3e12ae64-s','{"options": ["Chromatic aberration", "Placing Base-up prism", "Sudden introduction of base-down prism", "Lens thickness"], "correct": 2, "explanation": "Image jump comes from the SUDDEN introduction of base-down prism at the segment top. Hint: crossing into the seg top adds abrupt base-down prism = image jump."}'),
  ('b10d2d3b-v','{"options": ["Less UV than glass", "The same UV as glass", "More UV than glass", "No UV"], "correct": 2, "explanation": "Plastic (CR-39) absorbs MORE UV than crown glass. Hint: plastic naturally blocks more UV than ordinary glass."}'),
  ('8723586b-1q','{"options": ["Bayer Test", "Steel Wool Test", "Taber Test", "Drop Ball Test"], "correct": 2, "explanation": "The Taber test measures scratch/abrasion resistance with an abrasion wheel. Hint: Taber = abrasion WHEEL; Bayer = shaking sand; Drop-ball = impact."}'),
  ('0fc4a135-1i','{"options": ["Gold bifocal", "Double D trifocal", "Executive bifocal", "Round segment bifocal"], "correct": 1, "explanation": "A Double-D trifocal suits librarians (near at the bottom AND top for high shelves). Hint: two segments (up and down) for reaching high and low = Double-D."}'),
  ('3616a3d1-4i','{"options": ["High transparency", "Low refractive index", "Low Abbe Value", "High scratch resistance"], "correct": 2, "explanation": "Low Abbe value causes the peripheral color fringes in high-index lenses. Hint: low Abbe = chromatic aberration at the lens edge."}'),
  ('8e780957-2t','{"options": ["Back surface", "Front surface", "Both surface", "Edge only"], "correct": 0, "explanation": "The BACK surface, a semi-finished lens has a finished front and needs the back surfaced/ground to power. Hint: semi-finished = front done, grind the back to Rx."}'),
  ('87cf2746-3i','{"options": ["Yellow", "Gray", "Brown", "Green"], "correct": 0, "explanation": "Yellow (same as Q117), best contrast in fog. Hint: fog driving = yellow/amber tint."}'),
  ('3fc2fc37-6w','{"options": ["Round-segment bifocal", "Flat-top bifocal", "Franklin bifocal", "Cemented bifocal"], "correct": 1, "explanation": "A flat-top bifocal, wider reading area with less image jump than a round segment. Hint: flat-top = wide near field + low image jump."}'),
  ('13e9ac7d-32','{"options": ["Increased image jump", "Flatter and thinner lens", "Greater lens thickness", "Higher chromatic aberration"], "correct": 1, "explanation": "A flatter and thinner lens is the primary advantage of an aspheric design in strong Rx. Hint: aspheric = flatter, thinner, less magnification."}'),
  ('c19f597f-3w','{"options": ["Mechanical trauma from tight lens fit", "Allergic conjunctivitis", "Infectious keratitis", "Dry eye syndrome"], "correct": 0, "explanation": "Mechanical trauma from a tight lens fit (superior epithelial arcuate lesions, SEALs). Hint: an arcuate superior scrape from a rigid/tight lens = mechanical SEAL."}'),
  ('9971815a-25','{"options": ["Soft toric lenses", "Scleral lenses", "Daily disposable soft lenses", "Conventional RGP lenses"], "correct": 1, "explanation": "Scleral lenses are the best choice for keratoconus (vault the cone with a tear reservoir). Hint: keratoconus comfort/vision champion = scleral."}'),
  ('a3374e0c-2e','{"options": ["Corneal curvature radius", "Pupil size", "Lid anatomy", "Lens diameter"], "correct": 0, "explanation": "Corneal curvature radius most determines a soft lens base curve. Hint: fit the base curve to the corneal curvature."}'),
  ('6d3484b7-38','{"options": ["Change to monovision correction", "Adjust the add power", "Refit with a different multifocal design", "Prescribe lubricating drops"], "correct": 1, "explanation": "Adjust the add power first for ghosting with a multifocal contact lens. Hint: multifocal ghosting = tweak the add before switching designs."}'),
  ('8f41c25e-2f','{"options": ["Multipurpose solutions", "Hydrogen peroxide systems", "Saline solutions", "Enzymatic cleaners"], "correct": 1, "explanation": "Hydrogen peroxide systems are most effective against Acanthamoeba. Hint: for Acanthamoeba, peroxide beats multipurpose solutions."}'),
  ('7dc4ca8b-2g','{"options": ["Corneal infiltrate with overlying epithelial defect", "Papillary conjunctivitis", "Corneal neovascularization", "Dry eye"], "correct": 0, "explanation": "A corneal infiltrate with an overlying epithelial defect is the hallmark of microbial keratitis. Hint: infiltrate + epithelial break = infection (keratitis), an emergency."}'),
  ('fd6abdda-22','{"options": ["Daily cleaning with multipurpose solution", "Weekly enzymatic cleaning", "Cleaning with soap and water", "Monthly hydrogen peroxide cleaning"], "correct": 0, "explanation": "Daily cleaning with a (gentle) multipurpose solution is generally advised for prosthetic lenses; avoid harsh agents that damage the tint. VERIFY the manufacturer''s specific care. Hint: prosthetic/painted lenses need gentle daily care, no soap/harsh systems."}'),
  ('c4981f62-30','{"options": ["Monovision soft lenses", "Multifocal concentric design lenses", "Aspheric soft multifocal lenses", "RGP spherical lenses"], "correct": 2, "explanation": "Aspheric soft multifocal lenses are used for EDOF (extended depth of focus) presbyopia correction. Hint: EDOF = aspheric multifocal soft design."}'),
  ('f9eeace3-20','{"options": ["Corneal abrasion", "Conjunctival prolapse", "Corneal edema", "Giant papillary conjunctivitis"], "correct": 2, "explanation": "Corneal edema (hypoxic) is a leading scleral-lens complication (thick lens + fluid reservoir limit oxygen). Some cite midday fogging/conjunctival prolapse, so VERIFY. Hint: a thick vaulted scleral can starve the cornea of oxygen = edema."}'),
  ('d0a1aefc-2h','{"options": ["1 day, 1 week, and 1 month after fitting", "1 week and 1 month after fitting", "1 day and 6 months after fitting", "1 month and 3 months after fitting"], "correct": 0, "explanation": "1 day, 1 week, and 1 month after fitting is the standard new-wearer follow-up. Hint: new CL fit follow-up = 1 day, 1 week, 1 month."}'),
  ('43f4f925-2z','{"options": ["Giant papillary conjunctivitis", "Corneal ulcer", "Allergic conjunctivitis", "Dry eye syndrome"], "correct": 0, "explanation": "Giant papillary conjunctivitis (red, itchy eyes with mucous discharge and upper-lid papillae). Hint: itch + mucus + lens wear = GPC."}'),
  ('9677888b-1w','{"options": ["Central corneal thickness", "Corneal topography", "Pupil size", "Tear film osmolarity"], "correct": 1, "explanation": "Corneal topography is the most critical parameter for ortho-k fitting. Hint: ortho-k reshapes the cornea, so map it first (topography)."}'),
  ('52569a0f-29','{"options": ["Hydrogen peroxide solution", "Multipurpose solution with preservatives", "Enzymatic cleaner", "Saline solution"], "correct": 0, "explanation": "A hydrogen peroxide system is safest for sensitive eyes (preservative-free once neutralized). Hint: sensitive/allergic eyes = peroxide (no preservatives)."}'),
  ('74397d7b-25','{"options": ["To control lens movement and comfort", "To increase oxygen permeability", "To adjust optical power", "To improve color tinting"], "correct": 0, "explanation": "To control lens movement and comfort, the primary role of RGP edge design. Hint: the RGP edge governs movement, tear exchange, and comfort."}'),
  ('ba5b6330-2z','{"options": ["Pseudomonas aeruginosa", "Staphylococcus aureus", "Candida albicans", "Acanthamoeba"], "correct": 0, "explanation": "Pseudomonas aeruginosa is the most common cause of CL-related microbial keratitis. Hint: contact-lens keratitis = think Pseudomonas first."}'),
  ('10648233-1y','{"options": ["Lens color", "Lens material composition", "Lens thickness", "Lens diameter"], "correct": 1, "explanation": "Lens MATERIAL composition most determines oxygen permeability (Dk). Hint: Dk is a material property; thickness affects Dk/t, not Dk itself."}'),
  ('40289520-2o','{"options": ["Immediate discontinuation of lens wear and topical antibiotics", "Continue lens wear and prescribe lubricants", "Prescribe corticosteroids", "No treatment necessary"], "correct": 0, "explanation": "Discontinue lens wear immediately and start topical antibiotics for a CL-related corneal abrasion. Hint: CL abrasion = stop lenses + antibiotic cover (never patch/steroid)."}'),
  ('0ed6e9cc-24','{"options": ["Soft spherical lenses", "RGP lenses", "Prosthetic lenses", "Hybrid lenses"], "correct": 1, "explanation": "RGP lenses give the best optics for aphakia (high plus power). Hint: aphakia = high plus, RGP for the sharpest correction."}'),
  ('93a1471f-1u','{"options": ["Surfactants", "Preservatives", "Buffers", "Enzymes"], "correct": 1, "explanation": "Preservatives prevent microbial growth in contact-lens solutions. Hint: the preservative is the germ-killer in the bottle."}'),
  ('0c44f8f2-23','{"options": ["High oxygen permeability", "UV protection and impact resistance", "Cosmetic enhancement", "Daily disposable design"], "correct": 3, "explanation": "A daily disposable design is the most practical/safe choice for sports (hygiene, easy replacement), since lenses themselves offer no impact protection. VERIFY the intent, some keys stress oxygen/UV. Hint: for sport, favor daily disposables and pair them with protective eyewear."}'),
  ('528762e9-3v','{"options": ["Continue lens wear but clean lenses thoroughly", "Remove lenses immediately and discontinue wear until symptoms resolve", "Use corticosteroid eye drops with lenses in place", "Increase lens wear time to improve tolerance"], "correct": 1, "explanation": "Remove the lenses immediately and stop wear until symptoms resolve (water-exposed lenses risk infection). Hint: swimming symptoms = take lenses out, stop wear (Acanthamoeba risk)."}'),
  ('2f68c64c-2j','{"options": ["Hydrophobicity", "Refractive index", "Tensile strength", "Oxygen permeability"], "correct": 0, "explanation": "Surface hydrophobicity/ionicity most affects protein deposition (charged, high-water surfaces attract more protein). VERIFY the property your key names. Hint: surface chemistry (hydrophobic/non-ionic) drives how much protein sticks."}'),
  ('0f9d1c79-27','{"options": ["Lens dehydration and reduced tear exchange", "Allergic reaction to lens solution", "Excessive blinking", "Corneal ulceration"], "correct": 0, "explanation": "Lens dehydration and reduced tear exchange is the most common cause of CL-related dry eye. Hint: the lens drying out and blocking tear turnover = CL dry eye."}'),
  ('580ce998-1u','{"options": ["Lower cost", "Improved convenience and hygiene", "Higher oxygen permeability", "Longer wear time"], "correct": 1, "explanation": "Improved convenience and hygiene is the main advantage of daily disposables. Hint: fresh lens daily = best hygiene/convenience (not cost)."}'),
  ('7e6601f4-2g','{"options": ["Tonometry", "Tear breakup time", "Visual acuity test", "Retinoscopy"], "correct": 1, "explanation": "Tear breakup time (TBUT) best assesses dry-eye severity in lens wearers. Hint: dry-eye severity = TBUT (tear-film stability)."}'),
  ('7b312306-1s','{"options": ["Daily cleaning with enzymatic cleaner and saline rinse", "Weekly cleaning with multipurpose solution", "Rinsing with saline only after removal", "Monthly cleaning with hydrogen peroxide"], "correct": 0, "explanation": "Daily cleaning plus a saline rinse is the core scleral routine (fill and clean daily). VERIFY the exact cleaner/regimen. Hint: sclerals = clean daily + rinse/fill with preservative-free saline."}'),
  ('3c469446-3h','{"options": ["Multifocal lenses", "Monovision lenses", "Bifocal spectacles", "Scleral lenses"], "correct": 1, "explanation": "Monovision, one eye set for distance and the other for near. Hint: one eye far, one eye near = monovision."}'),
  ('325ea136-1q','{"options": ["Infectious keratitis", "Corneal staining", "Corneal neovascularization", "Allergic conjunctivitis"], "correct": 2, "explanation": "Corneal neovascularization is least likely with (high-Dk, overnight-only) ortho-k. Common ortho-k issues are infectious keratitis and corneal staining. VERIFY. Hint: high-oxygen RGP ortho-k rarely grows new vessels; infection/staining are the real risks."}'),
  ('911d80f9-23','{"options": ["High water content", "Silicone component", "Thin lens design", "UV blocker"], "correct": 1, "explanation": "The silicone component most improves oxygen transmission in silicone hydrogels. Hint: silicone (not water) carries the oxygen in SiHy lenses."}'),
  ('a887d9fd-3s','{"options": ["Infectious keratitis", "Corneal abrasion", "Contact lens-induced papillary conjunctivitis", "Corneal edema"], "correct": 0, "explanation": "Infectious keratitis, a ring-shaped infiltrate with hypopyon after extended wear (classically Acanthamoeba). Hint: ring infiltrate + hypopyon in a lens wearer = infectious (Acanthamoeba) keratitis."}'),
  ('b0017362-5t','{"options": ["II", "IV", "I", "III"], "correct": 0, "explanation": "Safety glasses (II, option A) are the basic eye protection for general work with dust and flying particles. A face shield adds secondary protection, safety lenses are a lens component, and keeping away from children is not eye PPE. General particle protection = safety glasses."}'),
  ('ff179870-6n','{"options": ["III", "II", "I", "IV"], "correct": 0, "explanation": "A face shield (III, option A) is worn OVER safety glasses/goggles to add splash, heat, and blood-borne protection to the face. Face shield = secondary full-face protection worn with primary eyewear."}'),
  ('5065c42c-5m','{"options": ["I", "II", "IV", "III"], "correct": 2, "explanation": "Safety lenses (IV, option C) made of impact-resistant polycarbonate or trivex protect against impact. Impact-resistant lens materials = safety lenses."}'),
  ('02a5bc08-51','{"options": ["IV", "II", "III", "I"], "correct": 3, "explanation": "Keeping hazards away from children (I, option D) is a free, simple, and effective preventive measure. Low-cost general prevention = keep away from children."}'),
  ('6183f586-67','{"options": ["I", "II", "IV", "III"], "correct": 0, "explanation": "A behavioral measure (keeping hazards away from children, I, option A) does not degrade with moisture/heat/chemicals or wear like physical PPE does. A habit does not wear out; equipment does."}'),
  ('25edb540-4t','{"options": ["I", "II", "III", "IV"], "correct": 0, "explanation": "Keratoconus (I, option A) is a progressive corneal ectasia (conical thinning) that typically begins around puberty. Progressive conical thinning from adolescence = keratoconus."}'),
  ('18961a02-4v','{"options": ["II", "I", "III", "IV"], "correct": 0, "explanation": "Cornea guttata (II, option A) is the deposition of hyaline excrescences (guttae) on Descemet''s membrane/endothelium across the posterior cornea. Posterior hyaline excrescences = cornea guttata."}'),
  ('c9bb3375-5v','{"options": ["II", "III", "I", "IV"], "correct": 1, "explanation": "Keratoplana (cornea plana) (III, option B) is an abnormally FLAT cornea with an indistinct limbus and deep stromal changes. Flat cornea, indistinct limbus = keratoplana."}'),
  ('54b597f1-5w','{"options": ["III", "IV", "II", "I"], "correct": 1, "explanation": "Megalocornea (IV, option B) is a non-progressive congenital enlargement of the cornea (diameter 12 to 16 mm or more). Large, stable, congenital cornea = megalocornea."}'),
  ('3d35cb52-4i','{"options": ["III", "II", "I", "IV"], "correct": 2, "explanation": "Gradual bilateral apical thinning is keratoconus (I, option C), which thins and steepens the corneal apex into a cone. Apical thinning/steepening = keratoconus."}'),
  ('7061f1f1-3x','{"options": ["III", "IV", "I", "II"], "correct": 2, "explanation": "Mydriasis (I, option C) is a dilated pupil. Miosis is constriction, anisocoria is unequal size, and corectopia is displacement. Dilated pupil = mydriasis."}'),
  ('8f41b98c-41','{"options": ["III", "II", "IV", "I"], "correct": 1, "explanation": "Miosis (II, option B) is a constricted (small) pupil. Constricted pupil = miosis."}'),
  ('35b07a68-3f','{"options": ["II", "IV", "III", "I"], "correct": 2, "explanation": "Anisocoria (III, option C) means the two pupils are of unequal size. Unequal pupils = anisocoria."}'),
  ('e8ae3563-3o','{"options": ["III", "I", "II", "IV"], "correct": 3, "explanation": "Corectopia (IV, option D) is an abnormally positioned (displaced) pupil. Off-center pupil = corectopia."}'),
  ('cded0239-42','{"options": ["III", "II", "IV", "I"], "correct": 1, "explanation": "A parasympathomimetic (cholinergic) drop stimulates the iris sphincter, causing miosis (II, option B). Parasympathomimetic = constriction (miosis)."}'),
  ('3bb1fb09-5y','{"options": ["I", "III", "II", "IV"], "correct": 0, "explanation": "Catarrhal conjunctivitis (I, option A) features a mucoid discharge and is linked to colds, allergy, and irritation. Mucoid, irritation-associated = catarrhal."}'),
  ('999f2c57-3x','{"options": ["I", "III", "IV", "II"], "correct": 3, "explanation": "Purulent conjunctivitis (II, option D) produces pus (a thick, mucopurulent discharge), typically bacterial (for example gonococcal). Pus = purulent."}'),
  ('cab0232b-5o','{"options": ["II", "III", "IV", "I"], "correct": 1, "explanation": "Papillary conjunctivitis (III, option B) forms papillae, elevations with a central vascular tuft surrounded by inflammatory (lymphoid) cells. Papillae with central vessel = papillary."}'),
  ('11b9813c-3r','{"options": ["I", "II", "IV", "III"], "correct": 2, "explanation": "Membranous conjunctivitis (IV, option C) forms an inflammatory membrane on the conjunctiva. Membrane formation = membranous."}'),
  ('82d65888-66','{"options": ["II", "IV", "I", "III"], "correct": 1, "explanation": "Diphtheritic conjunctivitis (Corynebacterium diphtheriae) forms a TRUE membrane that bleeds when peeled, a membranous conjunctivitis (IV, option B). True bleeding membrane = membranous (diphtheritic)."}'),
  ('8eadbffb-47','{"options": ["III", "IV", "I", "II"], "correct": 2, "explanation": "Elevated IOP results from increased resistance to AQUEOUS (I, option C) outflow. Poor aqueous drainage = high IOP."}'),
  ('3bc33347-47','{"options": ["III", "I", "IV", "II"], "correct": 3, "explanation": "Blockage of the canal of Schlemm (II, option D), which collects aqueous from the meshwork, raises IOP. Canal of Schlemm blockage = raised IOP."}'),
  ('bde954e3-40','{"options": ["II", "III", "IV", "I"], "correct": 1, "explanation": "Aqueous drains through the trabecular meshwork (trabecula) (III, option B), the main site of outflow resistance/blockage. Aqueous passes through the trabecular meshwork."}'),
  ('2fd17d3a-41','{"options": ["I", "II", "III", "IV"], "correct": 3, "explanation": "When the iris (IV, option D) crowds and blocks the drainage angle, angle-closure glaucoma occurs. Iris blocking the angle = angle closure."}'),
  ('dfdd450a-4b','{"options": ["III", "I", "II", "IV"], "correct": 3, "explanation": "Open (wide) angle glaucoma involves aqueous, the trabecular meshwork, and Schlemm''s canal. The iris (IV, option D) is the culprit in ANGLE CLOSURE, not open angle, so it is the EXCEPT. Iris = angle-closure mechanism, not open angle."}'),
  ('dec13446-4f','{"options": ["II", "III", "IV", "I"], "correct": 3, "explanation": "A hospital-acquired infection is nosocomial (I, option D). Acquired in hospital = nosocomial."}'),
  ('a105a04b-60','{"options": ["III", "IV", "II", "I"], "correct": 2, "explanation": "Infection introduced by a contaminated instrument/procedure is iatrogenic (II, option C). Caused by the medical procedure/instrument = iatrogenic."}'),
  ('c612588b-4r','{"options": ["IV", "II", "I", "III"], "correct": 3, "explanation": "An infected practitioner passing infection to a patient is a human (III, option D) source. Person-to-person transmission = human source."}'),
  ('42a41eb0-52','{"options": ["IV", "II", "I", "III"], "correct": 0, "explanation": "Contamination from soil is an environmental (IV, option A) source. Soil/surroundings exposure = environment."}'),
  ('7eb967ca-67','{"options": ["I", "III", "II", "IV"], "correct": 2, "explanation": "Spreading infection via an inadequately disinfected instrument between patients is iatrogenic (II, option C). Contaminated shared instrument = iatrogenic."}'),
  ('91f8fd3b-47','{"options": ["I", "IV", "II", "III"], "correct": 0, "explanation": "Chemical, thermal, and radiation exposures all cause burns (I, option A). Chemical/thermal/radiation = burns."}'),
  ('c9cbbc1c-40','{"options": ["III", "IV", "I", "II"], "correct": 3, "explanation": "A glass chip lodged in the eye is a foreign body (II, option D). Embedded fragment = foreign body."}'),
  ('2a3f8b4f-3e','{"options": ["III", "I", "IV", "II"], "correct": 0, "explanation": "A puncture through the globe wall is a perforating (III, option A) injury. Full-thickness puncture = perforating."}'),
  ('31c96f43-4q','{"options": ["IV", "II", "I", "III"], "correct": 0, "explanation": "A tear in the tissue is a laceration (IV, option A). Tissue tear = laceration."}'),
  ('6fbd7531-4c','{"options": ["IV", "I", "III", "II"], "correct": 3, "explanation": "Loose lashes lodged under the lid are foreign bodies (II, option D). Stray lashes lodged in the lid = foreign body."}'),
  ('b1af1338-52','{"options": ["IV", "I", "III", "II"], "correct": 1, "explanation": "Failing to recognize/see a hazard is a failure of Identification (I, option B). Not spotting the hazard = identification failure."}'),
  ('faa1f31c-44','{"options": ["IV", "II", "I", "III"], "correct": 1, "explanation": "Not understanding a hazard''s potential is a gap in Education (II, option B). Lack of hazard understanding = education failure."}'),
  ('223e8d11-4u','{"options": ["III", "II", "I", "IV"], "correct": 0, "explanation": "Putting the rules into practice is Implementation (III, option A). Applying/enforcing the rules = implementation."}'),
  ('ff88e287-4l','{"options": ["II", "III", "I", "IV"], "correct": 3, "explanation": "Providing/using protective devices is Instrumentation (IV, option D). Protective equipment = instrumentation."}'),
  ('0d8d9053-4b','{"options": ["III", "IV", "I", "II"], "correct": 1, "explanation": "Not using the provided device is a failure of Instrumentation (IV, option B). PPE non-use = instrumentation failure."}'),
  ('fb57de0d-5e','{"options": ["III", "I", "II", "IV"], "correct": 1, "explanation": "Scleral stretching and thinning under pressure is ectasia (I, option B). Stretched, thinned sclera = ectasia."}'),
  ('7da875b5-4d','{"options": ["I", "IV", "II", "III"], "correct": 2, "explanation": "A bulging out-pouching of the sclera lined by uveal tissue is a staphyloma (II, option C). Scleral bulge with uvea = staphyloma."}'),
  ('a11909ba-4s','{"options": ["III", "II", "I", "IV"], "correct": 0, "explanation": "The sclera proper (III, option A) is the dense, largely avascular collagen/elastic tunic. Tough fibrous collagen coat = sclera proper."}'),
  ('b0a6219a-5s','{"options": ["I", "III", "II", "IV"], "correct": 3, "explanation": "The outer sclera (episclera) (IV, option D) is the thin, vascular connective tissue overlying the sclera, thickest anteriorly. Vascular surface layer of the sclera = episclera (outer sclera)."}'),
  ('572aa538-33','{"options": ["I", "II", "I & II", "III & IV"], "correct": 2, "explanation": "Ectasia and staphyloma (I & II, option C) are pathological conditions, not tissues, so they cannot be graft material, unlike the sclera proper and episclera. VERIFY: the item mixes conditions with tissue layers, so it is loosely constructed; the disease states are the non-graftable items."}'),
  ('94614834-5e','{"options": ["IV", "III", "II", "I"], "correct": 3, "explanation": "Retinal detachment (I, option D) is separation of the retina from the underlying choroid/RPE, giving a curtain over the vision. Curtain vision, retina off the choroid = retinal detachment."}'),
  ('cb177990-4t','{"options": ["IV", "III", "I", "II"], "correct": 3, "explanation": "Complete lens dislocation is luxation (II, option D); partial is subluxation. Complete lens dislocation = luxation."}'),
  ('6656876a-4w','{"options": ["II", "I", "III", "IV"], "correct": 3, "explanation": "Partial lens dislocation is subluxation (IV, option D). Partial lens dislocation = subluxation."}'),
  ('d58c3484-54','{"options": ["IV", "II", "III", "I"], "correct": 2, "explanation": "Ruptured vessels produce hemorrhages (III, option C). Vessel rupture = hemorrhage."}'),
  ('a2c9e578-3i','{"options": ["III & I", "I & II", "II & IV", "IV & III"], "correct": 2, "explanation": "Lens dislocation (luxation and subluxation, II & IV, option C) can traumatize the lens and lead to cataract. VERIFY: retinal detachment/hemorrhage are separate trauma outcomes; lens displacement is the pathway to traumatic cataract in this set. Lens displacement = traumatic cataract."}'),
  ('6da6a082-6x','{"options": ["I", "II", "IV", "III"], "correct": 3, "explanation": "Wilson''s disease is hepatolenticular degeneration (III, option D), whose copper deposition produces the corneal Kayser-Fleischer ring. Wilson''s = hepatolenticular degeneration (K-F ring)."}'),
  ('563aec8b-6x','{"options": ["I", "IV", "III", "II"], "correct": 0, "explanation": "Maternal hyperglycemia (diabetes mellitus, I, option A) during gestation causes metabolic effects (and cataract risk) in the child. Maternal high blood sugar = diabetes mellitus."}'),
  ('ba3ad26d-77','{"options": ["III", "I", "IV", "II"], "correct": 1, "explanation": "Diabetes mellitus (I, option B) alters lens glucose/sorbitol metabolism, driving the diabetic (sugar) cataract. Lens glucose-metabolism disturbance = diabetes mellitus."}'),
  ('e782afc5-4v','{"options": ["III", "IV", "II", "I"], "correct": 1, "explanation": "Cretinism (IV, option B) is severe congenital hypothyroidism in infants. Congenital severe hypothyroidism = cretinism."}'),
  ('62eaca67-5s','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "Diabetes mellitus (I, option D), especially type 2, is a classic lifestyle-related disease. Lifestyle-related metabolic disease = diabetes mellitus."}'),
  ('979afd88-4g','{"options": ["IV", "I", "III", "II"], "correct": 1, "explanation": "Gonioscopy (I, option B) uses a special contact lens (goniolens) to view the anterior chamber angle. Angle assessment with a lens = gonioscopy."}'),
  ('a0818b84-4l','{"options": ["III", "IV", "II", "I"], "correct": 2, "explanation": "Tonometry (II, option C) measures IOP and (for applanation) requires a topical anesthetic. IOP measurement with anesthetic = tonometry."}'),
  ('3cba8b81-47','{"options": ["IV", "II", "I", "III"], "correct": 3, "explanation": "Perimetry (III, option D) maps the visual field (including the central 30 to 60 degrees). Field mapping = perimetry."}'),
  ('e00e68a1-3z','{"options": ["IV", "III", "I", "II"], "correct": 0, "explanation": "Ophthalmoscopy (IV, option A) visualizes the optic disc to assess the cup-to-disc ratio. Disc cupping = ophthalmoscopy."}'),
  ('df63beef-43','{"options": ["II", "III", "I", "IV"], "correct": 3, "explanation": "Ophthalmoscopy (IV, option D), a non-contact look with a light, is the least intimidating of these (versus touching the eye for tonometry/gonioscopy). VERIFY: ''least intimidating'' is subjective; ophthalmoscopy involves no eye contact. Non-contact light exam = least intimidating."}'),
  ('79cee047-5s','{"options": ["II", "IV", "I", "III"], "correct": 2, "explanation": "Anencephaly (I, option C) is failure of the brain above the medulla to develop, with an absent cranial vault. Absent brain/cranial vault = anencephaly."}'),
  ('1403c0a7-4t','{"options": ["I", "IV", "III", "II"], "correct": 1, "explanation": "Crouzon''s disease (IV, option B) (craniofacial dysostosis) gives shallow orbits with proptosis and a frog-like facies. Frog-like face with proptosis = Crouzon''s."}'),
  ('f23263ae-56','{"options": ["II", "I", "IV", "III"], "correct": 0, "explanation": "Hypertelorism (II, option A) is an abnormally wide distance between the orbits/eyes. Wide-set eyes = hypertelorism."}'),
  ('4bc35400-4v','{"options": ["IV", "III", "I", "II"], "correct": 1, "explanation": "Franceschetti''s (Treacher Collins) syndrome (III, option B), mandibulofacial dysostosis, features underdeveloped (hypoplastic) mandible and malar bones. Underdeveloped jaw/cheekbones = Franceschetti''s (Treacher Collins)."}'),
  ('49d34540-59','{"options": ["II", "IV", "I", "III"], "correct": 3, "explanation": "Franceschetti''s syndrome (III, option D) is also known by additional eponyms (Franceschetti-Klein / Treacher Collins), reflecting more than one clinical name. VERIFY: this item''s meaning is vague; Franceschetti''s mandibulofacial dysostosis carries multiple eponyms."}'),
  ('19272fe5-53','{"options": ["I", "II", "IV", "III"], "correct": 0, "explanation": "Discomfort in the head (the uppermost part of the body) is a dull headache (I, option A). Head discomfort = headache."}'),
  ('6f9a74c3-56','{"options": ["I", "II", "IV", "III"], "correct": 1, "explanation": "Raised IOP forces fluid into the corneal epithelium, causing edema (II, option B) (which then produces halos). High IOP = corneal (epithelial) edema."}'),
  ('a481c0b4-5n','{"options": ["IV", "I", "II", "III"], "correct": 3, "explanation": "Corneal epithelial edema scatters light into colored rings, so the patient sees halos around lights (III, option D). Corneal edema = halos around lights."}'),
  ('68f8f9d7-5h','{"options": ["II", "I", "III", "IV"], "correct": 3, "explanation": "Open-angle glaucoma silently and painlessly progresses toward blindness (IV, option D). VERIFY: the item conflates the slow process with its endpoint; the detrimental silent outcome is vision loss/blindness. Painless slow damage in POAG = progressive (blinding) loss."}'),
  ('7f4f850c-51','{"options": ["I", "III", "II", "IV"], "correct": 3, "explanation": "Untreated glaucoma ends in irreversible blindness (IV, option D). Late-stage irreversible outcome = blindness."}'),
  ('64c69521-3t','{"options": ["III", "II", "I", "IV"], "correct": 2, "explanation": "A slippery floor (fall risk) is a physical (I, option C) hazard. Slip/fall = physical hazard."}'),
  ('3625c84c-3a','{"options": ["II", "I", "IV", "III"], "correct": 0, "explanation": "An alkaline (caustic) substance is a chemical (II, option A) hazard. Caustic substance = chemical hazard."}'),
  ('535a1f10-43','{"options": ["IV", "I", "II", "III"], "correct": 3, "explanation": "A bacterium like Pseudomonas is a biological (III, option D) hazard. Microorganism = biological hazard."}'),
  ('77739903-42','{"options": ["IV", "II", "III", "I"], "correct": 0, "explanation": "UV exposure is a radiation (IV, option A) hazard. UV rays = radiation hazard."}'),
  ('091a27a2-3u','{"options": ["II", "IV", "I", "III"], "correct": 3, "explanation": "Pathogenic infection is the domain of biological (III, option D) hazards. Pathogens/infection = biological hazard."}'),
  ('7d6b3e8b-66','{"options": ["I", "IV", "II", "III"], "correct": 0, "explanation": "Anencephaly (I, option A), absence of the brain/cranial vault, is incompatible with survival beyond a few hours. Fatal absent-brain malformation = anencephaly."}'),
  ('dccb286f-7a','{"options": ["II", "I", "III", "IV"], "correct": 0, "explanation": "Oxycephaly (turricephaly, tower skull) (II, option A) results from premature fusion of the coronal (and lambdoid) sutures, forcing upward growth. VERIFY: suture-specific descriptions vary between craniosynostosis types; oxycephaly is the tower-skull form. Premature coronal/lambdoid fusion, tower skull = oxycephaly."}'),
  ('7617af65-6w','{"options": ["III", "II", "I", "IV"], "correct": 3, "explanation": "Crouzon''s disease (IV, option D) features midface hypoplasia, a beaked/parrot nose, shallow orbits (proptosis), and dental crowding. Midface hypoplasia, beaked nose, proptosis = Crouzon''s."}'),
  ('a9c267ac-5n','{"options": ["III", "II", "IV", "I"], "correct": 0, "explanation": "Apert''s syndrome (III, option A) (acrocephalosyndactyly) shows hypertelorism, proptosis, and prominent strabismus (including vertical). VERIFY: Crouzon''s shares hypertelorism/proptosis, so the two overlap; Apert''s is distinguished by syndactyly and its strabismus pattern. Wide-set proptotic eyes with strabismus (plus syndactyly) = Apert''s."}'),
  ('b08b85a2-3k','{"options": ["IV", "I", "III", "II"], "correct": 3, "explanation": "Oxycephaly (II, option D) is the ''tower skull'' (turricephaly). Tower skull = oxycephaly."}'),
  ('e478f050-4z','{"options": ["III", "II", "I", "IV"], "correct": 3, "explanation": "Molluscum contagiosum (IV, option D), a poxvirus, is a mildly contagious viral skin infection that can affect the lids. Viral lid skin nodules = molluscum contagiosum."}'),
  ('fcbc5ea7-5v','{"options": ["II", "I", "III", "IV"], "correct": 2, "explanation": "A chalazion (III, option C) is a chronic, painless granuloma of a blocked meibomian (or Zeis) gland. Chronic lipogranuloma of a lid gland = chalazion."}'),
  ('cd0c1f1f-5e','{"options": ["IV", "II", "I", "III"], "correct": 1, "explanation": "A hordeolum (stye) (II, option B) is an acute staphylococcal infection of a lid gland. VERIFY: staphylococcal blepharitis is also a staph lid infection, so the answer can be argued; the acute staph lid lump is a hordeolum. Acute staph lid infection = hordeolum."}'),
  ('288574e0-5j','{"options": ["IV", "I", "II", "III"], "correct": 1, "explanation": "Seborrheic blepharitis (I, option B) arises from seborrhea of the lid margin and is often aggravated by secondary staphylococcal infection. Seborrhea-based lid-margin inflammation = blepharitis."}'),
  ('3584688f-4m','{"options": ["IV", "I", "III", "II"], "correct": 3, "explanation": "A hordeolum (stye) (II, option D) is treated with warm compresses and topical antibiotics. Warm compress + topical antibiotic = hordeolum."}'),
  ('abc686e6-3q','{"options": ["I", "III", "II", "IV"], "correct": 0, "explanation": "Primary glaucoma (I, option A) arises on its own, not caused by another ocular disease (unlike secondary glaucoma). Not caused by another disease = primary glaucoma."}'),
  ('b1685ae6-3r','{"options": ["II", "I", "IV", "III"], "correct": 0, "explanation": "Secondary glaucoma (II, option A) is caused by or associated with another ocular condition (for example uveitis, trauma, neovascularization). Caused by another eye disease = secondary glaucoma."}'),
  ('a47c5172-4q','{"options": ["III", "II", "IV", "I"], "correct": 0, "explanation": "Absolute glaucoma (III, option A) is the end-stage, blind, often painful eye from any glaucoma. Blind painful end-stage eye = absolute glaucoma."}'),
  ('5adce2f2-55','{"options": ["III", "I", "II", "IV"], "correct": 3, "explanation": "Congenital (developmental) glaucoma (IV, option D) affects the young and is divided into infantile and juvenile forms. Young-onset developmental glaucoma = congenital."}'),
  ('8a7074bf-4v','{"options": ["I", "II", "III", "IV"], "correct": 0, "explanation": "Primary adult glaucoma (I, option A) splits into chronic simple (open-angle) and narrow (closed) angle types. Adult open + closed angle primary disease = primary glaucoma."}'),
  ('3436cfc6-48','{"options": ["II", "I", "III", "IV"], "correct": 0, "explanation": "The dural sheath (II, option A) of the optic nerve splits at the optic canal (one layer becomes orbital periosteum, the other continues with the nerve). Dural sheath splits at the optic canal."}'),
  ('40abbf05-4a','{"options": ["I", "II", "IV", "III"], "correct": 0, "explanation": "The optic nerve''s meningeal (I, option A) sheaths (dura, arachnoid, pia) are continuous with the meninges of the brain. Optic nerve coverings = the brain''s meninges."}'),
  ('9c61ad2a-4b','{"options": ["III", "IV", "I", "II"], "correct": 0, "explanation": "Tumors (III, option A) can compress the optic nerve and impair vision. Compressive mass = tumor."}'),
  ('5bae847d-4l','{"options": ["IV", "II", "I", "III"], "correct": 0, "explanation": "Compression of the optic nerve causes functional loss (IV, option A) of vision. Nerve compression outcome = functional (visual) loss."}'),
  ('b055b5dc-3j','{"options": ["IV & I", "II & III", "III & IV", "I & II"], "correct": 2, "explanation": "The meningeal and dural sheaths are structures of the optic nerve, whereas tumors and functional loss (III & IV, option C) are a pathology and a consequence, not anatomical parts. Tumor and functional loss = not structures."}'),
  ('23768cf8-42','{"options": ["III", "II", "IV", "I"], "correct": 3, "explanation": "The levator palpebrae elevates the upper eyelid, so a lid (I, option D) injury impairs it. VERIFY: the levator is itself an extraocular muscle, so option II is defensible; as it acts on the eyelid, the lid is the affected structure. Levator raises the lid = lids."}'),
  ('1466b740-4w','{"options": ["III", "IV", "II", "I"], "correct": 2, "explanation": "The extraocular muscles (II, option C) execute saccades, pursuit, and the vestibulo-ocular reflex. Eye movements = extraocular muscles."}'),
  ('8d9f0cb4-4a','{"options": ["II", "III", "IV", "I"], "correct": 1, "explanation": "The pupils (III, option B) are assessed for the direct and consensual light reflexes. Light-reflex testing = pupils."}'),
  ('84e3d7fb-3g','{"options": ["III", "II", "IV", "I"], "correct": 2, "explanation": "Chemosis is edema (swelling) of the conjunctiva (IV, option C). Conjunctival swelling = chemosis (conjunctiva)."}'),
  ('9fbd1488-51','{"options": ["II", "IV", "I", "III"], "correct": 3, "explanation": "Mydriatics dilate the pupil (III, option D) to give a wide view of the fundus. Dilating drops act on the pupil (iris)."}'),
  ('80fcf306-1r','{"options": ["Internal Hordeolum", "External Hordeolum", "Chalazion", "Meibomian Gland Tumors"], "correct": 2, "explanation": "A chalazion is a painless, chronic lipogranuloma from a BLOCKED (not infected) meibomian gland. An internal hordeolum is the acutely infected meibomian gland (Q3); external hordeolum infects Zeis/Moll (Q2). Blockage and painless = chalazion; infection and painful = hordeolum."}'),
  ('b5c41778-29','{"options": ["Internal Hordeolum", "External Hordeolum", "Chalazion", "Meibomian Gland Tumor"], "correct": 1, "explanation": "An external hordeolum (stye) is the painful infection of the gland of Zeis (or Moll) at the lash line. Internal hordeolum infects the meibomian gland (Q3); chalazion is the painless blocked version (Q1). Zeis/Moll = external; meibomian = internal."}'),
  ('6f0e3171-2b','{"options": ["Internal Hordeolum", "External Hordeolum", "Chalazion", "Meibomian Gland Tumors"], "correct": 0, "explanation": "An internal hordeolum is the painful acute infection of a meibomian gland, pointing toward the conjunctival side. External hordeolum infects Zeis/Moll (Q2); chalazion is the painless blocked meibomian gland (Q1). Meibomian infection = internal hordeolum."}'),
  ('2321b566-1q','{"options": ["Trichiasis", "Dichiasis", "Distichiasis", "Monochiasis"], "correct": 2, "explanation": "Distichiasis is an extra (second) row of eyelashes emerging from the meibomian gland orifices. Trichiasis is misdirected normal lashes (Q6); the other terms are distractors. Distichiasis = two rows of lashes."}'),
  ('2c420168-1w','{"options": ["Lacrimal", "Zeis", "Meibomian", "Moll"], "correct": 2, "explanation": "Distichiasis is a second row of lashes emerging from the MEIBOMIAN gland orifices along the posterior lid margin, where oil should be coming out instead of hair. Answer: Meibomian. Separate it from trichiasis, where normally sited lashes simply grow inward. Distichiasis is an extra row in the wrong place; trichiasis is the right row pointing the wrong way. Zeis and Moll sit with the normal anterior lash line, and the lacrimal gland is nowhere near the lid margin."}'),
  ('29887eb9-2m','{"options": ["Trichiasis", "Dichiasis", "Distichiasis", "Monochiasis"], "correct": 0, "explanation": "Trichiasis is the inward misdirection of otherwise normal lashes, which rub and can abrade the cornea. Distichiasis is an extra row (Q4); entropion turns the whole lid in. Misdirected lashes scratching cornea = trichiasis."}'),
  ('cd2a2e7f-2a','{"options": ["Pterygium", "Pinguecula", "Xanthelasma", "Primary Acquired Melanosis"], "correct": 0, "explanation": "A pterygium is a fibrovascular (wing-shaped) growth that extends from the conjunctiva onto the cornea. A pinguecula (Q8 area) stays on the conjunctiva and does not cross the limbus. Onto the cornea = pterygium; stays put = pinguecula."}'),
  ('12ca0bbc-18','{"options": ["Pterygium", "Pinguecula", "Xanthelasma", "Primary Acquired Melanosis"], "correct": 2, "explanation": "Xanthelasma is a yellow lipid deposit (plaque) on or near the eyelids, often medial. Pterygium and pinguecula are conjunctival; PAM is pigmented. Yellow lid plaque = xanthelasma."}'),
  ('f5a55eed-1o','{"options": ["Lacrimal", "Zeis", "Meibomian", "Moll"], "correct": 2, "explanation": "Meibomian gland dysfunction reduces the tear lipid layer, so tears evaporate faster, causing EVAPORATIVE dry eye. The lacrimal gland handles the aqueous layer (Q10). Lipid/meibomian problem = evaporative dry eye."}'),
  ('d1ceb667-1u','{"options": ["Lacrimal", "Zeis", "Meibomian", "Moll"], "correct": 0, "explanation": "The lacrimal gland makes the aqueous layer, so its failure causes AQUEOUS-DEFICIENT dry eye (as in Sjogren''s). Meibomian problems give evaporative dry eye (Q9). Aqueous deficiency = lacrimal gland."}'),
  ('26c4210a-12','{"options": ["Microphthalmos", "Nanophthalmos", "Macrophthalmos", "Buphthalmos"], "correct": 0, "explanation": "Microphthalmos is a small, malformed (disorganized) eye. Nanophthalmos is small but structurally NORMAL (Q14); macro/buphthalmos are enlarged. Small + malformed = micro; small + normal = nano."}'),
  ('a254856f-10','{"options": ["Microphthalmos", "Nanophthalmos", "Macrophthalmos", "Buphthalmos"], "correct": 3, "explanation": "Buphthalmos (''ox eye'') is the enlargement of the globe in all axes from infantile/congenital glaucoma. Macrophthalmos enlarges chiefly axially (Q13). Globe big in all directions = buphthalmos."}'),
  ('a1e3ea5a-1k','{"options": ["Microphthalmos", "Nanophthalmos", "Macrophthalmos", "Buphthalmos"], "correct": 2, "explanation": "Macrophthalmos is enlargement mainly along the anteroposterior (axial) dimension. Buphthalmos enlarges in all axes (Q12). AP/axial enlargement = macrophthalmos."}'),
  ('acb4a416-1j','{"options": ["Microphthalmos", "Nanophthalmos", "Macrophthalmos", "Buphthalmos"], "correct": 1, "explanation": "Nanophthalmos is a small eyeball with otherwise NORMAL internal structures (a pure size reduction). Microphthalmos is small AND malformed (Q11). Small but normal = nanophthalmos."}'),
  ('dd0ead2e-23','{"options": ["Levator Palpebrae Superioris", "Mullen’s Muscle", "Orbicularis Oculi", "Muller’s Muscle"], "correct": 3, "explanation": "PARTIAL ptosis comes from weakness of Muller''s (superior tarsal) muscle, the small sympathetic smooth muscle (as in Horner''s). COMPLETE ptosis is levator (LPS) failure (Q16). Partial droop = Muller''s; complete droop = levator."}'),
  ('d8e7aae6-24','{"options": ["Levator Palpebrae Superioris", "Mullen’s Muscle", "Orbicularis Oculi", "Muller’s Muscle"], "correct": 0, "explanation": "COMPLETE ptosis results from weakness/palsy of the levator palpebrae superioris, the main lid elevator. Muller''s muscle only lifts a few millimeters (Q15 partial). Full droop = levator (LPS)."}'),
  ('69ce4ead-1i','{"options": ["CN2", "CN3", "CN7", "SNS"], "correct": 1, "explanation": "The levator palpebrae superioris is supplied by cranial nerve III (oculomotor), so a complete CN III palsy gives complete ptosis. Answer: CN3. Muller''s muscle is the sympathetic one, which is why Horner''s gives only a partial 2 mm ptosis rather than a full lid drop. That contrast is the usual exam hook: complete ptosis is CN III, partial ptosis is sympathetic."}'),
  ('847908f5-1e','{"options": ["Blepharospasm", "Enophthalmos", "Blepharoptosis", "Proptosis"], "correct": 2, "explanation": "Blepharoptosis (ptosis) is the medical term for a drooping upper eyelid. Blepharospasm is forced lid closure, enophthalmos is a sunken globe, proptosis is a forward-bulging globe. Drooping lid = blepharoptosis."}'),
  ('6f35a1d5-1b','{"options": ["Blepharospasm", "Enophthalmos", "Blepharoptosis", "Proptosis"], "correct": 3, "explanation": "Proptosis (exophthalmos) is the forward protrusion of the globe, classically seen in Graves'' (thyroid) eye disease. Enophthalmos is the opposite (sunken). Graves = bulging eyes (proptosis)."}'),
  ('c09e3670-1a','{"options": ["Blepharospasm", "Enophthalmos", "Blepharoptosis", "Proptosis"], "correct": 1, "explanation": "Enophthalmos (a sunken globe) commonly follows orbital wall fractures (the orbital volume enlarges or contents prolapse, as in a blowout fracture). Proptosis is forward protrusion. Orbital fracture = enophthalmos."}'),
  ('e2631a67-1g','{"options": ["Exophthalmos", "Enophthalmos", "Ectropion", "Entropion"], "correct": 3, "explanation": "Entropion is the inward turning of the lid margin (lashes then rub the eye). Ectropion is the outward turning (Q22). En = in; ec = out."}'),
  ('441192ce-1h','{"options": ["Exophthalmos", "Enophthalmos", "Ectropion", "Entropion"], "correct": 2, "explanation": "Ectropion is the outward turning/sagging of the lower lid (causing exposure and tearing). Entropion turns in (Q21). Ectropion = lid everted outward."}'),
  ('cac82601-21','{"options": ["Scleritis", "Anterior Blepharitis", "Posterior Blepharitis", "Episcleritis"], "correct": 1, "explanation": "Anterior blepharitis affects the lash base, giving crusting, collarettes around the lashes, and lid debris (often staphylococcal/seborrheic). Posterior blepharitis is meibomian-based (Q24). Collarettes at the lashes = anterior blepharitis."}'),
  ('47da6251-37','{"options": ["Scleritis", "Anterior Blepharitis", "Posterior Blepharitis", "Episcleritis"], "correct": 2, "explanation": "Posterior blepharitis is meibomian gland disease, with sebum-like secretion from the gland orifices and erythematous lid margins. Anterior blepharitis is lash-based crusting (Q23). Meibomian orifice oil = posterior blepharitis."}'),
  ('625da903-13','{"options": ["Scleritis", "Anterior Blepharitis", "Posterior Blepharitis", "Episcleritis"], "correct": 0, "explanation": "Scleritis is the focal or diffuse inflammation of the sclera (deep, boring pain). Episcleritis is the more superficial, milder inflammation. Deep scleral inflammation = scleritis."}'),
  ('2145da70-2j','{"options": ["Perennial Conjunctivitis", "Seasonal Conjunctivitis", "Vernal Conjunctivitis", "GPC", "Simple allergic conjunctivitis"], "correct": 1, "explanation": "Conjunctivitis that recurs in a particular season (here every winter) is SEASONAL allergic conjunctivitis. Perennial occurs year-round (indoor allergens, Q29); vernal is a chronic spring/warm-season type. Tied to one season = seasonal."}'),
  ('061724c0-29','{"options": ["Perennial Conjunctivitis", "Seasonal Conjunctivitis", "Atopic Keratoconjunctivitis", "Vernal Conjunctivitis", "GPC"], "correct": 4, "explanation": "Allergy to contact-lens wear (and sutures/prostheses) causes giant papillary conjunctivitis (GPC). Perennial and seasonal are environmental allergy; atopic links to eczema (Q28). Contact-lens papillae = GPC."}'),
  ('13787ada-1h','{"options": ["Perennial Conjunctivitis", "Seasonal Conjunctivitis", "Atopic Keratoconjunctivitis", "Vernal Conjunctivitis", "GPC"], "correct": 2, "explanation": "Atopic keratoconjunctivitis is strongly associated (about 95%) with atopic dermatitis (eczema) and asthma. Perennial/seasonal are simple environmental allergy; GPC is mechanical. Eczema link = atopic keratoconjunctivitis."}'),
  ('ae06a65b-29','{"options": ["Perennial Conjunctivitis", "Seasonal Conjunctivitis", "Atopic Keratoconjunctivitis", "Vernal Conjunctivitis", "GPC"], "correct": 0, "explanation": "Symptoms appearing whenever she enters her room point to a year-round indoor allergen (dust, mites), which is PERENNIAL conjunctivitis. Seasonal is tied to one season (Q26). Indoor, all-year = perennial."}'),
  ('5e1b4f63-1j','{"options": ["Perennial Conjunctivitis", "Seasonal Conjunctivitis", "Atopic Keratoconjunctivitis", "Vernal Conjunctivitis", "GPC"], "correct": 3, "explanation": "Vernal keratoconjunctivitis is the classic pink eye with giant ''cobblestone'' papillae on the upper tarsus (spring catarrh). VERIFY: GPC is also literally papillary, so if the key reserves vernal for Q-something else, GPC (option e) is the alternative. Both are papillary diseases."}'),
  ('ffa4b81f-12','{"options": ["Chlamydial Conjunctivitis", "Herpetic Conjunctivitis", "Gonococcal Conjunctivitis", "Adenoviral Conjunctivitis"], "correct": 2, "explanation": "Hyperacute conjunctivitis is caused by Neisseria gonorrhoeae (gonococcal), with explosive onset and copious pus. Chlamydial is more indolent, adenoviral is watery. Hyperacute = gonococcal."}'),
  ('df63379c-1b','{"options": ["Purulent", "Mucopurulent", "Mucoid", "Watery"], "correct": 0, "explanation": "Hyperacute (gonococcal) conjunctivitis produces a copious PURULENT (thick pus) discharge. Viral is watery, allergic is mucoid/stringy. Hyperacute = profuse purulent discharge."}'),
  ('739dc8b8-1h','{"options": ["Hyperacute Conjunctivitis", "Acute Conjunctivitis", "Chronic Conjunctivitis", "Adenoviral Conjunctivitis"], "correct": 3, "explanation": "Adenoviral conjunctivitis is the most common cause of acute (often unilateral first) infectious conjunctivitis. Hyperacute is gonococcal and uncommon. Most common acute red eye = adenoviral (viral)."}'),
  ('a17bdcfc-33','{"options": ["Hyperacute Conjunctivitis", "Acute Conjunctivitis", "Chronic Conjunctivitis", "Adenoviral Conjunctivitis"], "correct": 1, "explanation": "Watery-to-mucoid discharge, photophobia, and engorged vessels describe acute (typically viral) conjunctivitis. VERIFY: this picture is essentially adenoviral, so the key may instead want option d; confirm whether they want the category ''acute'' or the specific ''adenoviral''."}'),
  ('a1f92ef4-1i','{"options": ["Chlamydial Conjunctivitis", "Herpetic Conjunctivitis", "Gonococcal Conjunctivitis", "Adenoviral Conjunctivitis"], "correct": 0, "explanation": "Chlamydia trachomatis is the most common bacterial STD, so chlamydial conjunctivitis is the answer. Gonococcal is the hyperacute STD but less common than chlamydia. Most common bacterial STD = chlamydia."}'),
  ('58237709-17','{"options": ["Cortical cataract", "Nuclear cataract", "Posterior subcapsular cataract", "Christmas tree cataract"], "correct": 3, "explanation": "Christmas tree cataract (polychromatic needle-like crystals) is associated with MYOTONIC DYSTROPHY, not aging, so it is the exception. Cortical, nuclear, and posterior subcapsular are the age-related types. Christmas tree = myotonic dystrophy."}'),
  ('8367fcf8-1m','{"options": ["Pre - Mature Cataract", "Matured Cataract", "Hyper Mature Cataract", "Brunescent Cataract"], "correct": 0, "explanation": "Second sight (a temporary improvement in near vision from index myopia) appears in the early/pre-mature (incipient) nuclear cataract. By the mature/hypermature stages vision is lost. Second sight = early nuclear cataract."}'),
  ('01ce6065-v','{"options": ["Decrease VA", "Decrease contrast sensitivity", "Visual Field Defect", "Disturbed Color Vision"], "correct": 2, "explanation": "A visual FIELD defect is NOT a cataract symptom; cataract gives decreased acuity, reduced contrast sensitivity, glare, and color disturbance. Field defects suggest glaucoma or retinal/neuro disease. Cataract clouds vision globally, it does not carve out field defects."}'),
  ('ab93c309-3g','{"options": ["Nuclear Cataract", "Cortical Cataract", "Posterior Subcapsular Cataract", "Traumatic Cataract"], "correct": 0, "explanation": "A nuclear cataract scatters light and yellows/browns the central lens nucleus (index myopia, central opacity). Cortical is wedge-shaped (Q41), PSC sits behind. Central yellow nucleus = nuclear cataract."}'),
  ('7e9314ca-1h','{"options": ["Hypermaturity", "Pseudo exfoliation (PEX)", "Brunescence", "Vacuoles"], "correct": 2, "explanation": "Brunescence is the brown, opaque coloration of an advanced nuclear cataract (brunescent cataract). Pseudoexfoliation is fibrillar deposits; vacuoles are fluid clefts. Brown nucleus = brunescent."}'),
  ('09f7615f-1q','{"options": ["Nuclear Cataract", "Cortical Cataract", "Posterior Subcapsular Cataract", "Traumatic Cataract"], "correct": 1, "explanation": "Cortical cataract produces cuneiform (wedge/spoke) opacities radiating from the periphery. Nuclear is central (Q39), PSC is posterior plaque. Wedge spokes = cortical."}'),
  ('52c30b19-1b','{"options": ["Electrical Injury", "Blunt Trauma", "Infrared Radiation", "Penetrating Trauma"], "correct": 1, "explanation": "A Vossius ring (a ring of iris pigment imprinted on the anterior lens) results from BLUNT trauma. Penetrating trauma gives capsular tears (Q43). Pigment ring = blunt trauma."}'),
  ('93907291-2d','{"options": ["Electrical Injury", "Blunt Trauma", "Infrared Radiation", "Penetrating Trauma"], "correct": 3, "explanation": "A positive Seidel test (aqueous leak) plus a capsular tear indicates PENETRATING trauma. Blunt trauma gives a Vossius ring (Q42). Open wound, leak, capsular tear = penetrating."}'),
  ('11b801a3-20','{"options": ["Electrical Injury", "Blunt Trauma", "Infrared Radiation", "Penetrating Trauma"], "correct": 2, "explanation": "Glassblower''s cataract is caused by chronic INFRARED radiation (heat) exposure, which damages the anterior capsule. Electrical and trauma causes are separate. Heat/IR = glassblower''s cataract."}'),
  ('f203e2d0-1p','{"options": ["Diabetes Mellitus", "Galactosemia", "Wilson''s Disease", "Myotonic Dystrophy"], "correct": 2, "explanation": "A sunflower cataract (with Kayser-Fleischer rings) is seen in Wilson''s disease from copper deposition. Diabetes/galactosemia give other lens changes; myotonic dystrophy gives the Christmas tree type. Copper, sunflower, Wilson''s go together."}'),
  ('900d37c4-1o','{"options": ["POAG", "PACG", "SOAG", "NTG"], "correct": 0, "explanation": "POAG (chronic simple glaucoma) is the ''compensated'' glaucoma, a slow, tolerated IOP rise. Hint: chronic, quietly compensated over years = POAG."}'),
  ('889cb619-1y','{"options": ["PAOG", "PACG", "SOAG", "NTG"], "correct": 3, "explanation": "NTG (normal-tension glaucoma) is the best fit for ''idiopathic,'' though the stem''s ''congenital/hereditary'' really points to primary CONGENITAL glaucoma, which is not offered, so this item is defective, VERIFY the key. Hint: if congenital glaucoma is not a choice, the idiopathic label lands on NTG."}'),
  ('2f5ca9ca-2r','{"options": ["Bacterial Conjunctivitis", "Allergic Conjunctivitis", "Viral Conjunctivitis", "Giant Papillary Conjunctivitis"], "correct": 1, "explanation": "Bilateral chemosis with clear, watery discharge is allergic conjunctivitis. Bacterial gives purulent discharge, viral is watery but usually with follicles, GPC is mechanical. Itchy, watery, bilateral = allergic."}'),
  ('b0c4596d-25','{"options": ["Bacterial Conjunctivitis", "Allergic Conjunctivitis", "Viral Conjunctivitis", "Giant Papillary Conjunctivitis"], "correct": 3, "explanation": "Giant papillary conjunctivitis (GPC) commonly arises from contact-lens mishandling/overwear (a mechanical-immune reaction). Bacterial/viral/allergic have other triggers. Contact-lens cause = GPC."}'),
  ('d58dd6f7-1u','{"options": ["S. Aureus", "S. Pnuemoniea", "H. Flu", "Pseudomonas Aeruginosa"], "correct": 0, "explanation": "Staphylococcus aureus is the most common cause of bacterial conjunctivitis overall (especially in adults). S. pneumoniae and H. influenzae are commoner in children; Pseudomonas is a contact-lens keratitis organism. Most common = Staph aureus."}'),
  ('0691d528-1q','{"options": ["Hyphema", "Hypopyon", "Hyalosis", "Pannus"], "correct": 1, "explanation": "Hypopyon is layered PUS in the anterior chamber. Hyphema is blood (Q57), hyalosis is a vitreous change, pannus is corneal vascularization. Pus in the AC = hypopyon."}'),
  ('63f435b5-13','{"options": ["IgA", "IgG", "IgM", "IgE"], "correct": 0, "explanation": "IgA (secretory IgA) is the most abundant immunoglobulin on the ocular surface/in tears, the first-line mucosal defense. IgG dominates serum, not the tear film. Ocular surface = IgA."}'),
  ('7f446c0d-2e','{"options": ["Optic Neuropathy", "Optic Atrophy", "Optic Neuritis", "Papilledema"], "correct": 1, "explanation": "Optic atrophy is the death/degeneration of the retinal ganglion cell axons that make up the optic nerve, seen as a pale disc. Optic neuritis is inflammation, papilledema is swelling. Axon death = optic atrophy."}'),
  ('778a7e46-17','{"options": ["munson sign", "abnormal K readings", "below 390 microns Central corneal thickness", "Irregular Astigmatism"], "correct": 2, "explanation": "All listed items occur in keratoconus, so the item is built around the odd value: a central corneal thickness below 390 microns is the soft option here. Munson''s sign, steep/abnormal K, and irregular astigmatism are core signs. VERIFY: keratoconus does thin the cornea, so confirm which figure the key treats as ''not a sign''."}'),
  ('3ca7f07c-1x','{"options": ["Anterior Uveitis", "Posterior Uveitis", "Intermediate Uveitis", "Pan Uveitis"], "correct": 3, "explanation": "Panuveitis involves all layers of the uvea (anterior, intermediate, and posterior together). The other terms name a single zone. All layers = panuveitis."}'),
  ('c4549d2c-1g','{"options": ["Pinguecula", "Pterygium", "Conjunctival Cyst", "Hordeolum"], "correct": 1, "explanation": "Pterygium is nicknamed ''surfer''s eye'' because UV/wind/dust exposure (as in surfers) drives it. Pinguecula is related but does not cross the cornea. Surfer''s eye = pterygium."}'),
  ('d9de6de0-1s','{"options": ["Hyphema", "Hypopyon", "Hyalosis", "Panus"], "correct": 0, "explanation": "Hyphema is BLOOD in the anterior chamber (often post-trauma). Hypopyon is pus (Q51). Blood in the AC = hyphema."}'),
  ('16ac9580-1m','{"options": ["Between RPE and Photoreceptor cell layer", "Between Choroid and Photoreceptor cell Layer", "Between Sclera and Choroid", "Between Bipolar Cell layer and Photoreceptor cell layer"], "correct": 0, "explanation": "Retinal detachment occurs at the embryologic cleavage plane between the neurosensory retina (photoreceptors) and the RPE. The two layers were never tightly fused. Detachment plane = photoreceptors vs RPE."}'),
  ('fe32a7ec-1d','{"options": ["Retinal Sheen", "Retinal Tigroid Appearance", "Lattice Degeneration", "Retinal Hemorrhage"], "correct": 2, "explanation": "Lattice degeneration is the peripheral retinal thinning (with a lattice/crisscross pattern) that predisposes to tears and detachment. Retinal sheen and tigroid are other appearances. Peripheral thinning lattice = lattice degeneration."}'),
  ('acc3e05c-1b','{"options": ["TRUE", "FALSE"], "correct": 0, "explanation": "TRUE: diabetic retinopathy is classically divided into two stages, non-proliferative (NPDR) and proliferative (PDR). Two stages = correct."}'),
  ('718c6461-26','{"options": ["TRUE", "FALSE"], "correct": 1, "explanation": "FALSE: the defining sign of PROLIFERATIVE diabetic retinopathy is neovascularization (new vessels), not hemorrhage alone. Hemorrhages occur in both stages. Proliferative = new vessels, so the statement is false."}'),
  ('c33681f3-2i','{"options": ["TRUE", "FALSE"], "correct": 1, "explanation": "FALSE as stated: diabetic retinopathy is primarily a vascular/macular disease and is not ''mainly characterized by multiple negative scotomas''."}'),
  ('45fabd61-1x','{"options": ["TRUE", "FALSE"], "correct": 0, "explanation": "TRUE: corticosteroids (topical or systemic) can raise IOP (steroid-response glaucoma) and induce posterior subcapsular cataract. Steroids = pressure up and lens opacity."}'),
  ('69ea5aae-1g','{"options": ["TRUE", "FALSE"], "correct": 0, "explanation": "TRUE: dry AMD is the non-exudative (no leakage/neovascular) form, marked by drusen and atrophy. Wet AMD is exudative with choroidal neovascularization. Dry = non-exudative."}'),
  ('963132bb-1d','{"options": ["GRADE I", "GRADE II", "GRADE III", "GRADE IV"], "correct": 2, "explanation": "VERIFY (image-based): the original item showed a fundus photo to grade. Without the image the grade cannot be read; placeholder is Grade III (typically the grade shown with hard exudates, cotton-wool spots, or a macular star). Match the answer to the actual photo in the source."}'),
  ('32e2e98c-1r','{"options": ["Neuro Syphilis", "Traumatic brain injury", "Ocular trauma", "Myasthenia gravis"], "correct": 0, "explanation": "Argyll Robertson pupil is classically caused by neurosyphilis. ARP = neurosyphilis."}'),
  ('768109ce-1v','{"options": ["Escherichia coli", "treponema pallidum", "streptococcus pneumoniae", "staphylococcus aureus"], "correct": 1, "explanation": "Treponema pallidum is the spirochete of syphilis, the organism behind the Argyll Robertson pupil. The other bacteria are unrelated. Syphilis = Treponema pallidum."}'),
  ('129daeb7-21','{"options": ["Binasal Heternonymous Hemianopsia", "Binasal Heternonymous Hemianopsia", "Bitemporal Homonymous Hemianopsia", "Binasal Homonymous Hemianopsia"], "correct": 2, "explanation": "An optic chiasm lesion gives a BITEMPORAL HETERONYMOUS hemianopsia. VERIFY: the options are corrupted (two are identical and none reads ''bitemporal heteronymous''); the closest is the ''bitemporal'' choice, so confirm against the source."}'),
  ('8c88dee0-1j','{"options": ["Lagophthalmos", "Partial Ptosis", "Constricted pupil", "Anhidrosis"], "correct": 0, "explanation": "Lagophthalmos is NOT a Horner''s sign; Horner''s gives partial ptosis, miosis (constricted pupil), and anhidrosis. The Horner triad excludes lagophthalmos."}'),
  ('797fce1a-2k','{"options": ["Argyll Robertson’s pupil", "Adie’s pupil", "Marcus Gunn pupil", "Horner’s syndrome"], "correct": 2, "explanation": "The swinging flashlight test detects a Marcus Gunn pupil (relative afferent pupillary defect). Swinging light = RAPD/Marcus Gunn."}'),
  ('f35b5969-3o','{"options": ["Facial Nerve", "Oculomotor Nerve", "Acoustic Nerve", "Trigeminal Nerve"], "correct": 0, "explanation": "The facial nerve (CN VII) carries taste from the anterior two-thirds of the tongue (via chorda tympani) and some external-ear sensation. Trigeminal handles general face sensation and tongue touch, not taste. Anterior tongue taste = CN VII."}'),
  ('9987bde2-o','{"options": ["Iridocyclitis", "Iridodenesis", "Cyclodialysis", "Iridodialysis"], "correct": 3, "explanation": "Iridodialysis (a tear of the iris root from the ciliary body) leaves a D-shaped pupil. Iridodonesis is iris tremor, cyclodialysis separates ciliary body from sclera. D-shaped pupil = iridodialysis."}'),
  ('a005ca80-2s','{"options": ["Optic Nerve", "Oculomotor Nerve", "Acoustic Nerve", "Trigeminal Nerve"], "correct": 0, "explanation": "The optic nerve (CN II) is the paired nerve transmitting visual information from the retina to the brain. The others serve eye movement, hearing, and facial sensation. Vision in = optic nerve."}'),
  ('9b2215bd-y','{"options": ["Retinal disease", "Chronic glaucoma", "Papilledema", "Neurological disease"], "correct": 3, "explanation": "Primary optic atrophy follows direct neurological/retrobulbar damage to the nerve WITHOUT preceding disc swelling (the disc is pale with sharp margins). Secondary optic atrophy follows papilledema. Primary = neuro cause, no prior swelling."}'),
  ('69389a4a-23','{"options": ["Optic Chiasm", "Optic Tract", "Lateral Geniculate Body", "Optic Radiation"], "correct": 3, "explanation": "The optic radiation (geniculocalcarine tract) is the central connection carrying fibers from the lateral geniculate body to the occipital (visual) cortex. The chiasm and tract are upstream relays. To the occipital lobe = optic radiation."}'),
  ('07d54845-17','{"options": ["Phagocytosis", "Enucleation", "Leucocoria", "Hard exudates"], "correct": 1, "explanation": "Enucleation is the surgical removal of the entire eyeball from its socket. Leucocoria is a white pupil, phagocytosis is cell eating. Remove the eye = enucleation."}'),
  ('e9b020a6-11','{"options": ["Papilloedema", "Retinoblastoma", "Papillitis", "Retinitis"], "correct": 1, "explanation": "Amaurotic cat''s eye reflex (leukocoria, a white pupil) is the classic sign of retinoblastoma in children. Papilledema and papillitis are disc findings. White cat''s-eye reflex = retinoblastoma."}'),
  ('bb47530a-4u','{"options": ["Phagocytosis", "Leucocoria", "Hard exudates", "Retinitis proliferans"], "correct": 3, "explanation": "Retinitis proliferans is the proliferative response with new vessels and fibrous tissue over the retina extending into the vitreous (as in advanced diabetic retinopathy). Hard exudates and leukocoria are different findings. Fibrovascular proliferation = retinitis proliferans."}'),
  ('347f406d-s','{"options": ["Central retinal vein occlusion", "Dystrophies of retinal rods", "Dystrophies of the retinal cones", "Retinal detachment"], "correct": 1, "explanation": "Night blindness (nyctalopia) comes from dysfunction/dystrophy of the retinal RODS, the dim-light photoreceptors (as in retinitis pigmentosa, vitamin A deficiency). Cones serve day/color vision. Night vision = rods."}'),
  ('2546da3a-2d','{"options": ["Hard exudates", "Phagocytosis", "Cryotherapy", "Photocoagulation"], "correct": 3, "explanation": "Photocoagulation uses heat (laser) to coagulate blood and tissue from fluid to a clotted state, sealing vessels/tears. Cryotherapy uses cold, not heat. Heat clotting = photocoagulation."}'),
  ('87557025-1h','{"options": ["Hyaloid capsular ligament of Weigert", "Vitreous base", "Hyalocytes", "Space of Berger"], "correct": 3, "explanation": "The space of Berger (retrolental space) is the potential space between the lens and the anterior hyaloid face. Weigert''s ligament is the annular attachment around it; the vitreous base is peripheral. Behind the lens = space of Berger."}'),
  ('5448d9f7-24','{"options": ["Photopsia", "Positive scotoma", "Visual impairment", "Vitreous liquefaction"], "correct": 1, "explanation": "Floaters are shadows cast on the retina by vitreous opacities, perceived as a positive scotoma (the patient sees a spot). Photopsia is flashes, not shadows. Seeing a floating spot = positive scotoma."}'),
  ('1dd0f234-3x','{"options": ["Persistent Hyperplastic Primary Vitreous", "Vitreous liquefaction", "Vitreous Opacity", "Vitreous Band"], "correct": 0, "explanation": "Persistent hyperplastic primary vitreous (PHPV) is the failure of the embryonic hyaloid vasculature to regress, giving leukocoria in a small (microphthalmic) eye. It is a differential for retinoblastoma. Unregressed hyaloid system = PHPV."}'),
  ('5319a768-2c','{"options": ["Vitreous hemorrhage", "Synchisis scintillans", "Retinoblastoma", "Asteroid hyalosis"], "correct": 3, "explanation": "Asteroid hyalosis is vitreous opacity from calcium soaps (calcium-lipid spheres) suspended in the gel, usually unilateral and visually harmless. Synchysis scintillans is cholesterol crystals. Calcium soaps = asteroid hyalosis."}'),
  ('4c27f30e-4n','{"options": ["Non proliferative diabetic retinopathy", "Cystoid macular edema", "Vitreous hemorrhage", "Central retinal vein occlusion"], "correct": 2, "explanation": "A long-standing diabetic with sudden floaters and a dim red reflex obscuring the fundus most likely has a vitreous hemorrhage (from proliferative diabetic retinopathy neovessels). NPDR and CME would not blot out the whole fundus view. Sudden floaters + no fundus view in a diabetic = vitreous hemorrhage."}'),
  ('f5aa31a9-5m','{"options": ["Cataract", "Glaucoma", "Conjunctivitis", "Retinintis pigmentosa"], "correct": 1, "explanation": "Glaucoma is the group of diseases with abnormal IOP causing progressive optic nerve damage and irreversible vision loss. Cataract and conjunctivitis are reversible/treatable; RP is a dystrophy. Pressure + optic nerve damage + irreversible = glaucoma."}'),
  ('93b84718-4q','{"options": ["Primary angle closure glaucoma", "Secondary angle closure glaucoma", "Primary open-angle glaucoma", "Secondary open-angle glaucoma"], "correct": 0, "explanation": "Primary angle-closure glaucoma raises IOP because the iris apposes the angle and blocks aqueous from reaching the trabecular meshwork. Open-angle types have an open angle. Iris blocking the angle = angle closure."}'),
  ('0531e7bd-3b','{"options": ["Axenfeld syndrome", "Sturge-Weber syndrome", "Neurofibromatosis", "Marfan’s syndrome"], "correct": 3, "explanation": "Arachnodactyly (long fingers), cardiac anomalies, and lens subluxation (typically up and out) define Marfan''s syndrome (fibrillin defect). Axenfeld and Sturge-Weber are different. Tall, long fingers, dislocated lens = Marfan''s."}'),
  ('8c15e66a-1i','{"options": ["Eyestrain from reading in a darkened room", "Too much pressure on the optic nerve", "Too little pressure on the optic nerve", "Not wearing prescription glasses"], "correct": 1, "explanation": "In most glaucoma, excessive intraocular pressure damages the optic nerve (mechanical and vascular insult at the disc). Reading habits and glasses do not cause it. Glaucoma damage = too much pressure on the nerve."}'),
  ('ee220ad1-23','{"options": ["Tonometry", "Ophthalmoscopy", "Aqueous humour", "Intraocular pressure"], "correct": 0, "explanation": "Tonometry is the procedure of quantitatively measuring intraocular pressure with a tonometer. Ophthalmoscopy views the fundus; aqueous humor and IOP are the things measured, not the method. Measuring IOP = tonometry."}'),
  ('2df97adb-6i','{"options": ["Lens", "Cataract", "Aphakia", "Central dark interval"], "correct": 0, "explanation": "As the primary lens fibers fill the lens vesicle they form the central region of the lens (the embryonic nucleus). Among these options ''Lens'' is the structure formed; cataract/aphakia are pathologic. VERIFY: the precise textbook term is ''embryonic nucleus'', which is not offered, so confirm the intended answer."}'),
  ('42792c4e-1c','{"options": ["Aphakia", "Second sight", "Lens coloboma", "Opacity in the lens"], "correct": 3, "explanation": "The principal OBJECTIVE sign of cataract is a visible opacity in the lens (seen on exam). Second sight is a symptom; aphakia is absence of the lens. The sign you see = lens opacity."}'),
  ('8ea71f50-22','{"options": ["Lenticular myopia", "Second sight", "Aphakia", "Lens coloboma"], "correct": 0, "explanation": "A change in the lens refractive index from cataract produces lenticular (index) myopia, the basis of ''second sight''. Aphakia is absence of the lens, not a refractive shift. Index change = lenticular myopia."}'),
  ('df7d2bd7-2u','{"options": ["Calcium", "Contraceptive drugs", "Rubella", "Hypoparathyroidism"], "correct": 1, "explanation": "Maternal drug ingestion can cause embryopathy with cataract, the stem citing thalidomide as the prominent example, so the drug category (here ''contraceptive drugs'' as the listed drug option) is the answer. Rubella is an infection, not a drug. VERIFY: the option wording is awkward, so confirm the key, but thalidomide marks this as the drug-related cause."}'),
  ('b7152650-2g','{"options": ["Senile cataract", "Nuclear cataract", "Anterior axial embryonal cataract", "Lens coloboma"], "correct": 2, "explanation": "Anterior axial embryonal cataract shows multiple fine opacities with a faint halo at the embryonal (Y) suture, near the lens center. Senile and nuclear cataracts have other patterns. Fine opacities at the embryonal suture = anterior axial embryonal cataract."}'),
  ('54a4465d-2t','{"options": ["Choroid", "Uvea", "Pupil", "Iris"], "correct": 1, "explanation": "The uvea is the pigmented, vascular middle coat (iris + ciliary body + choroid) extending from the optic disc to the pupil. The choroid alone is only the posterior part. Whole middle vascular coat = uvea."}'),
  ('2742c819-1m','{"options": ["Panophthalmitis", "Choroideremia", "Coloboma", "Aniridia"], "correct": 3, "explanation": "Aniridia is the hereditary absence (hypoplasia) of the iris. Coloboma is a notch/gap, choroideremia is a choroidal dystrophy. No iris = aniridia."}'),
  ('c1af59be-17','{"options": ["Epithelium of ciliary body", "Posterior surface of iris", "Pars plana", "Coloboma"], "correct": 0, "explanation": "Aqueous humor is formed by the epithelium of the ciliary body (the ciliary processes), mainly by active secretion. The iris and pars plana do not produce it. Aqueous source = ciliary body epithelium."}'),
  ('f4784765-69','{"options": ["Panophthalmitis", "Choroideremia", "Coloboma", "Aniridia"], "correct": 1, "explanation": "Choroideremia is the X-linked recessive dystrophy with progressive degeneration of the choriocapillaris, RPE, and retina, leading to blindness in males. Aniridia and coloboma are structural, not degenerative. X-linked choroidal/RPE degeneration = choroideremia."}'),
  ('74fae338-4u','{"options": ["Arlt''s triangle", "Diffuse endothelial spread", "Krukenerg''s Spindle", "Punctate Epithelial Keratitis"], "correct": 0, "explanation": "Keratic precipitates classically deposit in a lower triangular pattern called Arlt''s triangle (gravity-dependent on the inferior corneal endothelium) in anterior uveitis. Krukenberg''s spindle is a vertical pigment deposit. KPs in uveitis = Arlt''s triangle."}'),
  ('7ecb5a23-2s','{"options": ["Tapetoretinal Degeneration", "Rod- Cone Dystrophy", "Acute Retinal Pigment Epithelitis", "Drusen"], "correct": 0, "explanation": "(Repeat of Q1) TAPETORETINAL DEGENERATION — the umbrella term for hereditary ''layer'' (RPE/photoreceptor) dystrophies whose primary site varies. Hereditary retinal-layer degeneration = tapetoretinal."}'),
  ('9461158e-3c','{"options": ["Fundus Flavimaculatus", "Fundus Albipunctatus", "Drusen", "Retinopathy"], "correct": 0, "explanation": "(Repeat of Q2) FUNDUS FLAVIMACULATUS — yellow-white pisciform flecks of the posterior pole (Stargardt-related). Yellow flecks posterior pole = fundus flavimaculatus."}'),
  ('d61a1e1d-3r','{"options": ["Venous dilation", "Retinal neovascularization", "Vascular pulsation", "Hemorrhage"], "correct": 1, "explanation": "RETINAL NEOVASCULARIZATION requires a diseased/ischemic retina plus a disturbed vascular bed, with new vessels arising predominantly from the VENOUS side — the hallmark of proliferative diabetic/ischemic retinopathy. Dilation/pulsation/hemorrhage are other vascular signs. Ischemia-driven new vessels = neovascularization."}'),
  ('886e495b-2q','{"options": ["Fibrosis of the retina and choroid", "Cotton wool patches", "Phakomatoses", "Hemorrhage"], "correct": 1, "explanation": "COTTON-WOOL spots/patches appear as indistinct, fluffy WHITE retinal opacities with hazy irregular margins — they are nerve-fiber-layer microinfarcts (axoplasmic stasis) seen in hypertension, diabetes, vasculitis. Sharp lesions/fibrosis/hemorrhage differ. Fluffy white NFL infarct = cotton-wool spot."}'),
  ('68109732-3u','{"options": ["Axenfeld syndrome", "Sturge-Weber syndrome", "Neurofibromatosis", "Marfan’s syndrome"], "correct": 3, "explanation": "MARFAN''S syndrome: arachnodactyly (long fingers), cardiac/aortic anomalies, and superior LENS SUBLUXATION (ectopia lentis), with angle/meshwork anomalies resembling infantile glaucoma — a fibrillin (FBN1) connective-tissue disorder. Axenfeld/Sturge-Weber/NF differ. Tall, long fingers + up-dislocated lens = Marfan."}'),
  ('073a81ca-4p','{"options": ["Retinal Dysplasia", "Myelinated Nerve Fibers", "Melanosis of the Retina", "Retinopathy of Prematurity"], "correct": 2, "explanation": "(Repeat of Q6) MELANOSIS OF THE RETINA — benign scattered grayish-black pigment spots, nonprogressive. Benign scattered pigment = retinal melanosis."}'),
  ('18abe407-31','{"options": ["Drusen", "Vitelliruptive degeneration", "Liber Congenital Amaurosis", "Fundus flavimaculatus"], "correct": 1, "explanation": "VITELLIRUPTIVE (Best vitelliform) degeneration — autosomal DOMINANT, onset at/near birth — shows the classic ''egg-yolk'' (sunny-side-up) macular lesion that later ''scrambles.'' Leber congenital amaurosis is AR blindness; drusen/flavimaculatus differ. Egg-yolk macula = Best disease (vitelliform)."}'),
  ('b00cd30d-34','{"options": ["Ataxia telagiectasias", "Angiomatosis Retinae", "Tuberous Sclerosis", "Ophthalmic bunch"], "correct": 0, "explanation": "ATAXIA-TELANGIECTASIA (Louis-Bar): autosomal recessive cerebellar ataxia, nystagmus, and conjunctival/skin telangiectasias (plus immunodeficiency). Angiomatosis retinae (von Hippel-Lindau) and tuberous sclerosis are other phakomatoses. Ataxia + conjunctival telangiectasia = A-T."}'),
  ('c62161c2-25','{"options": ["Perimetry", "Ophthalmoscopy", "Electroretinography", "Electro-oculography"], "correct": 2, "explanation": "Electroretinography (ERG) records the retina''s action potentials evoked by light. Electro-oculography (EOG) measures the resting RPE potential. Hint: ERG = Retina''s electrical response to light."}'),
  ('6bb8a837-34','{"options": ["Choriocapillaris", "Central retinal artery", "Cone and rod", "Sensory retina"], "correct": 0, "explanation": "The choriocapillaris (innermost choroid) nourishes the RPE and the outer sensory retina (photoreceptors). The central retinal artery feeds the INNER retina. Hint: outer retina/RPE fed by the choroid (choriocapillaris); inner retina fed by the retinal artery."}'),
  ('d5052ad0-2q','{"options": ["Disorder of foveal", "Visual Disturbance", "Night blindness", "Illumination"], "correct": 1, "explanation": "(Repeat of Q11) VISUAL DISTURBANCE = an abnormal change in vision not consistent with healthy eyes. Abnormal vision change = visual disturbance."}'),
  ('4a72b92e-7r','{"options": ["Vascular pulsation", "Venous dilation", "Neovascularization", "Subretinal neovacular membranes"], "correct": 2, "explanation": "Subretinal/choroidal NEOVASCULARIZATION = new vessels from the CHORIOCAPILLARIS growing through Bruch''s membrane between Bruch''s/RPE and then RPE/sensory retina — the mechanism of wet AMD (CNV). Pulsation/dilation are venous signs. Vessels breaching Bruch''s = (choroidal) neovascularization."}'),
  ('ecdde6b8-3a','{"options": ["Vascular pulsation", "Venous dilation", "Neovascularization", "Hemorrhage"], "correct": 1, "explanation": "[Stem says ''dilated veins'' → venous dilation.] Increased venous pressure, very low IOP, or hyperviscosity cause VENOUS DILATION (engorged retinal veins) — seen in CRVO/hyperviscosity syndromes. The source keys ''vascular pulsation''; the described outcome (''dilated veins'') is venous DILATION — verify. Engorged veins = venous dilation."}'),
  ('de5ad2bd-47','{"options": ["Myelinated nerve fibers", "Retinal dysplasia", "Melanosis of retina", "Coat disease"], "correct": 1, "explanation": "[Wording overlaps Q6/Q42.] Scattered grayish-black fundus spots (nonprogressive) describe a benign pigmentary anomaly; the source keys ''retinal dysplasia'' here, though the same description elsewhere is keyed ''melanosis of the retina'' — note the inconsistency. Scattered benign pigment = melanosis (verify vs dysplasia)."}'),
  ('79f2558a-2o','{"options": ["Retinal phlebitis", "Easles disease", "Retinal vasculitis", "Retinal edema"], "correct": 1, "explanation": "EALES disease (''Easles'') = an idiopathic peripheral PERIPHLEBITIS (retinal vasculitis) in young MEN (15-30 yr), causing recurrent vitreous hemorrhage from peripheral neovascularization. Retinal phlebitis/vasculitis/edema are descriptors; the named entity = Eales. Young male + peripheral periphlebitis = Eales."}'),
  ('25552d29-42','{"options": ["Leber congenital amaurosis", "Retinal pigment epithleium", "Retinitis pigmentosa", "Fundus albipunctatus"], "correct": 0, "explanation": "(Repeat of Q16) LEBER CONGENITAL AMAUROSIS — AR, consanguineous, no/near-no light perception from birth (flat ERG). Blind from birth AR = LCA."}'),
  ('0b27fc55-1w','{"options": ["Fundus photography", "OCT", "Fluorescein angiography", "Visual field testing"], "correct": 1, "explanation": "OPTICAL COHERENCE TOMOGRAPHY (OCT) provides CROSS-SECTIONAL (tomographic) views of the retinal layers (and macula/optic nerve). Fundus photo = en-face image; FA = vascular dye study; VF = function. Cross-section of retina = OCT."}'),
  ('c05a105b-1h','{"options": ["Hypertension", "Diabetes", "Hyperlipidemia", "Myopia"], "correct": 3, "explanation": "NOT a risk factor for retinal VEIN occlusion = answer. RVO risk = hypertension, diabetes, hyperlipidemia, hyperviscosity, glaucoma (vascular/atherosclerotic factors). MYOPIA is not a recognized RVO risk — the exception. RVO = vascular risk factors, not myopia."}'),
  ('d79a32f0-1q','{"options": ["Vitreous hemorrhage", "Retinitis Pigmentosa", "Macular edema", "Retinoschisis"], "correct": 2, "explanation": "FLUORESCEIN ANGIOGRAPHY best evaluates MACULAR EDEMA / vascular leakage (and CNV, ischemia) by showing dye leakage/pooling. Vitreous hemorrhage obscures the view; RP/retinoschisis are structural. Leakage/edema imaging = FA (or OCT)."}'),
  ('25f7ace4-28','{"options": ["Cotton wool spots", "Cherry red spot", "Flame hemorrhages", "Drusen"], "correct": 1, "explanation": "Central retinal ARTERY occlusion (CRAO) shows a pale, edematous retina with a CHERRY-RED SPOT at the fovea (the thin fovea reveals the intact choroidal red against the opaque ischemic retina) — an ophthalmic emergency. Cotton-wool/flame hemorrhages/drusen differ. CRAO = cherry-red spot."}'),
  ('f9624ada-1s','{"options": ["Neovascularization", "Macular edema", "Retinal detachment", "Vitreous hemorrhage"], "correct": 1, "explanation": "The leading cause of vision loss in diabetic retinopathy is DIABETIC MACULAR EDEMA (DME) — fluid at the macula impairs central acuity in both NPDR and PDR (the most common cause of moderate vision loss). Neovascularization/hemorrhage/detachment cause severe loss but DME is the leading cause overall. DR vision loss = macular edema."}'),
  ('27540385-4f','{"options": ["Sarcoidosis", "Ophthalmomyiasis", "Metozoan disease", "Protozoan disease"], "correct": 0, "explanation": "SARCOIDOSIS = a chronic multisystem granulomatous disorder of unknown cause with hilar lymphadenopathy, pulmonary infiltrates, skin and OCULAR lesions (uveitis, granulomas). Non-caseating granulomas; ACE elevated. Multisystem granulomas + hilar nodes + uveitis = sarcoid."}'),
  ('2628bddb-19','{"options": ["Inflammation", "Infection", "Immunity", "Hypersensitivity"], "correct": 0, "explanation": "INFLAMMATION is the reaction of living (vascularized) tissue TO injury — the protective vascular/cellular response (redness, heat, swelling, pain, loss of function). INFECTION is invasion by microorganisms (one cause of inflammation, not the definition). [Source keyed ''infection''; corrected to inflammation.] Tissue response to injury = inflammation."}'),
  ('efa33d11-15','{"options": ["Central retinal artery", "Choroidal circulation", "Ophthalmic vein", "Vortex veins"], "correct": 1, "explanation": "The OUTER retina (RPE + photoreceptors) is supplied by the CHOROIDAL circulation (choriocapillaris); the inner 2/3 by the central retinal artery. Ophthalmic vein/vortex veins are venous drainage. Outer retina blood supply = choroid."}'),
  ('54c6e0df-2g','{"options": ["Immunoglobulin A (IgA)", "Immunoglobulin M (IgM)", "Immunoglobulin E (IgE)", "Immunoglobulin D (IgD)"], "correct": 1, "explanation": "IgM is the LARGEST immunoglobulin (a pentamer, ''macroglobulin'') and stays largely CONFINED to the bloodstream (intravascular); it''s the first antibody in a primary response. IgA = secretions; IgE = allergy; IgD = surface. Largest, intravascular = IgM."}'),
  ('7ea8379f-45','{"options": ["Anaphylactic hypersensitivity (type I or immediate type of hypersensitive)", "Antibody –complement dependent reaction (type II)", "Delayed hypersensitivity T cell- mediated, cellular hypersensitivity (type IV)", "Immune complex disease (type III)"], "correct": 3, "explanation": "Antigen-antibody (immune) complexes depositing in vessel walls/connective tissue = TYPE III (immune-complex) hypersensitivity (e.g., serum sickness, lupus, some vasculitides) — complement activation and neutrophil-mediated damage. Type I = IgE/anaphylaxis; II = cytotoxic; IV = delayed T-cell. Deposited complexes = Type III."}'),
  ('fb1f5da9-29','{"options": ["Keratoconus", "Keratomalacia", "Staphyloma", "Limbal nodules"], "correct": 2, "explanation": "A localized bulging of the cornea/sclera lined by uveal tissue (often with raised IOP) = STAPHYLOMA. Keratoconus is a non-inflammatory ectasia (cone), keratomalacia is melting (Vit A deficiency); staphyloma is the glaucoma-associated bulge. Bulging cornea + glaucoma = staphyloma."}'),
  ('31883d2d-3h','{"options": ["Endothelial (Fuch’s) dystrophy", "Familial dystrophy", "Keratoconus", "Keratomalacia"], "correct": 1, "explanation": "Hereditary, BILATERAL stromal corneal deposits in granular, macular, or LATTICE patterns = the classic stromal (familial/granular-macular-lattice) DYSTROPHIES. Fuchs is endothelial; keratoconus is ectasia; keratomalacia is melting. Granular/macular/lattice stromal deposits = stromal corneal dystrophy."}'),
  ('4a93e62b-1v','{"options": ["Endothelial dystrophy", "Sclerocornea", "Mucopolysaccharidosis", "Droplet keratopathy"], "correct": 3, "explanation": "EXCEPT (does NOT cause neonatal corneal opacity). Endothelial dystrophy (CHED), sclerocornea, and mucopolysaccharidoses cause congenital cloudy corneas (STUMPED differential). DROPLET (climatic/spheroidal) KERATOPATHY is an ACQUIRED, age/UV-related degeneration — not a newborn cause. Climatic droplet = the exception."}'),
  ('e22f9d12-3j','{"options": ["Endothelial (Fuch’s) dystrophy", "Familial dystrophy", "Keratoconus", "Vitamin B-complex keratitis"], "correct": 3, "explanation": "Marginal opacification + superficial peripheral vascularization + loss of corneal substance from nutritional deficiency = VITAMIN B-COMPLEX (riboflavin) keratitis (peripheral vascularizing keratitis). Fuchs/familial dystrophy/keratoconus aren''t nutritional. Peripheral vascularizing keratitis from deficiency = B-complex keratitis."}'),
  ('4de647f2-1p','{"options": ["Arcus senilis", "Band keratopathy", "Hassal Henle bodies", "Mooren’s ulcer"], "correct": 1, "explanation": "BAND KERATOPATHY = calcific (calcium) degeneration of BOWMAN''S membrane — a horizontal interpalpebral band (chronic uveitis, hypercalcemia, silicone oil). Arcus = lipid; Hassall-Henle = peripheral Descemet bodies; Mooren = ulcer. Calcium at Bowman''s = band keratopathy. (Cf. pharmacology Q44.)"}'),
  ('f6c0d6a9-11','{"options": ["Fungal corneal ulcer", "Tuberculosis", "Sarcoidosis", "Viral ulcer"], "correct": 0, "explanation": "SATELLITE lesions (smaller infiltrates around a main one) with feathery margins are characteristic of FUNGAL corneal ulcers (Fusarium/Aspergillus/Candida) — slow, with hypopyon. Bacterial/viral ulcers lack satellites. Satellite + feathery infiltrate = fungal keratitis."}'),
  ('f3544e92-3c','{"options": ["Arcus senilis", "Band keratopathy", "Hassal Henle bodies", "Senile marginal degeneration"], "correct": 3, "explanation": "SENILE (Terrien''s-type) MARGINAL DEGENERATION = peripheral marginal opacification with superficial vascularization and thinning/loss of corneal substance in older patients. Arcus/band keratopathy/Hassall-Henle differ. Peripheral marginal thinning with vascularization = senile marginal degeneration."}'),
  ('3c2cf6bf-35','{"options": ["Corneal opacity", "Nebula", "Macula", "Leukoma"], "correct": 0, "explanation": "CORNEAL OPACITY = loss of corneal transparency from severe inflammation (ulceration/injury). Graded by density: nebula (faint), macula (moderate), leukoma (dense white scar) — but the general term for the lost transparency is corneal opacity. Loss of clarity = corneal opacity (nebula<macula<leukoma)."}'),
  ('9fd24d10-3j','{"options": ["Phlyctenular keratoconjunctivits", "Padi keratitis", "Idiopathic disciform keratitis", "Superficial punctate keratitis (SPK)"], "correct": 3, "explanation": "SUPERFICIAL PUNCTATE KERATITIS (SPK) = multiple minute epithelial erosions (fluorescein-staining dots) from adenovirus, measles, mumps, trachoma, etc. Phlyctenular/disciform keratitis are different patterns. Diffuse fine staining dots = SPK."}'),
  ('fe0ef8db-2i','{"options": ["Epithelial basement membrane dystrophy", "Corneal hydrops", "Keratoconus", "Recurrent erosion"], "correct": 3, "explanation": "RECURRENT (corneal) EROSION most commonly follows a corneal ABRASION (especially a fingernail/paper cut) — the basement membrane heals poorly, so the epithelium sloughs again (classically on waking). Hydrops/keratoconus/EBMD differ in cause. Post-abrasion repeated breakdown = recurrent erosion."}'),
  ('7c2039ac-33','{"options": ["Corneal Dystrophies", "Epithelial Dystrophies", "Gutter Degeneration", "Keratoconus"], "correct": 1, "explanation": "EPITHELIAL (map-dot-fingerprint / Cogan microcystic) DYSTROPHY = clear dots/microcysts in the corneal epithelium that intermittently rupture and stain (and cause recurrent erosions). Stromal dystrophies/gutter degeneration/keratoconus differ. Epithelial microcysts = epithelial (EBMD) dystrophy."}'),
  ('2b236910-3o','{"options": ["Venous Dilation", "Retinal Neovascularization", "Vascular Pulsation", "Hematoma"], "correct": 1, "explanation": "(Repeat of Q3) RETINAL NEOVASCULARIZATION — ischemic retina + disturbed vascular bed, new vessels from the venous side. Ischemic new vessels = neovascularization."}'),
  ('8c54b35d-2m','{"options": ["Fibrosis of the Retina and Choroid", "Cotton Wool Patches", "Phakomatoses", "Hemorrhage"], "correct": 1, "explanation": "(Repeat of Q4) COTTON-WOOL PATCHES — fluffy white NFL microinfarcts with hazy margins. NFL infarct = cotton-wool spot."}'),
  ('adebb3e8-44','{"options": ["Corneal Dystrophies", "Epithelial Dystrophies", "Gutter Degeneration", "Keratoconus"], "correct": 0, "explanation": "CORNEAL DYSTROPHIES are bilateral, hereditary, often present subtly at birth but manifest in adolescence and progress slowly (granular/lattice/macular, etc.). Epithelial dystrophies are a subset; gutter degeneration/keratoconus differ. Bilateral inherited slowly progressive corneal opacities = corneal dystrophies."}'),
  ('01c69a0f-12','{"options": ["Keratitis", "Conjunctivitis", "Retinitis", "Uveitis"], "correct": 0, "explanation": "KERATITIS = inflammation of the CORNEA. Conjunctivitis (conjunctiva), retinitis (retina), uveitis (uveal tract) are other -itises. Cornea inflammation = keratitis."}'),
  ('b919bfd9-3w','{"options": ["Gutter degeneration", "Keratoconus", "Spheroid keratitis", "Verucca"], "correct": 0, "explanation": "GUTTER (Terrien''s marginal) DEGENERATION = peripheral corneal stromal THINNING that begins SUPERIORLY and spreads circumferentially (a gutter/furrow), usually with intact epithelium. Keratoconus thins centrally/inferiorly. Superior peripheral thinning gutter = gutter degeneration."}'),
  ('231cd17b-2i','{"options": ["Cornea", "Sclera", "Pupil", "Conjunctiva"], "correct": 0, "explanation": "The CORNEA is the transparent, AVASCULAR anterior 1/6 of the globe''s outer coat (continuous with the sclera at the limbus) and the eye''s main refracting surface. Sclera = posterior 5/6; pupil/conjunctiva differ. Clear anterior 1/6 = cornea."}'),
  ('a59f50b3-31','{"options": ["Optic nerve coloboma", "Optic nerve hypoplasia", "Leber’s amaurosis", "Morning Glory Disc"], "correct": 1, "explanation": "OPTIC NERVE HYPOPLASIA = underdevelopment of the optic nerve (small disc, double-ring sign), often with midline/pituitary defects → HORMONAL abnormalities (septo-optic dysplasia/de Morsier). Coloboma/morning-glory/LCA differ. Small nerve + endocrine issues = optic nerve hypoplasia."}'),
  ('a4b76e0c-1t','{"options": ["Congenital cataract", "Sclerocornea", "Axenfeld-Rieger anomaly", "Coloboma"], "correct": 2, "explanation": "AXENFELD-RIEGER anomaly is part of the ANTERIOR SEGMENT DYSGENESIS spectrum (posterior embryotoxon, iris strands/adhesions, angle anomaly → glaucoma risk). Congenital cataract/coloboma/sclerocornea are separate congenital anomalies. Anterior-segment dysgenesis = Axenfeld-Rieger (and Peters)."}'),
  ('98944b9a-3i','{"options": ["CHARGE syndrome", "Axenfeld-Rieger", "Marfan syndrome", "Stickler syndrome"], "correct": 3, "explanation": "STICKLER syndrome (collagen 2/11 defect): high myopia, vitreoretinal degeneration with RETINAL DETACHMENT, plus midface/skeletal abnormalities and hearing loss. CHARGE/Axenfeld/Marfan differ. High myopia + RD + facial/skeletal = Stickler."}'),
  ('2cd42d0a-3e','{"options": ["Megalocornea", "Microphthalmia", "Congenital glaucoma (buphthalmos)", "Sclerocornea"], "correct": 2, "explanation": "Bilateral large, CLOUDY corneas with high IOP FROM BIRTH = CONGENITAL (infantile) GLAUCOMA with BUPHTHALMOS (enlarged eye, corneal edema, Haab striae). Megalocornea has clear corneas/normal IOP; sclerocornea/microphthalmia differ. Cloudy big cornea + high IOP at birth = congenital glaucoma."}'),
  ('498b620f-37','{"options": ["Peters anomaly", "Axenfeld-Rieger Syndrome", "Stickler syndrome", "Marfan syndrome"], "correct": 1, "explanation": "AXENFELD-RIEGER syndrome = anterior-segment anomalies (posterior embryotoxon, iris adhesions) PLUS systemic DENTAL (microdontia) and CRANIOFACIAL/umbilical features. Peters (central opacity), Stickler, Marfan differ. Anterior segment + dental/facial = Axenfeld-Rieger."}'),
  ('e8897ddd-2a','{"options": ["Microphthalmia", "Cryptophthalmos", "Anophthalmia", "Coloboma"], "correct": 2, "explanation": "ANOPHTHALMIA = complete ABSENCE of ocular (eye) tissue in the orbit (no globe). Microphthalmia = small eye; cryptophthalmos = skin-covered eye; coloboma = a gap. No eye at all = anophthalmia."}'),
  ('f76679b7-2j','{"options": ["Ankyloblepharon", "Epicanthus", "Eyelid coloboma", "Cryptophthalmos"], "correct": 3, "explanation": "CRYPTOPHTHALMOS = failure of EYELID formation so SKIN runs continuously over the (often malformed) eye — no palpebral fissure. Ankyloblepharon = fused lid margins; eyelid coloboma = a notch; epicanthus = skin fold. Skin over the eye, no lids = cryptophthalmos."}'),
  ('05729621-11','{"options": ["Optic pathway", "Optic disc", "Ganglion cells", "Cranial nerves"], "correct": 0, "explanation": "[Awkward stem.] The structure ''commonly called the optic nerve'' is part of the OPTIC PATHWAY (it is really a CNS tract/the beginning of the visual pathway, not a true peripheral nerve). The source keys ''optic pathway.'' Optic ''nerve'' = part of the optic pathway/tract."}'),
  ('02db9432-2l','{"options": ["Uveitis", "Optic neuritis", "Meningitis", "Sinusitis"], "correct": 2, "explanation": "MENINGITIS = inflammation/swelling of the MENINGES (protective membranes around the brain and spinal cord). Uveitis/optic neuritis/sinusitis are other -itises. Inflamed meninges = meningitis (can threaten vision/CN palsies)."}'),
  ('8cdbe58f-2d','{"options": ["Peters anomaly", "Coloboma", "Congenital glaucoma", "Sclerocornea"], "correct": 0, "explanation": "PETERS ANOMALY = anterior-segment dysgenesis with a CENTRAL CORNEAL OPACITY (defect in posterior cornea/Descemet) and often iris/LENS ADHESIONS to the cornea. Coloboma/congenital glaucoma/sclerocornea differ. Central corneal opacity + lens adhesion = Peters anomaly."}'),
  ('b919b7b7-17','{"options": ["Strabismus", "Coloboma", "Cystine storage disease (Lignac- Fanconi syndrome)", "Congenital glaucoma"], "correct": 1, "explanation": "CHARGE syndrome''s ocular hallmark is COLOBOMA (the ''C'' of CHARGE: Coloboma, Heart defects, Atresia choanae, Retardation, Genital, Ear anomalies). Strabismus/cystinosis/glaucoma aren''t the defining feature. CHARGE → coloboma."}'),
  ('d67dfb40-69','{"options": ["Oculocerebrorenal syndrome", "Renal tubule transport defects", "Cystine storage disease (Lignac- Fanconi syndrome)", "Benign cystinosis"], "correct": 2, "explanation": "Nephropathic (infantile) CYSTINE storage disease = CYSTINOSIS (Lignac-Fanconi syndrome) — widespread L-cystine crystal deposition (kidneys, marrow, CORNEA/conjunctiva, uvea) causing renal Fanconi and corneal crystals. Oculocerebrorenal (Lowe) differs. Cystine crystals everywhere incl. cornea = cystinosis (Lignac-Fanconi)."}'),
  ('5ccd3a36-4a','{"options": ["Alkaptonuria and ochronosis", "Tyrosinemia II (Richner-Hanhart syndrome)", "Cystathionine B-synthase deficiency", "Sulfite oxidase deficiency"], "correct": 2, "explanation": "Impaired methionine→cysteine metabolism from CYSTATHIONINE-β-SYNTHASE deficiency = HOMOCYSTINURIA — marfanoid habitus with INFERIOR (down/in) lens subluxation and thromboembolism risk. [Source keyed alkaptonuria; corrected to cystathionine-β-synthase deficiency (option C).] CBS deficiency = homocystinuria (down-dislocated lens)."}'),
  ('b6a60d25-19','{"options": ["Pseudoesotropia", "Iris heterochromia", "Cloudy lens", "Iris coloboma"], "correct": 0, "explanation": "EPICANTHUS (a medial canthal skin fold) in infants produces PSEUDOESOTROPIA — the fold hides nasal sclera so the eyes LOOK crossed though alignment (corneal reflexes/cover test) is normal. Not true strabismus. Epicanthal fold → pseudoesotropia."}'),
  ('e1ede62c-57','{"options": ["Marfan’s syndrome", "Ehler’s Danlos syndrome", "Osteogenesis imperfecta", "Thalassemia syndrome"], "correct": 2, "explanation": "OSTEOGENESIS IMPERFECTA = defects in type I procollagen → bone fragility, abnormal teeth (dentinogenesis imperfecta), deafness, and BLUE/gray SCLERAE (thin sclera shows the choroid). Marfan/Ehlers-Danlos differ. Brittle bones + blue sclerae = OI."}'),
  ('068aec06-45','{"options": ["Thamus syndrome", "Thalassemia syndrome", "Sickle cell syndrome", "Frontal lobe syndrome"], "correct": 1, "explanation": "THALASSEMIA = inherited impairment of normal hemoglobin chain synthesis (too few alpha or beta chains) → microcytic anemia. Sickle cell is a structural Hb variant; the others are distractors. Reduced globin-chain synthesis = thalassemia."}'),
  ('a4169cd2-1t','{"options": ["Visually significant congenital cataract", "Aniridia", "Sclerocornea", "Retinopathy of prematurity"], "correct": 0, "explanation": "A VISUALLY SIGNIFICANT CONGENITAL CATARACT needs EARLY surgery (within weeks) to PREVENT deprivation AMBLYOPIA during the critical period. Aniridia/sclerocornea/ROP have other timelines. Dense congenital cataract → urgent removal to save vision."}'),
  ('eb5fff00-3b','{"options": ["Down syndrome (trisomy 21)", "Trisomy 13 syndrome (Patau syndrome)", "Turner syndrome (Gonadal dysgenesis)", "Alzheimer’s disease"], "correct": 0, "explanation": "DOWN SYNDROME (trisomy 21) is the most common chromosomal disorder and the most common cause of intellectual disability recognizable AT BIRTH (with Brushfield spots, epicanthus, upslanting fissures, keratoconus risk). Patau/Turner are rarer. Commonest chromosomal disorder = trisomy 21."}'),
  ('a9c581d1-4i','{"options": ["Cat-eye syndrome", "Deletion syndrome (Wolf- Hirschorn)", "Monogenic disorder", "Chromosomal disorder"], "correct": 1, "explanation": "WOLF-HIRSCHHORN (4p deletion) syndrome: profound mental/growth retardation, HYPERTELORISM (wide-set, pseudo-exophthalmos), ptosis, exotropia, epicanthal folds, and iris COLOBOMA (''Greek-warrior-helmet'' facies). Cat-eye syndrome differs. 4p- = Wolf-Hirschhorn."}'),
  ('c1563fd9-1g','{"options": ["Congenital cataract", "Axenfeld-Rieger syndrome", "Epiblepharon", "Microphthalmia"], "correct": 0, "explanation": "CONGENITAL CATARACT is a classic cause of LEUKOCORIA (white pupillary reflex) at birth (along with retinoblastoma, PHPV, ROP, Coats). Axenfeld-Rieger/epiblepharon/microphthalmia don''t give leukocoria. White pupil at birth → think cataract/retinoblastoma first."}'),
  ('beaac58a-27','{"options": ["Surgery", "Topical steroids", "Crigler massage", "Laser punctoplasty"], "correct": 2, "explanation": "Congenital nasolacrimal duct obstruction is initially managed with CRIGLER (lacrimal sac) MASSAGE (digital hydrostatic massage to open the valve of Hasner) — most resolve by ~12 months; probing/surgery if persistent. Steroids/laser aren''t first-line. CNLDO first-line = Crigler massage."}'),
  ('5dcbeeac-2o','{"options": ["Monogene disorder", "Autosomal dominant disorder", "Autosomal recessive", "Monogenic defect"], "correct": 0, "explanation": "The description (''a permanent heritable change in genetic material'') is really the definition of a MUTATION, which none of the options name exactly, so the item is defective. A single-gene (''monogene'') disorder is the closest fit, VERIFY. Hint: a heritable change in the DNA = a mutation; here it maps loosely to a monogenic disorder."}'),
  ('d10256ee-1d','{"options": ["Retina", "Cornea", "Sclera", "Vitreous"], "correct": 1, "explanation": "PETER''S ANOMALY primarily affects the CORNEA (central posterior corneal/Descemet defect → central opacity, ± lens/iris adhesions). Not retina/sclera/vitreous. Peters = central corneal opacity. (Cf. Q62.)"}'),
  ('95c56aa7-32','{"options": ["Peter’s anomaly", "Axenfeld-Rieger syndrome", "Coloboma", "Microcornea"], "correct": 1, "explanation": "Posterior embryotoxon PLUS systemic DENTAL and UMBILICAL anomalies = AXENFELD-RIEGER syndrome (anterior-segment dysgenesis with characteristic systemic features). Peters lacks the dental/umbilical signs. Embryotoxon + dental/umbilical = Axenfeld-Rieger."}'),
  ('d2243fc7-1g','{"options": ["Neuroectoderm", "Surface ectoderm", "Mesoderm", "Neural crest"], "correct": 0, "explanation": "The RETINA arises from NEUROECTODERM — specifically the optic vesicle/cup (inner layer → neural retina, outer → RPE). Surface ectoderm → lens/cornea epithelium; mesoderm/neural crest → other ocular tissues. Retina = neuroectoderm (optic cup)."}'),
  ('1f419307-2w','{"options": ["Primary congenital glaucoma", "Congenital cataract", "Coloboma", "Sclerocornea"], "correct": 0, "explanation": "[Source keys ''coloboma''; the description fits congenital glaucoma.] A newborn with a CLOUDY cornea AND INCREASED corneal DIAMETER classically = PRIMARY CONGENITAL GLAUCOMA (buphthalmos) — raised IOP enlarges/clouds the cornea. Coloboma doesn''t enlarge the cornea — verify; the described findings are congenital glaucoma. Big cloudy cornea = congenital glaucoma."}'),
  ('0fb5a57b-1e','{"options": ["Routine school screening", "Neonatal screening and fundus exam", "Tear film analysis", "Applanation tonometry"], "correct": 1, "explanation": "Congenital ocular anomalies are best caught by NEONATAL SCREENING and FUNDUS/red-reflex examination at birth (e.g., for cataract/retinoblastoma) — not school screening (too late), tear analysis, or tonometry. Newborn red-reflex/fundus screen = congenital anomaly detection."}'),
  ('f4799e5c-1u','{"options": ["Alport Syndrome", "Norrie Disease", "Lowe Syndrome", "Peters Anomaly"], "correct": 2, "explanation": "LOWE (oculocerebrorenal) syndrome: X-linked, with microcornea, CONGENITAL CATARACT, posterior LENTICONUS, plus intellectual disability and renal Fanconi. Alport/Norrie/Peters differ. Cataract + lenticonus + renal/CNS = Lowe syndrome."}'),
  ('15aeeb1d-19','{"options": ["Cataract, ptosis, diplopia", "Proptosis, lid edema, eye pain", "Photophobia, tearing, buphthalmos", "Nystagmus, myopia, anisocoria"], "correct": 2, "explanation": "Congenital glaucoma''s classic TRIAD = PHOTOPHOBIA, TEARING (epiphora), and BLEPHAROSPASM — with buphthalmos/corneal clouding. (The 3 P''s: photophobia, ''pouring'' tears, ...) Not the cataract/proptosis sets. Congenital glaucoma triad = epiphora + photophobia + blepharospasm (+ buphthalmos)."}'),
  ('ccad8f14-1b','{"options": ["Term infants with trauma", "Premature infants with supplemental oxygen", "Infants with congenital cataracts", "Infants with toxoplasmosis"], "correct": 1, "explanation": "RETINOPATHY OF PREMATURITY occurs in PREMATURE/low-birth-weight infants exposed to SUPPLEMENTAL OXYGEN (abnormal peripheral retinal vascularization → neovascularization, possible detachment). Not term infants/cataracts/toxoplasmosis. Preterm + oxygen = ROP."}'),
  ('aa269937-1k','{"options": ["Absence of the retina", "Defect in the embryonic fissure", "Hyperplasia of the sclera", "Overgrowth of ciliary body"], "correct": 1, "explanation": "Ocular COLOBOMA results from failure of the EMBRYONIC (choroidal/optic) FISSURE to close — leaving an inferonasal gap in iris/retina/choroid/optic disc. Not absent retina or scleral overgrowth. Coloboma = unfused embryonic fissure (inferonasal)."}'),
  ('0d1c6990-1r','{"options": ["60 to 65 years old", "18 to 35 years old", "35 to 60 year old", "24 months or younger"], "correct": 1, "explanation": "The 18-35-year (young working-adult) group has the HIGHEST risk for burns (occupational/recreational exposure). Toddlers and older adults have specific but lower overall rates here. Highest burn risk = young working adults (18-35)."}'),
  ('f75fa8a9-47','{"options": ["Epithelium", "Cornea", "Outer coat", "Squamous"], "correct": 1, "explanation": "The CORNEA forms the anterior, transparent 1/6 of the globe and merges peripherally with the sclera at the LIMBUS (corneoscleral junction). Epithelium is a layer; ''outer coat'' is the whole fibrous tunic. Clear anterior 1/6 merging at limbus = cornea. (Cf. Q46.)"}'),
  ('3e2595df-3h','{"options": ["Galactose", "Galactokinase", "Transferace", "Galactosemia"], "correct": 3, "explanation": "GALACTOSEMIA = autosomal recessive impairment of galactose→glucose conversion (galactose-1-phosphate uridyltransferase, or galactokinase) → galactose/galactitol accumulation causing ''oil-droplet'' CATARACTS, hepatomegaly, intellectual disability. [Source keyed ''galactose'' (the sugar); corrected to galactosemia (the disease).] Galactose metabolism defect + infantile cataract = galactosemia."}'),
  ('e7993e47-7l','{"options": ["Ophthalmoscopy", "Exophthalmometry", "Orbitonometry", "Radiological investigation of the orbit"], "correct": 1, "explanation": "EXOPHTHALMOMETRY (Hertel) uses a binocular instrument resting on both lateral orbital margins with angled mirrors to superimpose each eye''s corneal profile on a scale — measuring proptosis (forward eye position). Orbitonometry measures resistance; this profile-on-scale device = exophthalmometer. Proptosis measurement = exophthalmometry."}'),
  ('1896497f-1l','{"options": ["Thyroid eye disease", "Lacrimal gland tumors", "Orbital cellulitis", "Cavernous cellulitis"], "correct": 0, "explanation": "THYROID EYE DISEASE (Graves orbitopathy) is the commonest cause of unilateral (and bilateral) EXOPHTHALMOS/proptosis in adults (EOM/fat expansion). Lacrimal tumors, orbital/cavernous cellulitis are rarer causes. Adult proptosis #1 cause = thyroid eye disease."}'),
  ('3f129c8f-2i','{"options": ["Vision", "Pain", "Redness", "Swelling"], "correct": 0, "explanation": "VISION is the key symptom distinguishing orbital cellulitis (vision usually PRESERVED early) from PANOPHTHALMITIS (intraocular infection → severe vision LOSS). Pain/redness/swelling occur in both. Vision status differentiates orbital cellulitis (spared) vs panophthalmitis (lost)."}'),
  ('05eb4ecf-2n','{"options": ["Proptosis", "Episcleral Space", "Orbit", "Muscle Cone"], "correct": 0, "explanation": "PROPTOSIS (exophthalmos) = forward displacement/protrusion of the eyeball from its normal position (passive, by an orbital space-occupying or inflammatory process). Episcleral space/orbit/muscle cone are anatomic terms. Forward eye protrusion = proptosis."}'),
  ('5a68a70c-81','{"options": ["Scaly blepharitis", "Cicatricial entropion", "Spastic entropion", "Ulcerative blepharitis"], "correct": 3, "explanation": "ULCERATIVE (anterior) BLEPHARITIS = staphylococcal lid-margin infection with hyperemic margins, yellow crusts MATTING the lashes, and bleeding ulcers when crusts/lashes are removed (± madarosis/loss of lashes). Scaly (seborrheic) blepharitis lacks ulcers; entropion is a lid-position problem. Crusted lashes + bleeding ulcers = ulcerative blepharitis."}'),
  ('28278fb7-2h','{"options": ["Will have a chin up head position", "Will benefit from bilateral frontalis suspension procedure", "Is likely to have amblyopia", "Will have a hot compress"], "correct": 0, "explanation": "Severe bilateral congenital MYOGENIC ptosis with POOR levator function makes the child adopt a CHIN-UP head posture (to see beneath the drooping lids) — and risks amblyopia if the pupil is occluded; severe cases need frontalis SUSPENSION (poor levator can''t be resected). The asked feature = chin-up posture. Bilateral severe ptosis + poor levator = chin-up + frontalis sling."}'),
  ('2951fb22-4v','{"options": ["Phthiriasis palpebrarum", "Herpes febrilis", "Herpes zoster ophthalmicus", "Lid vaccina"], "correct": 2, "explanation": "HERPES ZOSTER OPHTHALMICUS = reactivation in the GASSERIAN (trigeminal) ganglion with a unilateral vesicular eruption along the V1 (± V2) dermatome (Hutchinson''s sign = nasociliary involvement, ocular risk). Herpes febrilis (simplex) and phthiriasis differ. Dermatomal V1 vesicles = HZO."}'),
  ('efcc9e17-1d','{"options": ["Aponeurotic", "Neurogenic", "Traumatic", "Myogenic"], "correct": 3, "explanation": "MYOGENIC (simple congenital, levator dysgenesis) ptosis is the MOST COMMON type of congenital ptosis — poor levator development/function (often with lid-lag on downgaze). Aponeurotic = involutional (adult); neurogenic/traumatic differ. Commonest congenital ptosis = myogenic."}'),
  ('f0b75053-1y','{"options": ["Blepharitis", "Hordelum or style", "Keratitis", "Conjunctivitis"], "correct": 1, "explanation": "A staphylococcal infection of the eyelid SEBACEOUS glands (Zeis/meibomian) = HORDEOLUM (stye) — a tender, acute, pus-filled lid nodule. Blepharitis is margin inflammation; chalazion is sterile/chronic. Acute infected lid gland = hordeolum (stye)."}'),
  ('4249ac6c-2b','{"options": ["Meibomian Gland Carcinoma", "Nevus Flammeus", "Millium", "Lagophthalmos"], "correct": 3, "explanation": "LAGOPHTHALMOS = inability to fully close the lids, classically from SEVENTH (facial) nerve palsy (orbicularis paralysis) → exposure keratopathy risk. Not the lid tumors/lesions listed. Can''t close lids (CN VII palsy) = lagophthalmos."}'),
  ('72f0925a-27','{"options": ["Retinal tear", "Retinal detachment", "Vitreous detachment", "Vitreous hemorrhage"], "correct": 2, "explanation": "Vitreous detachment (same as Q1), the vitreous separates from the retina/surrounding tissue. Hint: match Q1, ''vitreous separates'' = vitreous detachment."}'),
  ('d716cc08-2x','{"options": ["Photopsia", "Scotoma", "Impaired vision", "Spasm"], "correct": 0, "explanation": "Photopsia (flashes of light) from mechanical traction of the detaching vitreous tugging the retina. Scotoma is a blind spot, not a flash. Hint: traction on the retina fires it mechanically, so you see flashes = photopsia."}'),
  ('1d3a6584-42','{"options": ["Visual agnosia", "Musca volitantes", "Bullous keratopathy", "Scyntisis synthilian"], "correct": 1, "explanation": "Musca volitantes (''flying flies'') = floaters, moving vitreous opacities from protein aggregates in aging or myopia. Hint: musca = flies; the little drifting specks are floaters."}'),
  ('a8216477-1y','{"options": ["Hysterectomy", "Myomectomy", "Lensectomy", "Vitrectomy"], "correct": 3, "explanation": "Vitrectomy = surgical removal of the vitreous. Hysterectomy/myomectomy are uterine; lensectomy removes the lens. Hint: vitre- (vitreous) + -ectomy (remove)."}'),
  ('5d31dd35-35','{"options": ["Pigment epithelium", "Visual cell layer", "Ganglion cell layer", "Bruch''s membrane"], "correct": 1, "explanation": "The visual cell layer (photoreceptors, rods and cones) captures light and starts the electrical signal (phototransduction). The pigment epithelium supports them; ganglion cells are downstream. Hint: light is CAUGHT by the photoreceptor (visual cell) layer first."}'),
  ('e45c6475-22','{"options": ["Vitreous base", "Zonular fibers", "Ciliary process", "Ligament of Weigert"], "correct": 3, "explanation": "The ligament of Weigert (hyaloideocapsular ligament) attaches the vitreous to the posterior lens capsule. Hint: Weigert = the vitreous-to-lens tether at the back of the lens."}'),
  ('5c1d33f9-4t','{"options": ["Vitreous base", "Zonular fibers", "Ciliary process", "Ligament of Weigert"], "correct": 0, "explanation": "The vitreous base straddles the ora serrata (about 2 mm anterior on the pars plana, 4 mm posterior on the retina) and is the FIRMEST vitreous attachment, which is why tears start there. Hint: vitreous BASE = the strongest anchoring ring at the ora serrata."}'),
  ('5c4ee32e-2g','{"options": ["Photopsia", "Syneresis", "Synchysis", "Nyctalopia"], "correct": 2, "explanation": "Synchysis = liquefaction of the vitreous (gel turns to liquid). Syneresis is the shrinking/collapse of the gel; the two often occur together but ''converts into liquid'' names synchysis. Hint: synCHYSis = the vitreous becomes liquid (chy-/fluid)."}'),
  ('97bb5dac-2e','{"options": ["Hemianopic scotoma", "Peripheral scotoma", "Positive scotoma", "Relative scotoma"], "correct": 2, "explanation": "A positive scotoma, the patient actually SEES the shadow cast by the floating opacity. A negative scotoma is an unnoticed gap. Hint: positive = you perceive it (a seen shadow/spot); negative = a blind area you do not notice."}'),
  ('308f230e-2h','{"options": ["Space of Berger", "Carotid space", "Hyaloid space", "Cloquet’s canal"], "correct": 0, "explanation": "The space of Berger (retrolental space) is the potential space between the lens and the anterior hyaloid membrane. Cloquet''s canal runs through the vitreous. Hint: Berger = behind the lens, in front of the vitreous face."}'),
  ('1b68fcfb-30','{"options": ["Central retinal artery occlusion", "Central retinal vein occlusion", "Arterio-venous crossing changes", "Hypertensive retinopathy"], "correct": 1, "explanation": "Central retinal VEIN occlusion, engorged, tortuous, dark congested veins. Artery occlusion gives a pale, whitened retina instead. Hint: dark, swollen, tortuous veins = venous congestion = CRVO."}'),
  ('9c13e54d-4c','{"options": ["Central retinal artery occlusion", "Central retinal vein occlusion", "Retinitis pigmentosa", "Hypertensive retinopathy"], "correct": 0, "explanation": "Central retinal ARTERY occlusion, constricted arteries, pale disc, and a white (ischemic, edematous) retina (often with a cherry-red spot). Hint: sudden pale/white retina + thread-like arteries = CRAO."}'),
  ('6ce62fa4-4o','{"options": ["Central retinal artery occlusion", "Diabetic retinopathy", "Arteriosclerotic retinopathy", "Hypertensive retinopathy"], "correct": 3, "explanation": "Hypertensive retinopathy, arteriolar narrowing, a ''retinal sheen'' from edema, loss of transparency, and hard exudates (a macular star). Hint: narrowed arterioles + edema + hard exudates in a hypertensive = hypertensive retinopathy."}'),
  ('1efd3333-4v','{"options": ["Central retinal artery occlusion", "Central serous chorio-retinopathy", "Arteriosclerotic retinopathy", "Retinitis pigmentosa"], "correct": 2, "explanation": "Arteriosclerotic retinopathy, lipid/hyaline plaques thicken the vessel wall, producing visible vascular sheathing and copper/silver-wire changes. Hint: sheathed, wire-like, plaque-walled vessels = arteriosclerosis of the retina."}'),
  ('303302b4-61','{"options": ["Central serous chorio-retinopathy", "Diabetic retinopathy", "Arteriosclerotic retinopathy", "Hypertensive retinopathy"], "correct": 0, "explanation": "Central serous chorioretinopathy (CSCR), a focal RPE defect lets choroidal fluid seep under the macula, causing localized macular edema/detachment (classically in young stressed males). Hint: blister of fluid under the macula from an RPE leak = CSCR."}'),
  ('df9abcdf-1t','{"options": ["Capsulectomy", "Goniotomy", "Fistulizing operation", "Trabelectomy"], "correct": 0, "explanation": "Capsulectomy is a LENS/cataract procedure, not a glaucoma one, so it is the odd one out. Goniotomy, fistulizing operations, and trabeculectomy are all glaucoma surgeries. Hint: glaucoma surgery targets the ANGLE/drainage (gonio-, trabecul-, fistula), not the lens capsule."}'),
  ('0f9b5021-2a','{"options": ["Layers of rod and cones", "Outer molecular layer", "Inner molecular layer", "Outer nuclear layer"], "correct": 3, "explanation": "The outer nuclear layer holds the cell bodies (nuclei) of the photoreceptors. The inner nuclear layer holds bipolar/horizontal/amacrine nuclei. Hint: OUTER nuclear = the OUTER cells'' nuclei = photoreceptors (rods/cones)."}'),
  ('9f136c5e-3w','{"options": ["Outer molecular layer", "Retinal pigment epithelium", "External limiting membrane", "Internal limiting membrane"], "correct": 3, "explanation": "The internal limiting membrane (ILM) is the innermost retinal layer, formed by Muller cell footplates, separating retina from vitreous. Hint: INTERNAL limiting membrane = the innermost boundary against the vitreous."}'),
  ('fbcd8bd0-2j','{"options": ["Layers of rod and cones", "Inner nuclear layer", "Inner molecular layer", "Outer nuclear layer"], "correct": 1, "explanation": "The inner nuclear layer contains the nuclei of bipolar, Muller, horizontal, and amacrine cells. Hint: pair with Q17, OUTER nuclear = photoreceptors, INNER nuclear = the bipolar/Muller/amacrine crowd."}'),
  ('4ee4aff2-2c','{"options": ["Layers of rod and cones", "Inner nuclear layer", "Inner molecular layer", "Inner plexiform layer"], "correct": 3, "explanation": "The inner plexiform layer is where bipolar axons synapse with ganglion cell dendrites. (''Plexiform'' = synaptic/wiring layer.) Hint: plexiform = a synapse layer; inner plexiform links bipolars to ganglion cells."}'),
  ('3cd18f35-21','{"options": ["Poptosis", "Panophthalmitis", "Chemosis", "Hypopyon"], "correct": 1, "explanation": "Panophthalmitis = inflammation of ALL coats of the eye plus intraocular contents (pan = all). Endophthalmitis spares the sclera/coats; hypopyon is just pus in the AC. Hint: PAN = whole eye inflamed, coats and all."}'),
  ('7ff6066b-53','{"options": ["Tuberculosis", "Rheumatoid disease", "Gout", "Toxoplasmosis"], "correct": 1, "explanation": "Rheumatoid (juvenile idiopathic arthritis / HLA-B27 spondyloarthropathy) causes acute anterior uveitis with fibrin (plastic iritis) in young patients. Hint: young patient + acute fibrinous anterior uveitis = a rheumatologic (HLA-B27/JIA) cause."}'),
  ('8b4433e1-4c','{"options": ["Tuberculosis", "Rheumatoid disease", "Leprosy", "Toxoplasmosis"], "correct": 2, "explanation": "Leprosy, its granulomatous anterior uveitis classically shows whitish ''iris pearls'' (nodules). Hint: iris PEARLS = leprosy, a near-pathognomonic sign."}'),
  ('bfc25ced-5y','{"options": ["Tuberculosis", "Rheumatoid disease", "Leprosy", "Toxoplasmosis"], "correct": 0, "explanation": "Tuberculosis, famously ''protean,'' presenting as granulomatous anterior uveitis with greasy mutton-fat keratic precipitates, iris nodules, and choroidal exudates/tubercles. Hint: ''protean'' + mutton-fat KPs + choroidal tubercles = TB."}'),
  ('ad57a806-6m','{"options": ["Amoebic Uveitis", "Histoplasmosis", "Foci of infection", "Nematode"], "correct": 1, "explanation": "Histoplasmosis (POHS), small peripheral punched-out chorioretinal scars (''histo spots'') with little pigment, and late macular involvement (with peripapillary changes). Hint: ''punched-out'' scars = presumed ocular histoplasmosis."}'),
  ('b075d2b8-1l','{"options": ["Coloboma", "Anisocoria", "Aniridia", "Aphakia"], "correct": 2, "explanation": "Aniridia = absence of the iris (a developmental anomaly). Coloboma is a notch/gap, anisocoria is unequal pupils, aphakia is no lens. Hint: an-IRID-ia = no iris."}'),
  ('456e78aa-5c','{"options": ["Benign melanoma", "Malignant melanoma", "Melanosarcoma", "Metastatic carcinoma"], "correct": 0, "explanation": "Benign melanoma (nevus), a stable, well-demarcated pigmented patch that may darken but does not grow. Growth or change would suggest malignant melanoma. Hint: flat, stable, well-defined pigment = benign nevus; enlarging/thick = malignant."}'),
  ('69755db0-3q','{"options": ["Rubella virus", "Herpes virus", "Measles virus", "Mumps virus"], "correct": 0, "explanation": "Rubella (German measles) in the first trimester causes congenital cataract (plus deafness and heart defects). Hint: first-trimester rubella = the classic congenital cataract virus."}'),
  ('8cdc5da6-5a','{"options": ["Discission", "Capsulectomy", "Phacoemulsification", "Lensectomy"], "correct": 2, "explanation": "Phacoemulsification, ultrasound vibration fragments the lens and the pieces are aspirated through a small incision. Hint: phaco = lens, emulsi = liquefy by ultrasound, then aspirate."}'),
  ('eab4757e-1w','{"options": ["Iris", "Ciliary body", "Choroid", "Retina"], "correct": 1, "explanation": "Ciliary body, anterior-uveal (iridocyclitis) inflammation is the most intense and symptomatic, given its rich vascularity and nerve supply. Some texts stress the choroid''s vascularity instead, so VERIFY. Hint: the anterior uvea (iris + ciliary body) drives the most severe, painful uveitis."}'),
  ('a5438fa5-5m','{"options": ["Granulomatous", "Non-granulomatous", "Purulent", "Non-purulent"], "correct": 2, "explanation": "Purulent (suppurative) inflammation, pyogenic bacteria or fungi introduced by perforation or blood-borne emboli produce pus. Hint: pus-forming organisms = purulent/suppurative."}'),
  ('f9dd8ca8-15','{"options": ["Anterior chamber angle", "Ciliary processes", "Schlemm’s canal", "Trabecular meshwork"], "correct": 1, "explanation": "Aqueous humor is produced by the ciliary processes (nonpigmented ciliary epithelium). Schlemm''s canal and the trabecular meshwork are DRAINAGE, not production. Hint: ciliary processes make it; the angle/TM/Schlemm drain it."}'),
  ('1fb0ac83-4h','{"options": ["Secondary open angle", "Primary open angle", "Secondary angle closure", "Primary angle closure"], "correct": 3, "explanation": "Primary angle closure, the peripheral iris blocks the angle so aqueous cannot reach the trabecular meshwork, with no other causative disease. Hint: ''angle abnormality blocking flow TO the meshwork'' with no other disease = primary angle closure."}'),
  ('216e91ca-1f','{"options": ["Secondary open angle", "Primary open angle", "Secondary angle closure", "Primary angle closure"], "correct": 2, "explanation": "Secondary angle-closure glaucoma, posterior synechiae (iris stuck to lens) can cause pupillary block and iris bombe, closing the angle secondarily. Hint: synechiae are a disease PROCESS, so any glaucoma they cause is SECONDARY."}'),
  ('91b63eb4-49','{"options": ["Secondary open angle", "Primary open angle", "Secondary angle closure", "Primary angle closure"], "correct": 1, "explanation": "Primary open-angle glaucoma (POAG), the angle is open (aqueous can always reach it) yet IOP rises, with no precipitating disease. Hint: open angle + no other cause = PRIMARY open-angle."}'),
  ('2652aefc-4z','{"options": ["Central retinal artery occlusion", "Diabetic retinopathy", "Central retinal vein occlusion", "Retinitis pigmentosa"], "correct": 2, "explanation": "Central retinal vein occlusion, the ''blood and thunder'' fundus of dilated tortuous veins with widespread flame and blot hemorrhages. Hint: ''blood and thunder'' is the signature phrase for CRVO."}'),
  ('40f0b3b2-6w','{"options": ["Marfan’s syndrome", "Sturge-Weber syndrome", "Axenfeld syndrome", "Marchesani syndrome"], "correct": 2, "explanation": "Axenfeld(-Rieger) syndrome, autosomal dominant, affecting teeth, eyes, and umbilical/abdominal region, with posterior embryotoxon and angle anomalies causing glaucoma. Hint: teeth + eyes + umbilicus + posterior embryotoxon = Axenfeld-Rieger."}'),
  ('43a84707-3r','{"options": ["Hypertensive retinopathy", "Retinitis pigmentosa", "Diabetic retinopathy", "Central retinal artery occlusion"], "correct": 2, "explanation": "Diabetic retinopathy, microaneurysms, dot-and-blot hemorrhages, hard exudates, and neovascularization in the proliferative stage. Hint: microaneurysms + dot-blot + neovascularization = diabetes."}')
)
UPDATE question_reviews r
SET payload = r.payload || d.patch::jsonb
FROM d
WHERE r.question_id = d.qid;
